rawset(_G, "S_IncrementModernChain", function(eb, num, dedTimer)
	num = $ or 1
	dedTimer = $ or 0
	local prevCombo = eb.enemyComboTimer or 0
	eb.enemyCombo = $!=nil and ($+num) or num
	eb.player.trickscore = $+100
	if not dedTimer
		if P_IsObjectOnGround(eb)
			eb.enemyComboPreTimer = max($ or 0,TICRATE+prevCombo)
		else
			eb.enemyComboPreTimer = max($ or 0, (TICRATE/4)+prevCombo)
		end
	else
		eb.enemyComboPreTimer = max($or 0,dedTimer+prevCombo)
	end
	eb.enemyComboTimer = 0
	eb.HUDEnemyTimer = 5
	eb.HUDEnemyTimerFade = 0
	if eb.enemyCombo == num
		eb.HUDEnemyTimerInit = 21
	else
		eb.HUDEnemyTimerInit = 0
	end
end)

local function S_EndCombo(eb)
	if eb.enemyCombo
		CONS_Printf(eb.player, eb.enemyCombo + " Chain!")
		if eb.enemyCombo >= 10
			local things = {sfx_hoop1, sfx_hoop2, sfx_hoop3, sfx_hidden}
			S_StartSound(eb, things[min(40, eb.enemyCombo)/10], player)
		end
		eb.storedEnemyCombo = eb.enemyCombo
		eb.HUDEnemyTimerFade = 10
		eb.enemyCombo = 0
		eb.enemyComboTimer = 0
		eb.enemyComboPreTimer = 0
		eb.HUDEnemyTimer = 0
		eb.HUDEnemyTimerInit = 0
		local addPoints = min(1500,eb.storedEnemyCombo)
		eb.player.chainPointsTimer = $ and $ + addPoints or addPoints 
	end
end

local function FireSonicFireSpawn(player)
	if player and player.mo
		local fire = P_SpawnMobjFromMobj(player.mo,
			P_RandomRange(-20, 20)*player.mo.scale,
			P_RandomRange(-20, 20)*player.mo.scale,
			P_RandomRange(10, 60)*player.mo.scale,
			MT_THOK)
		fire.flags = $|MF_NOCLIPTHING|MF_NOBLOCKMAP
		fire.state = S_FIRESONICFLAME
		fire.blendmode = AST_ADD
		fire.frame = P_RandomRange(A, J) --|FF_TRANS60
		fire.scale = $/2
	end
end
			

local function InDeathAnimation(mo)
  local state = mo.info.deathstate
  while state
    if mo.state == state
      return true
    end
    state = states[state].nextstate
  end
end

