local function FixedLerp(a, b, w)
    return FixedMul((FRACUNIT - w), a) + FixedMul(w, b)
end	

local currentstarcolor, currentstarcolor2 = 0,0
addHook("ThinkFrame", do
	if (gamestate!=GS_LEVEL) return end --
	currentstarcolor = $ + 2
	if currentstarcolor > #starcolors or not starcolors[currentstarcolor]
		currentstarcolor = 1
	end
	
	skincolors[SKINCOLOR_RAINBOW].ramp = starcolors[currentstarcolor]
	
	currentstarcolor2 = $ + 6
	if currentstarcolor > #starcolors or not starcolors[currentstarcolor2]
		currentstarcolor2 = 1
	end
	skincolors[SKINCOLOR_HOMINGRAINBOW].ramp = starcolors[currentstarcolor2]
	local numToRemove = #mobjsToRemove
	while numToRemove
		local mo = table.remove(mobjsToRemove)
		if mo.valid
			P_RemoveMobj(mo)
		end
		numToRemove = $ - 1
	end
	
	//Stretch.lua by NeonSRB2
	for p in players.iterate
		if not (p.mo and p.mo.valid) continue end --
		
		//Ring Sound code from TrickyTex with minor help from Tatsuru
		if p.ringseq==nil or p.ringseq then p.ringseq = 0 end //init the ring sequencer, but it can only be 0,1, or 2.
		if p.ringdif==nil then p.ringdif = 0 end --GS: This one doesn't seem to get used? At least not in ModernSonic.lua
		
		if (p.mo.skin!="modernsonic") continue end --
		if p.jt == nil then
			p.jt = 0
			p.jp = false
			p.sp = false
			p.tk = false
			p.tr = false
		elseif p.jt > 0 then
			p.jt = p.jt - 1
		elseif p.jt < 0 then
			p.jt = p.jt + 1
		end
		if (p.mo.state == S_PLAY_TRICKEND or p.mo.state == S_PLAY_TRICK_3 or p.mo.state == S_PLAY_BOREDOM)
		and (p.prevstate != p.mo.state) then
			p.jt = 3
		elseif p.jumptimer == 4
		and p.mo.state == S_PLAY_JUMP
		and not (p.powers[pw_carry])
			p.jt = 3
		end
		p.prevstate = p.mo.state
		
		p.maths = p.jt*FRACUNIT
		p.maths = p.maths / 10
		p.mo.spriteyscale = p.maths + FRACUNIT
		
		
		p.maths = p.jt*p.spinheight
		if p.mo.state != S_PLAY_ROLL then
			p.maths = p.jt*p.height
		end
		p.maths = p.maths / 20
		p.mo.spriteyoffset = -1*p.maths
		
		p.maths = p.jt*FRACUNIT
		p.maths = p.maths / 10
		p.maths = p.maths*-1
		p.mo.spritexscale = p.maths + FRACUNIT


		if not (p.manualdrifting)
			if (p.pflags & PF_ANALOGMODE) and not (p.pflags & PF_DIRECTIONCHAR)
			or not (p.pflags & PF_ANALOGMODE)
				p.mimicangle = R_PointToAngle2(0,0, p.mo.momx, p.mo.momy)
			else
				p.mimicangle = p.drawangle
			end
			--p.mimicangle = p.bsoldanalog and p.drawangle or p.mo.angle
		end
		if p.manualdrifting
			if (p.pflags & PF_ANALOGMODE) and not (p.pflags & PF_DIRECTIONCHAR)
				p.cmd.angleturn = p.mimicangle>>16
			elseif (p.pflags & PF_ANALOGMODE) and (p.pflags & PF_DIRECTIONCHAR)
				p.rememberanalog = 1
				p.pflags = $ & ~PF_ANALOGMODE
			elseif not (p.pflags & PF_ANALOGMODE)
				if (p.modernmenu.contents[2][6].value == 0 or (p.modernmenu.contents[2][6].value == 2 and (p.boosting))) -- Drift
					p.mo.angle = p.mimicangle
				end
				if (p.modernmenu.contents[2][6].value == 1 or (p.modernmenu.contents[2][6].value == 2 and not (p.boosting))) -- Drift
					local angdiff = p.mimicangle - p.mo.angle
					local AFIXED = AngleFixed(angdiff/FU) --GS: So we only have to calculate it once.
					local sidemove = (p.cmd.sidemove*FU)/10
					local ATURN
					if p.cmd.sidemove > 0
						ATURN = min(sidemove,p.angleturn*FU)
					else
						ATURN = max(sidemove,p.angleturn*FU)
					end
					if ATURN==nil 
						ATURN = p.cmd.angleturn 
					end
					ATURN = abs($)
					if ((AFIXED > 10) or (AFIXED < 10 and p.driftdirection == 1))
					and (AFIXED <= 180)
						if AFIXED <= 22
							p.mo.angle = $ + (FixedAngle(ATURN))
						elseif AFIXED < 40
							p.mo.angle = $ + (FixedAngle(ATURN)) + (FixedAngle(ATURN)) + FixedAngle(1*FU)
						elseif AFIXED < 60
							p.mo.angle = $ + (FixedAngle(ATURN)) + (FixedAngle(ATURN)) + FixedAngle(2*FU)
						elseif AFIXED < 80
							p.mo.angle = $ + (FixedAngle(ATURN)) + (FixedAngle(ATURN)) + FixedAngle(3*FU)
						elseif AFIXED < 100
							p.mo.angle = $ + (FixedAngle(ATURN)) + (FixedAngle(ATURN)) + FixedAngle(4*FU)
						elseif AFIXED < 120
							p.mo.angle = $ + (FixedAngle(ATURN)) + (FixedAngle(ATURN)) + FixedAngle(5*FU)
						else
							p.mo.angle = $ + (FixedAngle(ATURN)) + (FixedAngle(ATURN)) + FixedAngle(6*FU)
						end	
					elseif ((AFIXED < 23592946) or (AFIXED > 23592946 and p.driftdirection == -1))
					and (AFIXED > 180)
						if AFIXED >= 23592934
							p.mo.angle = $ - (FixedAngle(ATURN))
						elseif AFIXED > 23592935
							p.mo.angle = $ - (FixedAngle(ATURN)) - (FixedAngle(ATURN)) - FixedAngle(1*FU)
						elseif AFIXED > 23592916
							p.mo.angle = $ - (FixedAngle(ATURN)) - (FixedAngle(ATURN)) - FixedAngle(2*FU)
						elseif AFIXED > 23592996
							p.mo.angle = $ - (FixedAngle(ATURN)) - (FixedAngle(ATURN)) - FixedAngle(3*FU)
						elseif AFIXED > 23592976
							p.mo.angle = $ - (FixedAngle(ATURN)) - (FixedAngle(ATURN)) - FixedAngle(4*FU)
						elseif AFIXED > 23592956
							p.mo.angle = $ - (FixedAngle(ATURN)) - (FixedAngle(ATURN)) - FixedAngle(5*FU)
						else
							p.mo.angle = $ - (FixedAngle(ATURN)) - (FixedAngle(ATURN)) - FixedAngle(6*FU)
						end	
					end
				end
			end
		elseif p.rememberanalog
			p.pflags = $|PF_ANALOGMODE
			p.rememberanalog = nil
		end
	end
end)

--BLOOPS TODO: TRICKALT
local function DoTrickPose(mo, type)
	if type == 1
		mo.state = S_PLAY_TRICK_1 --trickposes[P_RandomRange(1, 19)]
	else
		mo.state = S_PLAY_TRICK_2 --trickposes[P_RandomRange(20, 36)]
		mo.player.jt = 4
	end
end

rawset(_G, "HandleHomingEnd", function(mo, arg1)
	local player = mo.player
	if player.cmd.sidemove == 0 and player.cmd.forwardmove == 0
		if arg1 == 1
			P_InstaThrust(player.mo, player.mo.angle, -3*player.mo.scale)
		elseif arg1 == 2
			P_InstaThrust(player.mo, R_PointToAngle2(player.mo.x, player.mo.y, player.rettarget.x, player.rettarget.y), -30*player.mo.scale)
		elseif arg1 == nil or arg1 == 0
			P_InstaThrust(player.mo, player.mo.angle, 0)
		end
	else
		if mo.player.powers[pw_shield] == SH_ATTRACT and not (mo.player.powers[pw_super])
			mo.momx,mo.momy = $*3/5,$*3/5
		else
			mo.momx,mo.momy = $/4,$/4
		end
	end
	P_SetObjectMomZ(mo, ((mo.eflags & MFE_UNDERWATER) and 5 or 10)<<16) //NOTE: P_SetObjectMomZ already takes into account scale!!
	
	if player.rettarget and player.rettarget.valid and not (player.rettarget.flags & MF_SPRING)
		local boss = player.rettarget
		if boss.flags & MF_BOSS
			if boss.health == boss.info.spawnhealth
				table.insert(player.bossperfect, 1)
				boss.perfectID = #player.bossperfect
			end
			if player.doubledamage == true
				player.boostshake = 8
			end
		end
		if player.doubledamage == true
			local INVULNTIME = 5
			if player.rettarget and player.rettarget.valid
				if (player.rettarget.type==MT_EGGMAN_BOX) or (player.rettarget.type==MT_EGGMAN_GOLDBOX)
					INVULNTIME = 22
				end
				if (player.rettarget.health > 1)
					P_DamageMobj(player.rettarget, mo, nil)
					P_DamageMobj(player.rettarget, mo, nil)
				end
			end
			player.trickable = true
			player.doubledamage = false
			player.phinvultime = INVULNTIME
			P_SetObjectMomZ(mo, 2*FU, true)
		end
		player.mo.modernjetspeed = 43*player.mo.scale
	end
	player.pflags = $ & ~(PF_THOKKED|PF_STARTJUMP)
	if player.modernmenu.contents[7][3].value==1 -- Poses 
		DoTrickPose(mo, 1)
	else
		mo.state = S_PLAY_TRICKALT_1
	end		
	player.customhoming = 0
	player.homingacceltimer = TICRATE
	player.traillag = 15
end)

local function ModernLockOn(player) 
	local twod = (twodlevel or player.mo.flags2 & MF2_TWOD)
	local ringdist, span
	ringdist = 1200*FU
	span = (ANGLE_45+ANGLE_22h)

	local maxdist = FixedMul(ringdist, player.mo.scale)
	local closestdist = 0
	local closestmo = nil
	searchBlockmap("objects",function(pmo,mo)
		if (mo.flags & MF_NOCLIPTHING) return end
		if (mo.health <= 0) return end -- dead

		if mo.player
			return -- not a valid target
		end
		if not (mo.flags & (MF_ENEMY|MF_BOSS|MF_MONITOR|MF_SPRING)) --None of these!
		and not (mo.type == MT_NIGHTSBUMPER) and not (mo.type == MT_BIGMINE) and not (mo.type == MT_PULLEYHANDLE)
		--and (!((mo.flags & (MF_ENEMY|MF_BOSS|MF_MONITOR)) or (mo.type == MT_NIGHTSBUMPER) or (mo.flags & MF_SPRING)) == !(mo.flags2 & MF2_INVERTAIMABLE)) -- allows if it has the flags desired XOR it has the invert aimable flag
			return -- not a valid target
		end
		if (mo.flags2 & (MF2_DONTDRAW|MF2_FRET))
		or (mo == pmo)
		or mo.type == MT_METALSONIC_BATTLE and not (mo.flags & MF_SHOOTABLE) and mo.state ~= S_METALSONIC_FLOAT
			return
		end
		//CTF monitor 
		if mo.type == MT_RING_REDBOX and not (G_GametypeHasTeams() and player.ctfteam == 1) then return end
		if mo.type == MT_RING_BLUEBOX and not (G_GametypeHasTeams() and player.ctfteam == 2) then return end

-- 		if (mo.type == MT_PLAYER) return end -- Don't chase after other players!
		--if (mo.type == MT_TARGETDUMMY) return end //We won't be relying on this for player detection
		--if (mo.player and (B.MyTeam(player,mo.player) or mo.player.spectator)) then return end //Disallow targeting teammates


		//Do angle/distance checks
		local zdist = (pmo.z + pmo.height/2) - (mo.z + mo.height/2)
		local dist = P_AproxDistance(pmo.x-mo.x, pmo.y-mo.y)
		//CBW: 	Made the angle checks their own locals, for readability purposes
		//		I also unsigned the angle checks, which appears to correct failed OutOfBounds checks above the player.
		local xyz_angle = abs(R_PointToAngle2(0, 0, dist, zdist))
		local xy_angle = abs(R_PointToAngle2(
				pmo.x + P_ReturnThrustX(pmo, pmo.angle, pmo.radius),
				pmo.y + P_ReturnThrustY(pmo, pmo.angle, pmo.radius),
				mo.x, mo.y
			) - pmo.angle)
			
			
		dist = P_AproxDistance(dist, zdist)
		if (dist > maxdist)
			return -- out of range
		end
-- 		print("\x82!!!VERT","# Span check: "..xyz_angle/ANG1,"# Limit: "..span*2/ANG1,"#Within Range: "..tostring(abs(xyz_angle) <= span))
		if (xyz_angle > span)
			return -- Don't home outside of desired angle!
		end
		if mo.player
			return
		end


		if (twod and abs(pmo.y-mo.y) > pmo.radius)
			return -- not in your 2d plane
		end

		if ((closestmo and closestmo.valid) and (dist > closestdist))
			return
		end
-- 		print("\x82!!!HORZ","# Span check: "..xy_angle/ANG1,"# Limit: "..span*2/ANG1,"#Within Range: "..tostring(abs(xy_angle) <= span))
		if (xy_angle > span)
			return -- behind back
		end

		if (P_CheckSight(pmo, mo) == false)
			return -- out of sight
		end
		if AngleFixed(xyz_angle)/FU > 50
			return
		end
		closestmo = mo
		closestdist = dist
		
	end,player.mo,player.mo.x-maxdist,player.mo.x+maxdist,player.mo.y-maxdist,player.mo.y+maxdist)	
	return closestmo
end

local function HeightCheck(mobj, thing, modifier)
	if ((mobj.z <= thing.z + thing.height + modifier)
	and (thing.z <= mobj.z + mobj.height + modifier))
		return true --
	end
end

local function hitscan(mobj)
	if mobj and mobj.valid
		mobj.flags2 = $|MF2_RAILRING
		for i = 1, 120
			if (P_RailThinker(mobj)) then
                break
-- 			else
-- 				local gs = P_SpawnMobjFromMobj(mobj,0,0,0,MT_THOK)
-- 				gs.tics = 2
-- 				gs.color = SKINCOLOR_SUPERSILVER1
			end
		end
	end
end
addHook("MobjThinker", hitscan, MT_HOMING_ATTACK_DETECTOR)

local IGM = {} --Ignore these guys.
IGM[MT_PLAYER] = true
IGM[MT_RING] = true
IGM[MT_FLINGRING] = true
IGM[MT_COIN] = true
IGM[MT_FLINGCOIN] = true
IGM[MT_CRUSHCLAW] = true

addHook("MobjMoveCollide", function(mobj, thing)
	if mobj and mobj.target and thing and (IGM[thing.type]!=true) and HeightCheck(mobj, thing, 0) and mobj.target.player
		mobj.target.player.rettarget = thing return true --
	end
end, MT_HOMING_ATTACK_DETECTOR)

local function DoSpinDashDust(player, speed) // From the source code!
	local mo = player.mo
	local prandom = {}
	for i = 0, (leveltime%7) >> 1 // 1, 2, 3 or 4 particles
		local particle = P_SpawnMobjFromMobj(mo, 0, 0, 0, MT_SPINDUST)

		if mo.eflags & (MFE_TOUCHWATER|MFE_UNDERWATER) // overrides fire version
			particle.state = S_SPINDUST_BUBBLE1
		elseif player.powers[pw_shield] == SH_ELEMENTAL
			particle.state = S_SPINDUST_FIRE1
		end

		particle.target = mo
		particle.destscale = (mo.destscale << 1)/3
		P_SetScale(particle, particle.destscale)
		if mo.eflags & MFE_VERTICALFLIP // readjust z position if needed
			particle.z = mo.z + mo.height - particle.height
		end
		prandom[0] = P_RandomFixed()<<2 // P_RandomByte()<<10
		prandom[1] = P_RandomRange(-30, 30) // P_RandomRange(-ANG30/FRACUNIT, ANG30/FRACUNIT)*FRACUNIT
		prandom[2] = P_RandomFixed()<<3 // P_RandomByte()<<11
		P_SetObjectMomZ(particle, speed/50 + prandom[0], false)
		P_InstaThrust(particle,
		player.drawangle + prandom[1]*ANG1,
		-FixedMul(speed/12 + FRACUNIT + prandom[2], mo.scale))
		P_TryMove(particle, particle.x + particle.momx, particle.y + particle.momy, true)
	end
end

local function HandleHoming(player)
	if player.mo and player.mo.valid and player.mo.skin == "modernsonic"
		player.usedhomingattack = true
		player.customhoming = max($-1, 0)
		player.doublejumped = false
		player.jumptimer = 4
		if player.rettarget and player.rettarget.valid and player.rettarget.health and player.rettarget.flung ~= true
			player.pflags = $|PF_JUMPED
			if player.mo.state != S_PLAY_JUMP and player.customhoming
				player.mo.state = S_PLAY_JUMP
			end
			player.drawangle = player.mo.angle
			local zdist = (P_MobjFlip(player.mo) == 1) and (player.rettarget.z + player.rettarget.height) - (player.mo.z + player.mo.height) or (player.rettarget.z - player.mo.z)
			local dist = P_AproxDistance(P_AproxDistance(player.rettarget.x - player.mo.x, player.rettarget.y - player.mo.y), zdist)
			
			local theFasts = 70*player.mo.scale
			
			if player.powers[pw_shield] == SH_ATTRACT
			and not (player.powers[pw_super])
				theFasts = $ + 30*player.mo.scale
			end
			if player.doubledamage
				theFasts = $ + 40*player.mo.scale
			end
			if (player.powers[pw_shield] & SH_FIREFLOWER)
				theFasts = $+200*player.mo.scale
			end
			
			player.fastfastX = FixedMul(cos(player.mo.angle), theFasts)
			player.fastfastY = FixedMul(sin(player.mo.angle), theFasts)
			
			player.mo.momx = FixedMul(FixedDiv(player.rettarget.x-player.mo.x, dist), theFasts) or 1
			if not twodlevel
			and not (player.mo.flags2 & MF2_TWOD)
				player.mo.momy = FixedMul(FixedDiv(player.rettarget.y-player.mo.y, dist), theFasts) or 1
			end
			player.mo.momz = FixedMul(FixedDiv(zdist, dist), theFasts)
			player.mo.angle = R_PointToAngle2(player.mo.x, player.mo.y, player.rettarget.x, player.rettarget.y)
		end		
		if not (player.rettarget and player.rettarget.valid and player.rettarget.health)
		or player.rettarget.state==S_METALSONIC_VECTOR
		or player.powers[pw_carry]
		or (player.rettarget and player.rettarget.valid 
		and not (player.rettarget.flags & MF_SPRING) 
		and not (player.rettarget.type == MT_PULLEYHANDLE) 
		and not (player.rettarget.type == MT_NIGHTSBUMPER) 
		and not (player.rettarget.flags & MF_SHOOTABLE) 
		and not (player.rettarget.flags2 & MF2_INVERTAIMABLE) 
		and not (player.rettarget.type == MT_METALSONIC_BATTLE))
			HandleHomingEnd(player.mo, 0)
		end
		if P_PlayerInPain(player)
			player.customhoming = 0
		end
	end
end

local function SpawnBoostEnergy(mo, boostenergynumber, target)
	for i = 1, boostenergynumber
		local boostenergy = P_SpawnMobjFromMobj(mo, 0, 0, 0, MT_BOOSTENERGY)
		if target == 1
			boostenergy.target = mo.target
		elseif target == 0
			boostenergy.target = mo
		end
		boostenergy.boostchasetimer = 225
		boostenergy.color = SKINCOLOR_SKY
		boostenergy.momx = ((P_RandomRange(-10, 10)*boostenergy.target.scale)*P_MobjFlip(boostenergy.target))
		boostenergy.momy = ((P_RandomRange(-10, 10)*boostenergy.target.scale)*P_MobjFlip(boostenergy.target))
		boostenergy.momz = ((P_RandomRange(10, 15)*boostenergy.target.scale)*P_MobjFlip(boostenergy.target)+boostenergy.target.momz)
		boostenergy.scale = boostenergy.target.scale*2
		boostenergy.frame = A|FF_TRANS80|FF_FULLBRIGHT
		if not boostenergy.target.player.boostenergy then boostenergy.target.player.boostenergy = {} end
		table.insert(boostenergy.target.player.boostenergy,boostenergy)
	end
end


