local function PlayModernSound(player, soundtype)
  if player.modernsound
	return
  end
  local soundlist = MODERN_SOUNDS[soundtype] -- get the list of sounds for the sound type
  local sound = soundlist[P_RandomKey(#soundlist) + 1] -- choose a sound from the list
  if sound == sfx_silenc -- don't play a sound if silence is picked
    return
  end
  if player.mo.eflags & MFE_UNDERWATER
	return
  end
  local cooldown = soundlist
  S_StartSound(player.mo, sound)
  player.modernsound = MODERN_SOUNDS_COOLDOWNS[soundtype].cooldown
end

local function PlayEnemySound(mobj, soundtype)
  local soundlist = ENEMY_SOUNDS[soundtype] -- get the list of sounds for the sound type
  local sound = soundlist[P_RandomKey(#soundlist) + 1] -- choose a sound from the list
  S_StartSound(mobj, sound)
end

local function SpawnActionDust(mo, var)
	if var == 1
		for i = 1, 16 //spawn some dust yee
			local dust = P_SpawnMobj(mo.x, mo.y, mo.z + (mo.eflags & MFE_VERTICALFLIP and 4*mo.scale or 0), mo.eflags & (MFE_UNDERWATER | MFE_TOUCHWATER) and MT_MEDIUMBUBBLE or MT_PARTICLE)
			dust.fuse = TICRATE/4
			dust.scale = mo.scale
			dust.destscale = mo.scale/8
			dust.eflags = mo.eflags & MFE_VERTICALFLIP
			P_InstaThrust(dust, i*ANGLE_22h, 6*mo.scale)
			dust.momz = -2*P_MobjFlip(mo)*mo.scale
			dust.frame = $|FF_TRANS60
		end
	elseif var == 2
		local angle = mo.player.drawangle + ANGLE_90
		for i = 1, 16
		  local hthrust = FixedMul(cos(i*ANGLE_22h), 6*mo.scale) -- horizontal thrust
		  local vthrust = FixedMul(sin(i*ANGLE_22h), 6*mo.scale) -- vertical thrust
		  local dust = P_SpawnMobjFromMobj(mo, 0, 0, mo.height >> 1, MT_PARTICLE)
		  dust.angle = angle
		  dust.fuse = TICRATE >> 2
		  dust.angle = angle
		  dust.destscale = mo.scale >> 3
		  P_InstaThrust(dust, dust.angle, hthrust)
		  dust.momz = vthrust
		  dust.frame = $|FF_TRANS60
		end
	end
end

local client
local function screenshake(v, player)
client = player
	end
hud.add(screenshake)

// This handles turning super.
local function become_super(player)
	// Sanity check
	if player.can_super ~= true return end
	if player.superanim ~= 0    return end

	local canuse = true

	// Failure conditions!
	// Cannot turn super in enclosed spaces
	if player.mo.ceilingz - player.mo.floorz < P_GetPlayerHeight(player)
		canuse = false
	end

	// Error sound
	if not canuse
		return
	end

	player.charflags = $1 | SF_SUPER
	player.active_supertrans = true
end


//I'll be honest, I don't know how this works. But let's just be glad it does
local function SpawnMobjFrom(mobj, xofs, yofs, zofs, newtype)
	xofs = FixedMul(xofs, mobj.scale)
	yofs = FixedMul(yofs, mobj.scale)
	zofs = FixedMul(zofs, mobj.scale)

	local newobj = P_SpawnMobj(mobj.x+xofs, mobj.y+yofs, mobj.z+zofs, newtype)
	if (mobj.eflags & MFE_VERTICALFLIP)
		local elementheight = FixedMul(newobj.info.height, mobj.scale)

		newobj.eflags = $1 | MFE_VERTICALFLIP
		newobj.flags2 = $1 | MF2_OBJECTFLIP
		newobj.z = mobj.z + mobj.height - zofs - elementheight
	end
	newobj.destscale = mobj.destscale
	P_SetScale(newobj, mobj.scale)
	return newobj
end

local function FixedRandom(int1, int2)
	return (P_RandomRange(int1, int2)*FU)
end


rawset(_G, "SpawnFaker", function(enemy, p)
	if not enemy.flung
		enemy.flung = true
		if p.powers[pw_shield] == SH_ARMAGEDDON
			enemy.explode = true
		end
		local speedy = (abs(p.mo.momy) > 2*FU) and p.mo.momy or 2*FU * (p.mo.momy/abs(p.mo.momy+1))
		local speedx = (abs(p.mo.momx) > 2*FU) and p.mo.momx or 2*FU * (p.mo.momx/abs(p.mo.momx+1))
		local speedz = (abs(p.mo.momz) > 3*FU) and p.mo.momz or 3*FU * (p.mo.momz/abs(p.mo.momz+1))
		if p.fastfastX	
			speedz = (10*FU + abs(speedz))*P_MobjFlip(enemy)
			speedx = p.fastfastX
			speedy = p.fastfastY
			p.fastfastX = 0
			p.fastfastY = 0
		end
		if p.powers[pw_super]  and p.speed < FU*2
			speedx = FixedRandom(-10, 10)
			speedy = FixedRandom(-10, 10)
			speedz = FixedRandom(5, 10)*P_MobjFlip(enemy)
		end
		if p.boosting 
			speedz = $ + p.speed/5
		end
		if p.powers[pw_super] 
			speedz = $ + p.speed/5
			speedy = $ * 3
			speedx = $ * 3
			speedz = $ * 3
		end
		if p.doubledamage
			speedy = $ * 3
			speedx = $ * 3
			speedz = $ * 3
		end
		local ang = R_PointToAngle2(p.mo.x, p.mo.y, enemy.x, enemy.y)
		local fake = P_SpawnMobj(enemy.x,enemy.y,enemy.z, MT_FOUNDYOUFAKER)
		fake.target = p.mo
		fake.state = S_INVISIBLE
		fake.flags = $|MF_NOCLIPTHING
		
		fake.switch = P_RandomChance(FU/2) and 1 or -1
		fake.targetenemy = enemy
		fake.dontkillthisthing = 5
		fake.targetplayer = p.mo
		fake.random = FixedRandom(1, 15)
		fake.random2 = FixedRandom(-15, 15)
		fake.storedz = FU
		fake.angle = enemy.angle
		fake.rollangle = enemy.rollangle
		fake.width = enemy.width
		fake.height = enemy.height
		enemy.flags2 = $ & ~MF2_FRET
		enemy.fakerthing = fake
		P_InstaThrust(fake,ang+FixedAngle(fake.random2), R_PointToDist2(0,0,speedx, speedy))
		fake.momz = (speedz + FixedRandom(-3, 10))*P_MobjFlip(enemy)
		PlayEnemySound(fake, 1)
		--P_SetObjectMomZ(fake, 30*FU, false)
	end
end)

local function FindMyColor(player, color, menunumber, effect)
	if player.mo and player.mo.valid
		if not player.powers[pw_super]
			if not menunumber
				return player.mo.color
			end
			if menunumber < 0
			or menunumber > 7
			or player.modernmenu.contents[8][menunumber].value == 0 -- Colors
				if player.mo.color == SKINCOLOR_UNLEASHED
					if effect == "srb2jump"
						return SKINCOLOR_SAPPHIRE
					elseif effect == "unleashedjump"
						return SKINCOLOR_UNLEASHEDBOOST
					elseif effect == "colorsjump"
						return SKINCOLOR_DREAM
					elseif effect == "frontiersjump"
						return SKINCOLOR_CERULEAN
					elseif effect == "rushjump"
						return SKINCOLOR_COBALT
					elseif effect == "stomp"
						return SKINCOLOR_CERULEAN
					elseif effect == "boost1"
						return SKINCOLOR_SKY
					elseif effect == "boost2"
						return SKINCOLOR_CORNFLOWER
					elseif effect == "boost3"
						return SKINCOLOR_CORNFLOWER
					elseif effect == "slide"
						return SKINCOLOR_CYAN
					elseif effect == "gens"
						return SKINCOLOR_UNLEASHEDBOOST
					elseif effect == "rush"
						return SKINCOLOR_SAPPHIRE
					elseif effect == "colors"
						return SKINCOLOR_RAINBOW
					elseif effect == "forces"
						return SKINCOLOR_SAPPHIRE
					else
						return player.mo.color
					end
				else
					return player.mo.color
				end
			else
				return player.modernmenu.contents[8][menunumber].value -- Colors
			end
		else
			if player.mo.color == SKINCOLOR_SUPER_SUNFLOWER1
			or player.mo.color == SKINCOLOR_SUPER_SUNFLOWER2
			or player.mo.color == SKINCOLOR_SUPER_SUNFLOWER3
			or player.mo.color == SKINCOLOR_SUPER_SUNFLOWER4
			or player.mo.color == SKINCOLOR_SUPER_SUNFLOWER5
				return color
			else
				return player.mo.color
			end
		end
	end
end

// This function handles the Super Sonic animation!
function A_PreSuper(actor, var1, var2)
	if not actor.player return end
	local player = actor.player

	local ourskin = "modernsonic"
	if player.skin ourskin = player.skin end

	//P_ResetPlayer(player)
	player.superanim = $ + 1
	if player.superanim > 20
		player.superanim = $1 + 3
	end
	if player.superanim == 80
		if player.rings >= 50
			// We're officially "super" now
			player.charflags = $1 | SF_SUPER
			player.powers[pw_super] = 1
			player.charflags = $1 | SF_SUPER
			player.pflags = $|PF_JUMPED
			player.jumptimer = 4
			player.powers[pw_extralife] = 0
			player.powers[pw_sneakers] = 0
			player.powers[pw_invulnerability] = 0
			S_StartSound(NULL, sfx_mtrans)
			P_FlashPal(player, PAL_WHITE, 2)
			
			P_StartQuake(FU, TICRATE)
			local px = actor.x
			local py = actor.y
			local br = 525*FU
			searchBlockmap("objects", function(mo, found)
				if found.valid
				and (found.flags & MF_ENEMY) 
				and not found.flung
					SpawnFaker(found, mo.player)
					S_IncrementModernChain(actor)
				end
			end, actor, px-br, px+br, py-br, py+br)
			
			if not (player.mo.eflags & MFE_UNDERWATER)
			and player.mo.state ~= S_PLAY_BOREDOM
				if player.modernmenu.contents[6][1].value == 1 -- Voices
					if player.modernmenu.contents[6][2].value == 0
						S_StartSound(player.mo, sfx_supjsn)
					elseif player.modernmenu.contents[6][2].value == 1
						S_StartSound(player.mo, sfx_suprog)
					elseif player.modernmenu.contents[6][2].value == 2
						S_StartSound(player.mo, sfx_supryn)
					elseif player.modernmenu.contents[6][2].value == 3
						--S_StartSound(player.mo, sfx_supjun)
					elseif player.modernmenu.contents[6][2].value == 4
						if player.cmd.buttons & BT_TOSSFLAG
							S_StartSound(player.mo, sfx_perfeg)
						else
							S_StartSound(player.mo, sfx_flgood)
						end
					elseif player.modernmenu.contents[6][2].value == 5
						if player.cmd.buttons & BT_TOSSFLAG
							S_StartSound(player.mo, sfx_perfea)
						else
							S_StartSound(player.mo, sfx_goodj)
						end
					end
				end
			end
			return
		else
			P_FlashPal(player, PAL_MIXUP, 2)
			S_StartSound(player.mo, sfx_s3k66)
		end
	elseif player.superanim > 80
		local boostshockwave = P_SpawnMobjFromMobj(player.mo, 0, 0, 0, MT_BOOSTSHOCKWAVE)
		boostshockwave.target = player.mo
		boostshockwave.color = FindMyColor(player, SKINCOLOR_SUPERGOLD3)
		boostshockwave.scale = player.mo.scale
		boostshockwave.momx = player.mo.momx/2
		boostshockwave.momy = player.mo.momy/2
		boostshockwave.momz = player.mo.momz
		local superburst = P_SpawnMobjFromMobj(player.mo, 0, 0, 0, MT_THOK)
		superburst.state = S_SUPERBURST
		superburst.color = FindMyColor(player, SKINCOLOR_SUPERGOLD3)
		superburst.scale = actor.scale
		superburst.fuse = 16
		if actor.state ~= S_PLAY_BOREDOM
			actor.state = S_PLAY_MODERNTRANSFORM8
		else
			actor.state = S_PLAY_BOREDOM
		end
		for i = 1, 16
			local boom2 = P_SpawnMobjFromMobj(actor,
			P_RandomRange(-10, 10)*FRACUNIT,
			P_RandomRange(-10, 10)*FRACUNIT,
			P_RandomRange(-10, 10)*FRACUNIT,
			MT_THOK)
			boom2.fuse = TICRATE
			boom2.boomer = true --we'll attach a separate hook to this mobj
			P_InstaThrust(boom2, FixedAngle(P_RandomRange(0, 360)*FRACUNIT), P_RandomRange(1, 5)*FRACUNIT)
			boom2.momz = P_RandomRange(1, 5)*FRACUNIT*P_MobjFlip(boom2)
			boom2.flags = MF_NOCLIPHEIGHT|MF_NOCLIP
			boom2.destscale = 0
			boom2.blendmode = AST_ADD
			boom2.scale = actor.scale/5
			boom2.scalespeed = FRACUNIT/(TICRATE*2)
			boom2.color = FindMyColor(player, SKINCOLOR_SUPERGOLD3)
			boom2.state = S_SUPERBURST
		end
		--player.mo.state = $
		player.active_supertrans = false
		player.superanim = 0
		player.charability2 = skins[ourskin].ability2
		return
	end

	// Emeralds rotate around you
	local distsin = sin(FixedAngle((player.superanim*FRACUNIT/80)*180))
	local distance = 16*FRACUNIT + distsin*80

	local playerva = player.cmd.angleturn
	if ANGLE_90 > 16384 playerva = $1 << 16 end

	local angle, xofs, yofs, zofs, obj, obj2, obj3
	local tablelol = {}
	for i = 0, 6
		angle = (i * (103*FRACUNIT/2)) + player.superanim*20*FRACUNIT
		angle = FixedAngle(angle)
		xofs = FixedMul(sin(angle), distance)
		yofs = FixedMul(cos(angle), distance)
		zofs = FixedMul(cos(angle + (playerva + ANGLE_270)), distance>>2) + actor.height>>1
		obj = P_SpawnMobjFromMobj(actor, xofs, yofs, zofs, MT_FAKEEMMY)
		obj.frame = i | FF_FULLBRIGHT
		obj.scale = actor.scale/2
		tablelol[i] = obj
		
		obj2 = P_SpawnMobjFromMobj(actor, xofs, yofs, zofs, MT_FAKEEMMY)
		obj2.dispoffset = 2
		obj2.scale = actor.scale/2
		tablelol[i] = obj2
		
		obj3 = P_SpawnMobjFromMobj(actor, xofs, yofs, zofs, MT_FAKEEMMY)
		obj3.dispoffset = 2
		obj3.scale = actor.scale/2
		tablelol[i] = obj3
		if player.superanim >= 60
			obj2.frame = i | FF_FULLBRIGHT
			obj3.frame = i | FF_FULLBRIGHT
			obj2.colorized = true
			obj3.colorized = true
			obj2.color = SKINCOLOR_WHITE
			obj3.color = SKINCOLOR_WHITE
		elseif player.superanim >= 55
			obj2.frame = i | FF_FULLBRIGHT | FF_TRANS20
			obj3.frame = i | FF_FULLBRIGHT | FF_TRANS20
		elseif player.superanim >= 50
			obj2.frame = i | FF_FULLBRIGHT | FF_TRANS30
			obj3.frame = i | FF_FULLBRIGHT | FF_TRANS30
		elseif player.superanim >= 45
			obj2.frame = i | FF_FULLBRIGHT | FF_TRANS40
			obj3.frame = i | FF_FULLBRIGHT | FF_TRANS40
		elseif player.superanim >= 40
			obj2.frame = i | FF_FULLBRIGHT | FF_TRANS50
			obj3.frame = i | FF_FULLBRIGHT | FF_TRANS50
		elseif player.superanim >= 35
			obj2.frame = i | FF_FULLBRIGHT | FF_TRANS60
			obj3.frame = i | FF_FULLBRIGHT | FF_TRANS60
		elseif player.superanim >= 30
			obj2.frame = i | FF_FULLBRIGHT | FF_TRANS70
			obj3.frame = i | FF_FULLBRIGHT | FF_TRANS70
		elseif player.superanim >= 25
			obj2.frame = i | FF_FULLBRIGHT | FF_TRANS80
			obj3.frame = i | FF_FULLBRIGHT | FF_TRANS80
		end
		if player.superanim > 25
			obj2.blendmode = AST_ADD
			obj3.blendmode = AST_ADD
			
		else
			obj2.frame = i | FF_FULLBRIGHT
			obj3.frame = i | FF_FULLBRIGHT
		end
			

		if player.superanim > 1
			obj.tics = 1
			obj2.tics = 1
		end
	end
	return tablelol //yes hi i need this info
end

local function GiveBoost(post, mo)
	local player = mo.player
	//Activate starpost once
	if (post.health > player.starpostnum+1 and gametype & GT_RACE) then return end
	if player.starpostnum < post.health
	and mo.skin == "modernsonic"
	and not (mo.player.bot)
		
		post.target = mo
		SpawnBoostEnergy(post, 12, 1)
		S_StartSound(post, sfx_chkbst)
		S_IncrementModernChain(mo, 3, 100)
	end
end
addHook("TouchSpecial", GiveBoost, MT_STARPOST)

//Creates a new function that the lockon reticle will use.
function A_ReticleThinker (actor, var1, var2)
	//Use a variable to determine if the actor has a tracer
	if not actor.lifetime
		actor.lifetime = 6
	end
	actor.hastracer = false
	if (actor.tracer)
	and (actor.tracer.valid) then
		actor.hastracer = true
	end
	//If the actor has a target...
	if (actor.target)
	and (actor.target.valid) then
		if actor.scale > (FU*3)/4
			actor.scalespeed = FixedDiv(FU,(actor.scale/2))
			local transparencies = {0, FF_TRANS20, FF_TRANS40, FF_TRANS60, FF_TRANS80, FF_TRANS90}//im tired
			actor.frame = A|transparencies[actor.lifetime]|FF_FULLBRIGHT
			actor.lifetime = $-1 or 1
		else
			actor.scalespeed = FU/12
			actor.frame = A|FF_FULLBRIGHT
		end
		//Turn visible
		//actor.flags2 = $ & ~MF2_DONTDRAW
		//MORE LIKE
		//NEVER
		//Follow it
		local chasecam = CV_FindVar("chasecam")
		if actor.tracer
		and actor.tracer.player == displayplayer
		and not chasecam.value
			--actor.flags2 = $ & ~MF2_DONTDRAW
		end
		if actor.target.flags & MF_BOSS	
			if actor.target.type == MT_CYBRAKDEMON
				P_MoveOrigin(actor, actor.target.x, actor.target.y, actor.target.z+actor.target.height/2)
			else
				P_MoveOrigin(actor, actor.target.x, actor.target.y, actor.target.z+actor.target.height/3)
			end
		else
			P_MoveOrigin(actor, actor.target.x, actor.target.y, actor.target.z+actor.target.height/2)
		end
		actor.momx = 0
		actor.momy = 0
		actor.momz = 0
		//Copy its attributes
		//actor.scale = actor.target.scale
		if actor.target.eflags & MFE_VERTICALFLIP then
			actor.flags2 = $|MF2_OBJECTFLIP // flip gravity!
		end
		//If tracer present, point towards it
		if actor.hastracer == true then
			local an = R_PointToAngle2(actor.x, actor.y, actor.tracer.x, actor.tracer.y)
			actor.angle = an
			if actor.target.flags & MF_BOSS	
				if actor.target.type == MT_CYBRAKDEMON
					P_MoveOrigin(actor, actor.x + 1*cos(an), actor.y + 1*sin(an), actor.z+actor.height/2)
				else
					P_MoveOrigin(actor, actor.x + 1*cos(an), actor.y + 1*sin(an), actor.z+actor.height/3)
				end
			else
				P_MoveOrigin(actor, actor.x + 1*cos(an), actor.y + 1*sin(an), actor.z+actor.height/2)
			end
			
		end
		local marker = actor //im too lazy for this shit
		marker.rollangle = $1-FixedAngle(FixedMul(20*FU, marker.scale))
		if marker.scale > FU*2
			marker.scalespeed = FU
		else
			marker.scalespeed = FU/6
		end
		if not marker.ring1
			marker.ring1 = P_SpawnMobjFromMobj(marker,0,0,0,MT_RETICLERING)
			marker.ring1.frame = A|FF_TRANS60|FF_FULLBRIGHT
			marker.ring1.scale = FU
			marker.ring1.color = SKINCOLOR_GREY
			marker.ring1.flags2 = $ | MF2_DONTDRAW
		else
			marker.ring1.flags2 = marker.flags2
			P_MoveOrigin(marker.ring1, marker.x, marker.y, marker.z+(0*FU))
			marker.ring1.momx, marker.ring1.momy, marker.ring1.momz = 0,0,0
			marker.ring1.fuse = 2
		end
		if not marker.ring2
			marker.ring2 = P_SpawnMobjFromMobj(marker,0,0,0,MT_RETICLERINGSMALL)
			marker.ring2.frame = B|FF_FULLBRIGHT
			marker.ring2.color = SKINCOLOR_WHITE
			marker.ring2.scale = (11*FU)/16
			marker.ring2.destscale = 0
			marker.ring2.scalespeed = FU/50
			marker.ring2.flags2 = $ | MF2_DONTDRAW
		else
			marker.ring2.flags2 = marker.flags2
			P_MoveOrigin(marker.ring2, marker.x, marker.y, marker.z+(2*FU))
			marker.ring2.momx, marker.ring2.momy, marker.ring2.momz = 0,0,0
			marker.ring2.fuse = 2
		end
		
		if marker.ring1.valid and marker.ring2.valid
		and marker.tracer and marker.tracer.valid
			if marker.ring2.scale < 37456 and marker.ring2.scale > 27316
				marker.ring1.frame = A|FF_FULLBRIGHT
				--marker.ring1.color = ColorOpposite(marker.tracer.player.reticlecolor)
				marker.ring1.color = marker.tracer.player.perfectringcolor 
				marker.tracer.player.perfectCapable = true
			else
				marker.ring1.frame = A|FF_TRANS60|FF_FULLBRIGHT
				marker.ring1.color = SKINCOLOR_GREY
				marker.tracer.player.perfectCapable = false
			end
		end
	else
		//If no target, turn invisible
		actor.flags2 = $|MF2_DONTDRAW
		//Follow tracer and copy its attributes if there is one
		if actor.hastracer == true then
			P_MoveOrigin(actor, actor.tracer.x, actor.tracer.y, actor.tracer.z)
			actor.momx = 0
			actor.momy = 0
			actor.momz = 0
			actor.scale = actor.tracer.scale
			if actor.tracer.eflags & MFE_VERTICALFLIP then
				actor.flags2 = $|MF2_OBJECTFLIP // flip gravity!
			end
		end
	end
end

//GENERATIONS BOOST
addHook("MobjThinker", function(mo)
	if not (mo and mo.valid) return end --
	if mo.target and mo.target.valid
		local p = mo.target.player
		if p.powers[pw_super]
		or p.mysticsuper
			mo.color = FindMyColor(p, SKINCOLOR_GOLDENROD)
		elseif p.powers[pw_shield] == SH_ELEMENTAL
			mo.color = SKINCOLOR_ORANGE		
		elseif p.powers[pw_shield] == SH_FLAMEAURA
		or p.firesonic
			mo.color = SKINCOLOR_KETCHUP		
		else
			mo.color = FindMyColor(p, SKINCOLOR_GOLDENROD, 1, "gens")
		end
		if not (mo.target.player.powers[pw_carry] == CR_GRINDRAIL)
			P_MoveOrigin(mo, mo.target.x, mo.target.y, mo.target.z + ((mo.target.eflags & MFE_VERTICALFLIP) and mo.target.height or 0))
		end
		if mo.target.player.powers[pw_carry] == CR_ROLLOUT
		or mo.target.player.powers[pw_carry] == CR_GRINDRAIL
