		mo.rollangle = mo.target.rollangle
		if mo.target.blendmode == AST_ADD
			mo.blendmode = AST_ADD
		end
	end
end, MT_MODERN_RUSHBOOST2)

//FORCES BOOST
addHook("MobjThinker", function(mo)
	if not (mo.valid) return end --
	if mo.target and mo.target.valid
		local p = mo.target.player
		if p.powers[pw_super]
		or p.mysticsuper
			mo.color = FindMyColor(p, SKINCOLOR_GOLDENROD)
		elseif p.powers[pw_shield] == SH_ELEMENTAL
			mo.color = SKINCOLOR_ORANGE		
		elseif p.powers[pw_shield] == SH_FLAMEAURA
		or p.firesonic
			mo.color = SKINCOLOR_KETCHUP
		else
			mo.color = FindMyColor(p, SKINCOLOR_GOLDENROD, 1, "forces")
		end
		
		--P_MoveOrigin(mo, mo.target.x, mo.target.y, mo.target.z)
		if not (mo.target.player.powers[pw_carry] == CR_GRINDRAIL)
			P_MoveOrigin(mo, mo.target.x, mo.target.y, mo.target.z + ((mo.target.eflags & MFE_VERTICALFLIP) and mo.target.height or 0))
		end
		if mo.target.player.powers[pw_carry] == CR_ROLLOUT
		or mo.target.player.powers[pw_carry] == CR_GRINDRAIL
			mo.angle = mo.target.player.drawangle
		elseif mo.target.player.powers[pw_carry] == CR_MINECART
			mo.angle = mo.target.tracer.angle
		else
			mo.angle = R_PointToAngle2(0, 0, mo.target.momx, mo.target.momy)
		end
		mo.rollangle = mo.target.rollangle
		if mo.target.player.modernmenu.contents[5][5].value == 1
			mo.blendmode = AST_ADD
		end
	end
//Front
	if not mo.front
		mo.front = P_SpawnMobjFromMobj(mo,0,0,0,MT_MODERN_FORCESBOOST2)
		mo.front.state = S_MODERN_FORCESBOOST_FRONT
		mo.front.scale = mo.scale*5/4
		mo.front.target = mo
		mo.front.angle = mo.angle
		mo.front.color = mo.color
		mo.front.frame = $|FF_TRANS10
		--mo.front.colorized = true
		mo.front.dispoffset = 8
	end
//Back
	if not mo.back
		mo.back = P_SpawnMobjFromMobj(mo,0,0,0,MT_MODERN_FORCESBOOST2)
		mo.back.state = S_MODERN_FORCESBOOST_BACK
		mo.back.scale = mo.scale*5/4
		mo.back.target = mo
		mo.back.angle = mo.angle
		mo.back.color = mo.color
		mo.back.frame = $|FF_TRANS10
		--mo.back.colorized = true
		mo.back.dispoffset = -8
	end
	if mo.front and mo.front.valid
		mo.front.scale = mo.scale*5/4
		mo.front.color = mo.color
		mo.front.rollangle = mo.rollangle
	end
	if mo.back and mo.back.valid
		mo.back.scale = mo.scale*5/4
		mo.back.color = mo.color
		mo.back.rollangle = mo.rollangle
	end
	if mo.target and mo.target.valid
		if not mo.target.player.boosting
		and not (mo.target.player.boostheld == true and mo.target.player.powers[pw_carry] == CR_ROLLOUT)
		and mo.target.player.minecartboost == false
		and (not mo.target.player.airboost or mo.target.player.airboost and not mo.target.player.airboostheld)
		and not mo.target.player.superboost
		and mo.front and mo.front.valid
		and mo.back and mo.back.valid
		or mo.target.player.boostmeter == 0
			mo.fuse = 1
			mo.target.forcesboostaura = nil
			P_RemoveMobj(mo.front)
			P_RemoveMobj(mo.back)
		end
	end
end, MT_MODERN_FORCESBOOST)


addHook("MobjThinker", function(mo)
	if mo.valid and mo.target and mo.target.valid
		P_MoveOrigin(mo, mo.target.x, mo.target.y, mo.target.z)
		mo.angle = mo.target.angle
		mo.color = mo.target.color
		mo.rollangle = mo.target.rollangle
		if mo.target.blendmode == AST_ADD
			mo.blendmode = AST_ADD
		end
	end
end, MT_MODERN_FORCESBOOST2)

