//A simple function you can call to spawn the boostaura. Call it every frame to have it work continuously.


local function ModernSonicRebornBoost(s)
	local p = s.player
	s.boostpass2 = 2 //This summons the third particle from the mobjthinker.
	if s.msbaang == nil //Lazy failsafe.
		s.msbaang = R_PointToAngle2(s.x, s.y, s.momx, s.momy)
	end
	if s.bostframe == nil
	s.bostframe = 3
	end
 
	local boostsparkle = P_SpawnMobjFromMobj(s,
	P_RandomRange(-10, 10)*FU,
	P_RandomRange(-10, 10)*FU,
	P_RandomRange(10, 60)*FU,
	MT_BOOSTSPARKLE)
	if p.powers[pw_super]
	or p.mysticsuper
		boostsparkle.color = FindMyColor(p, SKINCOLOR_GOLDENROD)
	elseif p.powers[pw_shield] == SH_ELEMENTAL
		boostsparkle.color = SKINCOLOR_ORANGE
	elseif p.powers[pw_shield] == SH_FLAMEAURA
	or p.firesonic
		boostsparkle.color = SKINCOLOR_KETCHUP
	else
		boostsparkle.color = FindMyColor(p, SKINCOLOR_GOLDENROD, 1, "boost1")
	end
	boostsparkle.scale = s.scale/2
	boostsparkle.fuse = 6
	boostsparkle.colorized = true
	
	//We'll be calling Modern's Sonic boost aura object "player.mo.msboost" (Though we're shortening player.mo to simply "s")
	s.msboost = P_SpawnMobjFromMobj(s, FixedMul(3*s.scale, cos(s.msbaang)),FixedMul(3*s.scale, sin(s.msbaang)), s.height/4, MT_MSBOOSTAURA)
	s.msboost.target = s
	s.msboost.sprite = SPR_BOST //The is the 1st boost aura particle that spawns in FRONT of Modern Sonic
	s.msboost.tics = 1
	s.msboost.momx = s.momx
	s.msboost.momy = s.momy
	s.msboost.momz = s.momz
	s.msboost.angle = s.msbaang
	s.msboost.scale = s.scale
	if (leveltime % 2 == 0) and s.bostframe != nil
	s.msboost.frame = (s.bostframe)|FF_FULLBRIGHT|(FF_TRANS50+(P_RandomRange(0,2)*s.scale)) 
	else
	s.msboost.frame = A|FF_FULLBRIGHT|(FF_TRANS50+(P_RandomRange(0,2)*s.scale)) 
	end
	if p.powers[pw_super]
	or p.mysticsuper
		s.msboost.color = FindMyColor(p, SKINCOLOR_GOLDENROD)
	elseif s.msflameboost
		s.msboost.color = SKINCOLOR_RED	
	else
		s.msboost.color = FindMyColor(p, SKINCOLOR_GOLDENROD, 1, "boost1")
	end
	s.msboost.scale = (s.scale*5/6)+FixedMul(P_RandomRange(-11000, 17000), s.scale)			
	if (s.eflags & MFE_VERTICALFLIP) //Fix for upsidedown boost aura.
	--s.msboost.z = $-FixedMul(29*s.scale, s.msboost.scale)
	end
	for i = 0, 1
	
		local fast = P_SpawnMobjFromMobj(s, (P_RandomRange(-40,40) * FU), (P_RandomRange(-40,40) * FU), (s.height/2) + (P_RandomRange(-24,35) * FU), MT_SPEEDLINE)
		if p.powers[pw_carry] == CR_MINECART
			fast.angle = s.angle
		else
			fast.angle = R_PointToAngle2(s.x, s.y, (s.x+s.momx), (s.y+s.momy))
		end
		fast.target = s
		if fast.target.player == displayplayer
			local chasecam = CV_FindVar("chasecam")
			if (chasecam.value == 1)
				fast.flags2 = $ & ~MF2_DONTDRAW
			elseif (chasecam.value == 0)
				fast.flags2 = $ | MF2_DONTDRAW
			end
		end
		if (p.powers[pw_shield] == SH_ELEMENTAL)
		and not (s.eflags & MFE_UNDERWATER)
		and p.powers[pw_super] == 0
			fast.color = SKINCOLOR_ORANGE
		elseif p.powers[pw_shield] == SH_FLAMEAURA
		and p.powers[pw_super] == 0
		or p.firesonic
			fast.color = SKINCOLOR_KETCHUP
		elseif (p.powers[pw_super])
		or p.mysticsuper
			fast.color = FindMyColor(p, SKINCOLOR_GOLDENROD)
		else
			fast.color = FindMyColor(p, SKINCOLOR_SUPER_SUNFLOWER3, 1, "boost1")
		end
		
		fast.frame = $|FF_TRANS20
	end
	--And this below here is the 2nd boost aura; a ghost replica of the initial boost aura
	--It's translucency should be lower. In Generations, his boost aura color gets lighter around this point. 
	--The third and last one, an extra boost aura particle is in the mobjthinker above!
	s.msboost = P_SpawnMobjFromMobj(s, FixedMul(3*s.scale, cos(s.msbaang)),FixedMul(3*s.scale, sin(s.msbaang)), 0, MT_MSBOOSTAURA)
	s.msboost.target = s
	s.msboost.sprite = SPR_BOST 
	s.msboost.tics = 3
	s.msboost.scale = s.scale
	--s.msboost.blendmode = AST_ADD
	if p.modernmenu.contents[5][5].value == 1
		s.msboost.blendmode = AST_ADD
	end
	if P_RandomRange(0,1)
		s.msboost.momx = s.momx/4*-1 //This one falls slightly *behind* Modern Sonic
		s.msboost.momy = s.momy/4*-1
		s.msboost.momz = s.momz/4*-1
		s.baatr2 = FF_TRANS70
	else
		s.msboost.momx = s.momx/5*-1
		s.msboost.momy = s.momy/5*-1
		s.msboost.momz = s.momz/5*-1
		s.baatr2 = FF_TRANS90
	end
	s.msboost.angle = s.msbaang //msbaang stands for "Modern Sonic Boost Aura ANGle" Don't mess with it.
	if (leveltime % 2 == 0)
		s.msboost.frame = (s.bostframe)|FF_FULLBRIGHT|(s.baatr2)
	else
		s.msboost.frame = A|FF_FULLBRIGHT|(s.baatr2)
	end
	if p.powers[pw_super]
	or p.mysticsuper
		s.msboost.color = FindMyColor(p, SKINCOLOR_GOLDENROD)
	elseif s.msflameboost
		s.msboost.color = SKINCOLOR_KETCHUP			
	else
		s.msboost.color = FindMyColor(p, SKINCOLOR_GOLDENROD, 1, "boost2")
	end
	 
	s.msboost.scale = (s.scale*5/6)+FixedMul(P_RandomRange(-11000, 17000), s.scale) //Scale flickering for boost aura. Feel free to mess with it.
	
	if ((s.bostframe <= 1) or (s.bostframe > 3)) and not s.bostframeswitch //Failsafe to prevent frame errors. Don't mess with this.
	s.bostframe = 3
	s.bostframeswitch = true
	end
--	if (s.eflags & MFE_VERTICALFLIP)
	--s.msboost.z = $-FixedMul(29*s.scale, s.msboost.scale)
--	end
end

local function ModernSonicGenerationsBoost(s)
local p = s.player
	if s.gensboostaura == nil
		s.gensboostaura = P_SpawnMobjFromMobj(s,0,0,0,MT_MODERN_GENERATIONSBOOST)
		s.gensboostaura.scale = 5*$/4
		if p.powers[pw_super]
		or p.mysticsuper
			s.gensboostaura.color = FindMyColor(p, SKINCOLOR_GOLDENROD)
		elseif p.powers[pw_shield] == SH_ELEMENTAL
		or p.firesonic
			s.gensboostaura.color = SKINCOLOR_KETCHUP			
		else
			s.gensboostaura.color = FindMyColor(p, SKINCOLOR_GOLDENROD, 1, "gens")
		end
		s.gensboostaura.target = s
	else
		if leveltime %4 == 0
			for i = 1,4 do
				local fa = FixedAngle(P_RandomKey(360)*FRACUNIT)
				local particle = P_SpawnMobjFromMobj(s, FixedMul(cos(fa),s.radius), FixedMul(sin(fa),s.radius), FixedMul((P_RandomByte()<<(FRACBITS-2)) - 8*FRACUNIT, s.scale), MT_BOOSTSPARKLE)
				particle.color = s.gensboostaura.color
				particle.scale = $/2
				particle.blendmode = AST_ADD
				particle.colorized = true
				particle.fuse = 8
			end
		end
	end
end

local function ModernSonicForcesBoost(s)
local p = s.player
	if s.forcesboostaura == nil
		s.forcesboostaura = P_SpawnMobjFromMobj(s,0,0,0,MT_MODERN_FORCESBOOST)
