		elseif p.powers[pw_shield] == SH_ELEMENTAL
		or p.firesonic
			s.forcesboostaura.color = SKINCOLOR_KETCHUP			
		else
			s.forcesboostaura.color = FindMyColor(p, SKINCOLOR_GOLDENROD, 1, "forces")
		end
		s.forcesboostaura.target = s
	else
		return
	end
end
