end

local function ModernSonicOldBoost(s)
local player = s.player
	if (player.mo.eflags & MFE_VERTICALFLIP and not (player.mo.flags2 & MF2_OBJECTFLIP))
	or (player.mo.flags2 & MF2_OBJECTFLIP and not (player.mo.eflags & MFE_VERTICALFLIP))
		player.flipthisboost = player.mo.z+player.mo.height
	elseif (player.mo.eflags & MFE_VERTICALFLIP and (player.mo.flags2 & MF2_OBJECTFLIP))
	or not (player.mo.eflags & MFE_VERTICALFLIP and not (player.mo.flags2 & MF2_OBJECTFLIP))
		player.flipthisboost = player.mo.z
	end
	local boostaura = P_SpawnMobjFromMobj(player.mo, 0,0,0, MT_OLDBOOSTAURA)
	local boostsparkle = A_BossScream(player.mo, 0, MT_BOXSPARKLE)
	local invsparkle = P_SpawnMobjFromMobj(player.mo, 0, 0, 0, MT_IVSP)
	invsparkle.state = S_IVSP
	invsparkle.tics = -1
	invsparkle.frame = leveltime % 32
	invsparkle.fuse = 16
	boostaura.target = player.mo
	if player.powers[pw_shield] == SH_ELEMENTAL
		boostaura.color = SKINCOLOR_ORANGE		
	elseif player.powers[pw_shield] == SH_FLAMEAURA
		boostaura.color = SKINCOLOR_KETCHUP
	elseif player.powers[pw_super]
	or player.mysticsuper
		boostaura.color = FindMyColor(player, SKINCOLOR_GOLDENROD)
	else 
		boostaura.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 1, player.mo.color)
	end
	boostaura.scale = player.mo.scale
	boostaura.rollangle = player.mo.rollangle
	if player.powers[pw_carry] == CR_MINECART
		boostaura.angle = player.mo.tracer.angle
	else
		boostaura.angle = R_PointToAngle2(boostaura.x, boostaura.y, (boostaura.target.x+boostaura.target.momx), (boostaura.target.y+boostaura.target.momy))
	end
-- 	P_MoveOrigin(boostaura, player.mo.x, player.mo.y, player.flipthisboost)
	if (leveltime % 2 == 0)
		boostaura.flags2 = $ & ~MF2_DONTDRAW
	else
		boostaura.flags2 = $|MF2_DONTDRAW
	end
	
	if player.modernmenu.contents[5][5].value == 1
		boostaura.blendmode = AST_ADD
	end
	
	local boostafterimage = P_SpawnMobjFromMobj(boostaura, 0,0,0, MT_GHOST)
	boostafterimage.sprite = boostaura.sprite
	boostafterimage.color = boostaura.color
	boostafterimage.angle = boostaura.angle
	boostafterimage.rollangle = boostaura.rollangle
	if player.modernmenu.contents[5][5].value == 1
		boostafterimage.blendmode = AST_ADD
	end
	boostafterimage.fuse = 4
	boostafterimage.target = player.mo
	boostafterimage.frame = $|FF_FULLBRIGHT
	boostafterimage.scale = P_RandomRange(4000/3, 2000/3)*player.mo.scale/1000
end
rawset(_G, "GetRail", function(mo)
    local sector = mo.subsector.sector
    local slope = mo.standingslope 
    
    if mo.eflags & MFE_VERTICALFLIP
        if slope
            if slope == sector.c_slope
                return sector.ceilingpic
            end
            for fof in sector.ffloors()
                if slope == fof.b_slope
                and (fof.flags & (FF_EXISTS|FF_BLOCKPLAYER|FF_PLATFORM)) == (FF_EXISTS|FF_BLOCKPLAYER)
                    return true
                end
            end
        else
            local z = mo.z + mo.height
            if z == sector.ceilingheight
                return sector.ceilingpic
            end
            for fof in sector.ffloors()
                if z == fof.bottomheight
                and (fof.flags & (FF_EXISTS|FF_BLOCKPLAYER|FF_PLATFORM)) == (FF_EXISTS|FF_BLOCKPLAYER)
                   return true
                end
            end
        end
    else
        if slope
            if slope == sector.f_slope
                return sector.floorpic
            end
            for fof in sector.ffloors()
                if slope == fof.t_slope
                and (fof.flags & (FF_EXISTS|FF_BLOCKPLAYER|FF_REVERSEPLATFORM)) == (FF_EXISTS|FF_BLOCKPLAYER)
                  
					return true
                end
            end
        else
            local z = mo.z
            if z == sector.floorheight
                return sector.floorpic
            end
            for fof in sector.ffloors()
                if z == fof.topheight
                and (fof.flags & (FF_EXISTS|FF_BLOCKPLAYER|FF_REVERSEPLATFORM)) == (FF_EXISTS|FF_BLOCKPLAYER)
					return true
                end
            end
        end
    end
end)


rawset(_G, "ModernSpeedSystem", function(s, p, returnmaxspeed, returnringspeed, returntruespeed)

/*	local ringspeed = 28 --Start with maximum and downgrade if rings are below 200.
	local maxspeed = 36 --Together with maxed ringspeed makes 64.

 	--Start your intended maxspeed calculations.
	if (p.boosting or p.airboost)
	and p.speedwhileboosting and (p.speedwhileboosting > 36*FRACUNIT)
		maxspeed = p.speedwhileboosting/FRACUNIT
	end 
	if p.powers[pw_sneakers] or p.powers[pw_super]
		maxspeed = ($*40)/27 --1.5x multiplier.
	elseif p.mysticsuper
		maxspeed = $*2 --2x multiplier.
	end
	--We just wanted to know Sonic's max speed, kthx.
	if returnmaxspeed --Remember to multiply*FRACUNIT
		return maxspeed
	end
	
	--Ringspeed calculations
 	if p.rings <= 200 --Downgrade ringspeed because we're not maxed yet?
		if p.rings < 1
			ringspeed = 0 -- You get nothing, good day sir.
		else
			ringspeed = p.rings/8 --Up to 28.
		end
	end	
	if ringspeed
		if not P_IsObjectOnGround(s) --Ringspeed has less effect in the air.
			if p.airboost or p.boost
				if p.powers[pw_super] or p.powers[pw_sneakers]
					ringspeed = $*10/11
				elseif not p.mysticsuper
					ringspeed = $*3/4
				end
			else
			ringspeed = $/3
			end
		elseif not (p.airboost or p.boost)
			ringspeed = $*5/6
		end
	end
	
	--Our final value.
	maxspeed = $+ringspeed
	
	--With either of these two, just return Modern Sonic's final maxspeed or his ringspeed.
	if returntruespeed
		return maxspeed
	elseif returnringspeed
		return ringspeed
	end
	if P_IsObjectOnGround(s) or p.powers[pw_carry] or not p.speed
		return
	end
	
	--Didn't return anywhere? Apply airdrag!
	local speed = p.speed/FRACUNIT
	if (speed > maxspeed)
		local airdrag = (speed-maxspeed)/4
		if (airdrag > 15)
			airdrag = 15 --Okay, don't slow the guy down THIS much, c'mon.
		elseif (airdrag < 0)
			airdrag = 0
		end
		s.momx = FixedDiv(FixedMul($, 800), 800+airdrag)
		s.momy = FixedDiv(FixedMul($, 800), 800+airdrag)
	end */
	
	local DRAGMULT = 7
	if (abs(p.cmd.sidemove)+abs(p.cmd.forwardmove) < 5) and not p.boosting
		DRAGMULT = $+23 --Brake like mad if players aren't holding anything.
	end
	if (p.speed > 80*s.scale) --Increasing airdrag overtime.
		local SPEED = (p.speed-(78*s.scale)) / (s.scale*2)
		DRAGMULT = $+min(40, SPEED)
	end
	if p.boosting and p.boostmeter
		DRAGMULT = $/2
	elseif not p.boostmeter and (p.speed > 48*s.scale)
		DRAGMULT = $*4/3
	end
	s.momx = FixedDiv(FixedMul($, 800), 801+DRAGMULT)
	s.momy = FixedDiv(FixedMul($, 800), 801+DRAGMULT)
end)

/////////////This ENTIRE script can go screw itself. the effect is nice but SRB2 really needs a way to catagorize textures better. I have every flat in SRB2 listed....but then find out that textures are ALSO used as fucking floor and ceiling textures....shoulda seen that coming ~_~
rawset(_G, "GetGroundTexture", function(mo)
    local sector = mo.subsector.sector
    local slope = mo.standingslope 
    
    if mo.eflags & MFE_VERTICALFLIP
        if slope
            if slope == sector.c_slope
                return sector.ceilingpic
            end
            for fof in sector.ffloors()
                if slope == fof.b_slope
                and (fof.flags & (FF_EXISTS|FF_BLOCKPLAYER|FF_PLATFORM)) == (FF_EXISTS|FF_BLOCKPLAYER)
					if fof.flags & FF_TRANSLUCENT and fof.alpha < 256
						return "thisisglass"
					end
                    return fof.bottompic
                end
            end
        else
            local z = mo.z + mo.height
            if z == sector.ceilingheight
                return sector.ceilingpic
            end
            for fof in sector.ffloors()
                if z == fof.bottomheight
                and (fof.flags & (FF_EXISTS|FF_BLOCKPLAYER|FF_PLATFORM)) == (FF_EXISTS|FF_BLOCKPLAYER)
					if fof.flags & FF_TRANSLUCENT and fof.alpha < 256
						return "thisisglass"
					end
                    return fof.bottompic
                end
            end
        end
    else
        if slope
            if slope == sector.f_slope
                return sector.floorpic
            end
            for fof in sector.ffloors()
                if slope == fof.t_slope
                and (fof.flags & (FF_EXISTS|FF_BLOCKPLAYER|FF_REVERSEPLATFORM)) == (FF_EXISTS|FF_BLOCKPLAYER)
                    if fof.flags & FF_TRANSLUCENT and fof.alpha < 256
						return "thisisglass"
					end
					return fof.toppic
                end
            end
        else
            local z = mo.z
            if z == sector.floorheight
                return sector.floorpic
            end
            for fof in sector.ffloors()
                if z == fof.topheight
                and (fof.flags & (FF_EXISTS|FF_BLOCKPLAYER|FF_REVERSEPLATFORM)) == (FF_EXISTS|FF_BLOCKPLAYER)
                    if fof.flags & FF_TRANSLUCENT and fof.alpha < 256
						return "thisisglass"
					end
					return fof.toppic
                end
            end
        end
    end
end)

