local function resetmodern(player)
	if player.mo and player.mo.valid
		player.mo.boostpass = 0 //Legacy, doesn't really get used, but still here anyway.
		player.mo.boostpass2 = 0
		player.mo.msbatr = FF_TRANS40
	//	player.mo.rollboostangle = 0
