--GS: Adding a ringlist for performance.
local RINGLIST = {}
RINGLIST[MT_RING] = true
RINGLIST[MT_COIN] = true 
RINGLIST[MT_BLUESPHERE] = true
RINGLIST[MT_FLINGRING] = true
RINGLIST[MT_FLINGCOIN] = true

local function Lightdashable(player) 
	local ringdist
	ringdist = 300*FU
	--span = ANGLE_90

	local maxdist = FixedMul(ringdist, player.mo.scale)
	local closestdist = 0
	local closestmo = nil
	local nonenemiesdisregard = MF_SPRING
	searchBlockmap("objects",function(pmo,mo)
		if not (RINGLIST[mo.type]==true) 
		or (mo.flags & MF_NOCLIPTHING) 
		or (mo.health <= 0)
			return --
		end
		
		local zdist = (pmo.z + pmo.height/2) - (mo.z + mo.height/2)
		local dist = P_AproxDistance(pmo.x-mo.x, pmo.y-mo.y)
		//CBW: 	Made the angle checks their own locals, for readability purposes
		//		I also unsigned the angle checks, which appears to correct failed OutOfBounds checks above the player.
		local xyz_angle = abs(R_PointToAngle2(0, 0, dist, zdist))
		local xy_angle = abs(R_PointToAngle2(
				pmo.x + P_ReturnThrustX(pmo, pmo.angle, pmo.radius),
				pmo.y + P_ReturnThrustY(pmo, pmo.angle, pmo.radius),
				mo.x, mo.y
			) - pmo.angle)
			
			
		dist = P_AproxDistance(dist, zdist)
		if (dist > maxdist)
			return -- out of range
		end
-- 		print("\x82!!!VERT","# Span check: "..xyz_angle/ANG1,"# Limit: "..span*2/ANG1,"#Within Range: "..tostring(abs(xyz_angle) <= span))
		/*if (xyz_angle > span 
			return -- Don't home outside of desired angle!
		end*/
		if abs(zdist) > 300*FU
			return 
		end
		if ((closestmo and closestmo.valid) and (dist > closestdist))
			return
		end

		closestmo = mo
		closestdist = dist
		
	end,player.mo,player.mo.x-maxdist,player.mo.x+maxdist,player.mo.y-maxdist,player.mo.y+maxdist)
	return closestmo
end

addHook("MobjDamage", function(mobj, inflictor, source, damage, damagetype)
	if not (mobj and mobj.valid)
	or not (mobj.skin == "modernsonic")
	or not (mobj.player and mobj.player.valid)
	or not (mobj.health)
	or(mobj.player.powers[pw_carry] == CR_NIGHTSMODE)
	or P_PlayerInPain(mobj.player)
	or mobj.player.powers[pw_super]
		return
	end
	if(mobj.player.powers[pw_shield])
		P_RemoveShield(mobj.player)
		P_PlayerFlagBurst(mobj.player)
		P_DoPlayerPain(mobj.player)
		if not(mariomode)
			S_StartSound(mobj, sfx_shldls)
		else
			S_StartSound(mobj, sfx_mario8)
		end
	else
		if(mobj.health <= 0)
		or mobj.player.rings == 0
			P_PlayerWeaponPanelBurst(mobj.player)
			P_PlayerWeaponAmmoBurst(mobj.player)
			P_PlayerEmeraldBurst(mobj.player)
			P_PlayerFlagBurst(mobj.player)
			P_KillMobj(mobj)
			mobj.health = 0
		else
			if not(mariomode)
				S_StartSound(mobj, sfx_altow1)
			else
				S_StartSound(mobj, sfx_mario8)
			end
			P_PlayerRingBurst(mobj.player, mobj.player.rings)
			if mobj.player.rings >= 40
				mobj.player.rings = $ - $/2
			else
				mobj.player.rings = 0
			end
			--mobj.player.rings = (mobj.player.rings < 0) and 0 or $
			P_DoPlayerPain(mobj.player)
			
		end
	end
	return true
end, MT_PLAYER)
		
//Get the player's input angle
rawset(_G, "ModernInputAngle", function(player)
	if (player.pflags&PF_DIRECTIONCHAR and player.pflags&PF_ANALOGMODE)
	or player.mo.flags2 & MF2_TWOD or twodlevel
		return player.mo.angle
	elseif not P_GetPlayerControlDirection(player)
		return player.drawangle
	else 
		return player.cmd.angleturn<<16 + R_PointToAngle2(0, 0, player.cmd.forwardmove*FRACUNIT, -player.cmd.sidemove*FRACUNIT)
	end
end)
		
addHook("PlayerSpawn", function(p)
	if p.mo and p.mo.valid
		resetmodern(p)
	end
end)

