	sprite = SPR_MTHK,
	frame = FF_FULLBRIGHT,
	tics = -1
}

freeslot("SPR_SROK")
--This Trail Function is to only be used for Boosting
local function ModernBoostTrail(mo, trailmo, freq)
	local spawnedMobjs = {}
    if not mo.prevz or not mo.prevleveltime or (mo.prevleveltime ~= leveltime - 1) then
       mo.prevz2 = mo.z
    end
    local rmomz = mo.z - mo.prevz2
	mo.prevz2 = mo.z
    mo.prevleveltime = leveltime
    local mospeed = R_PointToDist2(0, 0, R_PointToDist2(0, 0, mo.momx, mo.momy), rmomz)
    local dist = (mospeed/freq)
	local player = mo.player
    for i = dist, 1, -1 do
        local modernboosttrail = P_SpawnMobjFromMobj(mo, (mo.momx/dist)*i-mo.momx, (mo.momy/dist)*i-mo.momy, (rmomz/dist)*i-rmomz, trailmo)
		table.insert(spawnedMobjs, modernboosttrail)
        if player.modernmenu.contents[5][1].value == 1 -- Boost Trail Blending	
			modernboosttrail.blendmode = AST_ADD
		else
			modernboosttrail.blendmode = AST_TRANSLUCENT
		end
		if player.powers[pw_super]
			modernboosttrail.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 2)
		elseif (player.powers[pw_shield] == SH_FLAMEAURA
		or player.powers[pw_shield] == SH_ELEMENTAL)
		and not (player.mo.eflags & MFE_UNDERWATER)
			if player.firesonic
				modernboosttrail.color = SKINCOLOR_RED
			else
				modernboosttrail.color = SKINCOLOR_ORANGE
			end
		else
			if player.boosting
			or (player.airboost == true and player.airboostheld == true)
				modernboosttrail.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 2, "forces")
			elseif player.customhoming 
				modernboosttrail.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 5, "forces")
			else
				modernboosttrail.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 4, "forces")
			end
		end
		modernboosttrail.sprite = SPR_SROK
		modernboosttrail.scale = mo.scale
		modernboosttrail.renderflags = $1|FF_FULLBRIGHT
		modernboosttrail.fuse = 5
		modernboosttrail.frame = A|TR_TRANS90
		modernboosttrail.rollangle = -1*(camera.angle - R_PointToAngle2(mo.momx, mo.momy, 0, 0) - R_PointToAngle2(R_PointToDist2(0, 0, mo.momx, mo.momy), -rmomz, 0, 0))
	end
	if mo.player.boosting 
	or mo.player.superboost == true 
	or (mo.player.airboost == true and mo.player.airboostheld == true)
		if mo.player.modernmenu.contents[7][6].value == 1 -- Lightning Trail
			local s = mo
			local p = mo.player
			local fa = FixedAngle(P_RandomKey(360)*FRACUNIT)
			local particle = P_SpawnMobjFromMobj(s, FixedMul(cos(fa),s.radius)/2, FixedMul(sin(fa),s.radius)/2, FixedMul((P_RandomByte()<<(FRACBITS-2)) - 24*FRACUNIT, s.scale), MT_THOK)
			particle.color = FindMyColor(p, SKINCOLOR_GOLDENROD, 1, "gens")
			particle.blendmode = mo.player.modernmenu.contents[5][5].value==1 and AST_ADD or 0
			particle.sprite = SPR_DTHK
			particle.frame = P_RandomRange(E,F)|FF_FULLBRIGHT
			particle.rollangle = fa
			particle.tics = 6
			particle.fuse = -1
		end
	end
end



--Call this if your trail needs segments!
local function Modern_GetTrailSegment(mo)
	if moTriedGetSegment==true return end --
	mo.TriedGetSegment = true
	
	if not (mo.target and mo.target.skin=="modernsonic") --Don't waste a blockmap search if we don't need it.
		local br = 1<<16
		searchBlockmap("objects", function(mobj, found)
			if found.skin == "modernsonic" and found.type==MT_PLAYER and found.health
				mo.target = found return true --
			end
		end, mo, mo.x - br, mo.x + br, mo.y - br, mo.y + br)
	end
	
	if mo.segment==nil and mo.target and mo.target.player and mo.target.player.modernmenu --Don't bother if we don't need it!
		mo.segment = {}
		local VAL = mo.target.player.modernmenu.contents[5][1].value
		for i = 0, 106 --S-SPORK?! 106?!
			mo.segment[i] = P_SpawnMobjFromMobj(mo, 0, 0, 0, MT_MTHOK)
			mo.segment[i].frame = i/8|FF_TRANS90
			mo.segment[i].scale = mo.scale 
			mo.blendmode = (VAL==1) and AST_ADD or AST_TRANSLUCENT --Boost Trail Blending	
		end
		for i = 0, 106
			if i == 0
				mo.segment[i].target = mo
				--mo.segment[i].tracer = mo.segment[i+1]
			elseif i == 106
				mo.segment[i].target = mo.segment[i-1]
			else
				mo.segment[i].target = mo.segment[i-1]
				--mo.segment[i].tracer = mo.segment[i+1]
			end
			if mo.target and mo.target.valid
				mo.segment[i].tracer = mo.target
			end
		end	
	end
end

local function NewModernTrail(player, supercolor)
	if not (player.mo and player.mo.valid and not player.moderntrail) return end --
	
	player.moderntrail = P_SpawnMobjFromMobj(player.mo, 0, 0, 0, MT_MODERN_TRAIL)
	player.moderntrail.target = player.mo
	
	if player.modernmenu.contents[5][1].value == 1 -- Boost Trail Blending	
		player.moderntrail.blendmode = AST_ADD
	else
		player.moderntrail.blendmode = AST_TRANSLUCENT
	end
	if player.powers[pw_super]
		player.moderntrail.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 2)
	elseif (player.powers[pw_shield] == SH_FLAMEAURA or player.powers[pw_shield] == SH_ELEMENTAL) and not (player.mo.eflags & MFE_UNDERWATER)
		player.moderntrail.color = (player.firesonic) and SKINCOLOR_RED or SKINCOLOR_ORANGE
	else
		if player.boosting or (player.airboost == true and player.airboostheld == true) 		
			player.moderntrail.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 2)
		elseif player.customhoming 
			player.moderntrail.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 5)
		else
			player.moderntrail.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 4)
		end
	end
	Modern_GetTrailSegment(player.moderntrail)
end

