addHook("MobjThinker", function(mobj)
	if mobj and mobj.valid and mobj.target and mobj.target.valid and mobj.tracer and mobj.tracer.valid
		mobj.eflags = mobj.tracer.eflags
		mobj.scale = mobj.tracer.scale
		local target = mobj.target
		local dist = P_AproxDistance(P_AproxDistance(mobj.x - target.x, mobj.y - target.y), mobj.z - target.z) 
		local radius = mobj.radius + target.radius
		local hangle = R_PointToAngle2(target.x, target.y, mobj.x, mobj.y)
		local zangle = R_PointToAngle2(0, target.z, dist, mobj.z)
		local hdist = P_ReturnThrustX(target, zangle, radius)
		local xdist = P_ReturnThrustX(target, hangle, hdist)
		local ydist = P_ReturnThrustY(target, hangle, hdist)
		local zdist = P_ReturnThrustY(target, zangle, radius)
		mobj.color =  mobj.target.color
		mobj.blendmode = mobj.target.blendmode
		if mobj.tracer.player.stomping
			P_MoveOrigin(mobj, target.x, target.y, target.z + zdist)
		else
			P_MoveOrigin(mobj, target.x + xdist, target.y + ydist, target.z + zdist)
		end
	end
end, MT_MTHOK)

--GS: Guess I updated this one for shits and giggles.
local function ModernTrail(mo, trailmo, freq, supercolor)
	local spawnedMobjs = {}
    if not mo.prevz or not mo.prevleveltime or (mo.prevleveltime ~= leveltime - 1) then
       mo.prevz = mo.z
    end
    local rmomz = mo.z - mo.prevz
	if mo.eflags & MFE_VERTICALFLIP
		rmomz = -$
	end
    mo.prevz = mo.z
    mo.prevleveltime = leveltime
    -- Handy local variables.
    local mospeed = R_PointToDist2(0, 0, R_PointToDist2(0, 0, mo.momx, mo.momy), rmomz)
    local dist = (mospeed/freq)
	
	
	--Settle color values outside of the loop so they only have to be done once!
	local COLOR = mo.color
	if mo.player.powers[pw_super] or mo.player.mysticsuper	
		if ((mo.color == SKINCOLOR_SUPER_SUNFLOWER1) or (mo.color == SKINCOLOR_SUPER_SUNFLOWER2) or (mo.color == SKINCOLOR_SUPER_SUNFLOWER3) or (mo.color == SKINCOLOR_SUPER_SUNFLOWER4) or (mo.color == SKINCOLOR_SUPER_SUNFLOWER5))
			COLOR = FindMyColor(mo.player, SKINCOLOR_GOLDENROD)
		else
			COLOR = FindMyColor(mo.player, supercolor)
		end
	elseif (mo.player.powers[pw_shield] == SH_ELEMENTAL or mo.player.powers[pw_shield] == SH_FLAMEAURA or mo.player.firesonic)
	and not (mo.eflags & MFE_UNDERWATER)
	and mo.player.powers[pw_super] == 0
		COLOR = FindMyColor(mo.player, supercolor, 2)
	elseif mo.player.boosting or (mo.player.airboost == true and mo.player.airboostheld == true) 
		COLOR = FindMyColor(mo.player, supercolor, 2)
	elseif mo.player.customhoming 
		COLOR = FindMyColor(mo.player, supercolor, 5)
	else
		COLOR = FindMyColor(mo.player, supercolor, 4)
	end
	
	local BOOSTING = (mo.player.boosting or mo.player.superboost==true or mo.player.airboost==true and mo.player.airboostheld==true) and true or false
	local BOOSTBLEND = (mo.player.modernmenu.contents[5][1].value==1) and AST_ADD or 0
	local STOMPBLEND = 0 if mo.player.stomping STOMPBLEND = mo.player.modernmenu.contents[5][3].value end
	local CUSTOMHOMINGBLEND = mo.player.modernmenu.contents[5][7].value
	local PARTICLE = nil
	if BOOSTING and mo.player.modernmenu.contents[7][1].value==4 and (leveltime%2==0)
		PARTICLE = FindMyColor(player, SKINCOLOR_GOLDENROD, 1)
	end
	
    -- The loop, repeats until it spawns all the thok objects.
    for i = dist,1,-1 do
        local spawnedmo = P_SpawnMobjFromMobj(mo, (mo.momx/dist)*i, (mo.momy/dist)*i, (rmomz/dist)*i, trailmo)
		if not (spawnedmo and spawnedmo.valid) continue end --
		table.insert(spawnedMobjs, spawnedmo)
		
		spawnedmo.color = COLOR
		
		if BOOSTING==true
			if BOOSTBLEND -- Boost Trail Blending
				spawnedmo.blendmode = BOOSTBLEND
				spawnedmo.sprite = SPR_DTHK
				if mo.player.powers[pw_super]
					spawnedmo.frame = D|FF_TRANS90
				else
					spawnedmo.frame = A|FF_TRANS70
				end
			else
				spawnedmo.sprite = SPR_DTHK
				spawnedmo.frame = C|FF_TRANS70
			end
			spawnedmo.fuse = 6
			if PARTICLE!=nil
				local s = spawnedmo
				local fa = FixedAngle(P_RandomKey(360)*FRACUNIT)
				local particle = P_SpawnMobjFromMobj(s, FixedMul(cos(fa),s.radius)/2, FixedMul(sin(fa),s.radius)/2, FixedMul((P_RandomByte()<<(FRACBITS-2)) - 24*FRACUNIT, s.scale), MT_THOK)
				particle.color, particle.colorized = PARTICLE, true
				particle.blendmode = AST_ADD
				particle.sprite = SPR_WZAP
				particle.flags = $|MF_NOCLIPTHING|MF_NOBLOCKMAP|MF_NOCLIPHEIGHT|MF_SCENERY|MF_NOCLIP
				particle.frame = P_RandomRange(0,3)
				particle.tics,particle.fuse = -1, 8
			end
		elseif STOMPBLEND==1 -- Stomp Blending
			spawnedmo.blendmode = AST_ADD -- blend
		elseif mo.player.customhoming
			if CUSTOMHOMINGBLEND==1
				spawnedmo.blendmode = AST_ADD -- blend
			end
			spawnedmo.sprite = SPR_DTHK
			if mo.player.doubledamage
				spawnedmo.frame = D|FF_TRANS70
				spawnedmo.color = SKINCOLOR_HOMINGRAINBOW
			end
			if mo.player.powers[pw_super] and not (mo.player.doubledamage)
				spawnedmo.frame = D|FF_TRANS90
			else
				spawnedmo.frame = A|FF_TRANS70
			end
		end
    end
	return spawnedMobjs
end

local WALLJUMPFALL = 4
local WALLJUMPTHRUST = 16

addHook("PlayerThink", function(player)
	local p = player if not (p.mo and p.mo.valid and p.mo.skin == "modernsonic") return end --
	local s = p.mo
	
	//Sliding Friction
	if p.sliding
		if s.standingslope == nil
			s.friction = FRACUNIT-3000
		elseif s.standingslope ~= nil
			if (s.z < p.prevz and not (s.eflags & MFE_VERTICALFLIP))
			or (s.z > p.prevz and (s.eflags & MFE_VERTICALFLIP))
				s.friction = 549*(29 * FRACUNIT/32)/500
				p.prevz = s.z
			elseif (s.z > p.prevz and not (s.eflags & MFE_VERTICALFLIP))
			or (s.z < p.prevz and (s.eflags & MFE_VERTICALFLIP))
				p.prevz = s.z
				s.friction = FRACUNIT-3000
			elseif s.z == p.prevz
				s.friction = FRACUNIT-3000
			end
		end
	end
	
	//Footsweep Friction
	if p.footsweepattack
		s.friction = FU
	end
	
	if p.airboost == false
		p.usedwalljump = false
	end
	if p.endlvl --Exit level victory animation!	
		p.endlvl = $+1
	end
	if (p.boosting or p.superboost == true
	or (p.airboost == true and p.airboostheld == true and p.speed > 45*s.scale)
	or p.minecartboost)
	and (p.modernmenu.contents[7][2].value == 1 or p.modernmenu.contents[7][2].value == 2 and p.rushmode) -- BoostTrail
	and p.usedwalljump == false
	and p.modernwallslide == 0
		--ModernTrail(p.mo, MT_THOK, 4*FRACUNIT, SKINCOLOR_SUPER_SUNFLOWER5) 
		--NewModernTrail(player, SKINCOLOR_SUPERGOLD3)
		ModernBoostTrail(player.mo, MT_THOK, 3*FRACUNIT)
	else
		if p.moderntrail and p.moderntrail.valid
		and not p.customhoming
		and not p.traillag
		and not p.stomping
		and not p.gensdash
			if not p.moderntrail.killmepls
				p.moderntrail.fuse = 15
				p.moderntrail.killmepls = 15
			end
			p.moderntrail = nil
		end
	end
	if p.playerstate == PST_DEAD
		p.boostheld = true
		p.boosting = false
		p.airboost = false
		p.superboost = false --i fucking suck
		if p.moderntrail
			if not p.moderntrail.killmepls
				p.moderntrail.fuse = 15
				p.moderntrail.killmepls = 15
			end
			p.moderntrail = nil
		end
	end
	if p.stomping
		NewModernTrail(player, SKINCOLOR_SUPERGOLD3)
	end
	if not p.customhoming and not p.footsweepattack
		p.doubledamage = false
	end
	if p.customhoming > 0
	or p.gensdash
		--ModernTrail(p.mo, MT_THOK, 4*FRACUNIT)
		NewModernTrail(player, SKINCOLOR_SUPERGOLD3)
	end
	p.walljumpmomercy = max($-1, 0)
	//wall jump ghosts
	if p.walljumpthrusttimer > 1
		p.drawangle = p.throwangle 
		--p.mo.reactiontime = 1 --using reactiontime instead of normalspeed 
		p.walljumpthrusttimer = $1-1
		p.mo.ghs = P_SpawnGhostMobj(p.mo)
		p.mo.ghs.tics = 4
		p.mo.ghs.colorized = true
		p.mo.ghs.blendmode = AST_ADD
	elseif p.walljumpthrusttimer == 0
		p.walljumpangle = 0
	end
	//Wall sliding
	if p.modernwallslide
		if (((p.cmd.buttons & BT_USE) and p.modernmenu.contents[2][2].value == 1) or ((p.cmd.buttons & BT_CUSTOM1) and p.modernmenu.contents[2][2].value == 0)) -- Actionswap
			p.boostheld = true
		end
		p.dropdashing = false
		p.pflags = $ & ~PF_SPINNING
		local line = lines[p.lastlinehit]
		local side = sides[p.lastsidehit]
		if not P_IsObjectOnGround(p.mo)
		and line and line.valid and side and side.valid
			local pointx, pointy = P_ClosestPointOnLine(p.mo.x, p.mo.y, line)
			p.drawangle = R_PointToAngle2(pointx, pointy, p.mo.x, p.mo.y)
			local angle = R_PointToAngle2(line.v1.x, line.v1.y, line.v2.x, line.v2.y)
			if line.frontside == side
				angle = $-ANGLE_180
			end
			//Slide momentum
			
			if (p.powers[pw_shield] == SH_FORCE)
			or p.powers[pw_shield] == SH_FORCE+1
				p.mo.momx = ($ - p.cmomx)*3/6 + p.cmomx
				p.mo.momy = ($ - p.cmomy)*3/6 + p.cmomy
				p.mo.momz = 0
			else
				if p.mo.momz*P_MobjFlip(p.mo) < 0
					p.mo.momz = min(max($, -WALLJUMPFALL*p.mo.scale), WALLJUMPFALL*p.mo.scale)
				end
				if leveltime%3==1 then
					local t = p.mo.radius
					local dust = P_SpawnMobj(p.mo.x+P_ReturnThrustX(nil,p.drawangle+ANGLE_180,t),
					p.mo.y+P_ReturnThrustY(nil,p.drawangle+ANGLE_180,t),
					p.mo.z,MT_DUST)
					dust.scale = p.mo.scale
				end
				p.mo.momx = ($ - p.cmomx)*5/6 + p.cmomx
				p.mo.momy = ($ - p.cmomy)*5/6 + p.cmomy
				if not (S_SoundPlaying(p.mo,sfx_s3k7e))
					S_StartSound(p.mo, sfx_s3k7e)
				end
			end
			
			//Stuff
			player.mo.state = S_PLAY_WALLCLING
			player.modernwallslide = $ - 1
			--player.modernslidesfx = max($, 1)
			
			//Move with conveyors
			if side == player.modernlastside
				//Move with conveyors
				if side.textureoffset != player.modernsidexscroll
				or side.rowoffset != player.modernsideyscroll
					//Horizontal movement
					P_TryMove(player.mo,
					player.mo.x+FixedMul(side.textureoffset-player.modernsidexscroll, cos(angle)),
					player.mo.y+FixedMul(side.textureoffset-player.modernsidexscroll, sin(angle)),
					true)
					
					//Verical Movement
					player.mo.z = $ + side.rowoffset-player.modernsideyscroll
					player.mo.momz = 0
				end
			else
				player.modernlastside = side
			end
			
			//Update variables
			player.modernsidexscroll = side.textureoffset
			player.modernsideyscroll = side.rowoffset
		else
			player.modernwallslide = 0
		end
		
		if not player.modernwallslide
			player.mo.state = S_PLAY_WALLCLINGEND
			player.modernlastside = nil
			player.airboost = false
		end
	elseif player.mo.state ~= S_PLAY_TRICKALT_1 and player.mo.state ~= S_PLAY_TRICKALT_2 and player.mo.state ~= S_PLAY_TRICKALT_3 and player.mo.state ~= S_PLAY_HOPFALL
		player.modernwalljump = false
		player.firstietimer = 0
	end
end)

addHook("MobjMoveBlocked", function(mo)
	--if not (P_IsObjectOnGround(mo)) return end
	if not (mo.player and mo.skin=="modernsonic") return end
	
	mo.player.driftcancel = $+1
	if mo.player.boosting or mo.player.superboost
		mo.player.boostfuckedbywall = $+1
		--return false
	end
	if mo.player.speed < 10*mo.scale
		mo.player.boostfuckedbywall = 5
	end
	--return true
	
end, MT_PLAYER)

//Wall Collision
addHook("MobjMoveBlocked", function(mo)
	local player = mo and mo.valid and mo.player
	if mo.skin ~= "modernsonic" then return end
	if (player.glidetime and P_IsObjectInGoop(mo)) return end
	if P_IsObjectOnGround(mo) then  return end
	if P_PlayerInPain(mo.player)  then return end
	if mo.player.tricking == true then return end
	--if mo.player.hopdown == true then return end
	--if mo.player.airboost == true then return end
	if mo.player.superboost == true then return end
	if mo.player.boosting == true then return end
	if mo.player.customhoming > 0 then return end
	if mo.player.lightdashing > 0 and player.wasjustlightdashing then return end
	if mo.player.powers[pw_carry] then return end
	if mo.player.playerstate == PST_DEAD then return end
	if mo.player.playerstate ~= PST_LIVE then return end --Why would i need this ~_~
	if mo.state == S_PLAY_DEAD then return end
	if mo.player.stomping then return end
	if (P_IsObjectInGoop(mo)) then return end
	//Wall Sliding and Ledge Grabbing
	if not P_IsObjectOnGround(mo) 
	and P_GetPlayerControlDirection(player) and not player.climbing
	and ( (player.pflags&PF_STARTJUMP and mo.momz*P_MobjFlip(mo) <= 0)
	or (not (player.pflags&PF_STARTJUMP) and mo.momz*P_MobjFlip(mo) <= -4*P_GetMobjGravity(mo) or player.walljumpmomercy)
	or player.modernwalljump)
	and not (player.pflags & (PF_JUMPSTASIS))
	
		local prevline = player.lastlinehit
		local prevside = player.lastsidehit
		
		player.lastlinehit = -1
		player.lastsidehit = -1
		
		P_SlideMove(mo)
		player.powers[pw_pushing] = 3
		
		local line = lines[player.lastlinehit]
		local side = sides[player.lastsidehit]
		if line and line.valid and side and side.valid
			
			local pointx, pointy = P_ClosestPointOnLine(mo.x, mo.y, line)
			local angle = R_PointToAngle2(mo.x, mo.y, pointx, pointy)
			
			local diff = ModernInputAngle(player) - angle
			diff = InvAngle(InvAngle($))
			
			if abs(diff) < ANGLE_90
			and not (line and line.backsector
			and line.backsector.ceilingpic == "F_SKY1"
			and line.frontsector
			and line.frontsector.ceilingpic == "F_SKY1"
			and (mo.z >= line.frontsector.ceilingheight
			or mo.z >= line.backsector.ceilingheight))
			and line.special != 41
				//Wall Slide
				--player.drawangle = R_PointToAngle2(mo.x,mo.y,P_ClosestPointOnLine(mo.x,mo.y,line)) - ANGLE_180
				player.throwangle = R_PointToAngle2(mo.x,mo.y,P_ClosestPointOnLine(mo.x,mo.y,line)) +FixedAngle(180*FRACUNIT)
				if player.modernwallslide == 0
					S_StartSound(mo, sfx_s3k4c)
				end
				player.firstietimer = $+1
				player.modernwallslide = 3
				P_Thrust(player.mo, angle, 1*FU)
				player.jumptimer = 4
				if player.modernlastside == nil
					player.modernlastside = side
					player.modernsidexscroll = side.textureoffset
					player.modernsideyscroll = side.rowoffset
				end
			end
		else
			player.lastlinehit = prevline
			player.lastsidehit = prevside
		end
		return true
	end
end, MT_PLAYER)

local LineJump = function(player)
	local mo = player.mo
	mo.state = S_PLAY_WALLJUMP
	player.jumptimer = 4
	mo.modernjetspeed = (player.speed+25*mo.scale)
	player.walljumpthrusttimer = 10
	if player.cmd.buttons & BT_USE
		mo.angle = player.throwangle
		player.boostheld = true
	end
	if player.airboost == true
		player.usedwalljump = true
		player.airboost = false
	end
	if player.modernmenu.contents[2][7].value == 1
		if player.rings <= 200
			player.normalspeed = FixedMul(36*FRACUNIT+(player.rings/3)*FRACUNIT, player.mo.scale)
		else
			player.normalspeed = 64*FU
		end
	else
		player.normalspeed = 36*FU
	end
	--if player.speed > 20*FU
	if player.firstietimer < 2
		local firstieflare = P_SpawnMobjFromMobj(player.mo, 0, 0, 0*FRACUNIT, MT_TRICKSPARKLESRING)
		firstieflare.target = player.mo
		firstieflare.scale = 0
		firstieflare.destscale = FRACUNIT*8
		firstieflare.scalespeed = FRACUNIT*65/100
		firstieflare.blendmode = AST_ADD
		firstieflare.color = FindMyColor(mo.player, SKINCOLOR_GOLDENROD, 1, "boost1")
		firstieflare.colorized = true
		mo.modernjetspeed = 931<<16
		player.doublejumped = false
		--player.airboostcounter = $-2
		player.trickable = true
		if player.cmd.buttons & BT_JUMP
			--P_SetObjectMomZ(player.mo, FixedMul(player.mo.scale, 10*FRACUNIT), false)
			P_SetObjectMomZ(player.mo, 10*FRACUNIT, false)
			player.mo.momz = $*max(6,9-player.airboostcounter)/7
		end
		if not (player.mo.eflags & MFE_UNDERWATER)
			S_StartSound(player.mo, sfx_lsd)
		else
			S_StartSound(player.mo, sfx_lsdw)
		end
	end
	--player.speedwhileboosting = FixedMul(36*FRACUNIT+(player.rings/3)*FRACUNIT, player.mo.scale)
	player.stompdown = true
	player.justjumped = true
	--player.wallslidetimer = 0
	SpawnActionDust(mo, 2)
	if player.powers[pw_super]
	or player.mysticsuper
		if mo.eflags & MFE_UNDERWATER
			P_InstaThrust(mo, player.throwangle, max(WALLJUMPTHRUST*mo.scale, player.speed*3/2))
			P_SetObjectMomZ(mo, 16*FRACUNIT/2, false)
			player.mo.momz = $*max(6,9-player.airboostcounter)/7
		else
			P_InstaThrust(mo, player.throwangle, max(WALLJUMPTHRUST*mo.scale, player.speed*3/2)*2)
			P_SetObjectMomZ(mo, 16*FRACUNIT, false)
			player.mo.momz = $*max(6,9-player.airboostcounter)/7
		end
	else
		if mo.eflags & MFE_UNDERWATER
			P_InstaThrust(mo, player.throwangle, max(WALLJUMPTHRUST*mo.scale, player.speed*3/2)/2)
			P_SetObjectMomZ(mo, 6*FU, false)
			player.mo.momz = $*max(6,9-player.airboostcounter)/7
		else
			P_InstaThrust(mo, player.throwangle, max(WALLJUMPTHRUST*mo.scale, player.speed*3/2))
			P_SetObjectMomZ(mo, 12*FU, false)
			player.mo.momz = $*max(0,9-player.airboostcounter)/9
		end
	end
	player.airboostheld = false
	player.walljumpthrusttimer = 10
	player.walljumpmomercy = 25
	player.walljumpangle = player.drawangle
	player.pflags = $1&~PF_THOKKED
	player.pflags = $|PF_JUMPED
	if (mo.eflags & MFE_UNDERWATER)
		if mo.player.mysticsuper
			S_StartSound(mo, sfx_bljpw)
		else
			S_StartSound(mo, sfx_wwljmp)
		end
	else
		if mo.player.mysticsuper
			S_StartSound(mo, sfx_bljp)
		else
			S_StartSound(mo, sfx_wljump)
		end
	end
end

local EBE = {} --GS: Object types for flingable objects that don't fall under MF_ENEMY
EBE[MT_TNTBARREL] = true 
EBE[MT_SMALLMACE] = "firesonic"
EBE[MT_BIGMACE] = "firesonic"

--GS: I'll leave this one here since all the local functions happen to be here.
addHook("MobjMoveCollide", function(eb, enemy)
	if not (eb.valid and eb.player) return end --
	local p = eb.player
	if not (
		p.boosting==true
		or p.airboost==true and p.airboostheld==true
		or ((p.customhoming or 0) > 0)
		or p.sliding
		)
		return --
	end
	if not (enemy and enemy.valid)
		return --
	end
	if (enemy.flags & MF_ENEMY)
	or EBE[enemy.type]==true
	or EBE[enemy.type]=="firesonic" and p.firesonic
		if (eb.z <= enemy.z + enemy.height*2)
		and (eb.z + eb.height*2 >= enemy.z)
			if enemy.health and (enemy.health<=(p.doubledamage and 2 or 1))
			and not enemy.flung  and not (enemy.flags2 & MF2_FRET)
			and enemy.type != MT_FOUNDYOUFAKER and not P_PlayerInPain(p)
				//enemy.target = eb.target
				enemy.flags = $ &~MF_SOLID
				if (p.boosting==true or (p.airboost==true and p.airboostheld==true) or p.customhoming > 0)
					p.boostshake = max(p.boostshake or 0, 3)
				end
				if p.rushmode > 0
					S_StartSound(eb, sfx_rstrck)
				end
				p.boostregentimer = 0
				if p.customhoming	
					if p.modernmenu.contents[7][3].value == 1 -- Poses
						DoTrickPose(eb, 1)
					else
						eb.state = S_PLAY_TRICKALT_1
					end
					HandleHomingEnd(eb, 0)
				end
				if p.rettarget
					p.rettarget,p.ret = 0,0
				end
				SpawnFaker(enemy, p)
				S_IncrementModernChain(eb) return false --
			end
		end
	end
end, MT_PLAYER)

//super flinging
local function CheckFling(pmo, enemy)
    local p = pmo.valid and pmo.player
	if pmo.skin == 'modernsonic'
    and p and enemy.valid
    and (enemy.z <= p.mo.z + p.mo.height + (FU*5))
    and (p.mo.z <= enemy.z + enemy.height + (FU*5))
	and p.powers[pw_super]
    and (enemy.flags & MF_ENEMY)
	--and enemy.health <= 1
	--and not (enemy.flags2 & MF2_FRET)
	and not (p.boosting or (p.airboost and p.airboostheld) or p.customhoming > 0)
		if not enemy.flung
			SpawnFaker(enemy, p)
		end
        return false
    end
end

local function footsweep(mo, enemy)
    if mo and enemy.valid
    and (enemy.z <= mo.z + mo.height)
    and (mo.z <= enemy.z + enemy.height)
		if ((enemy.flags & (MF_ENEMY|MF_BOSS|MF_MONITOR)) or enemy.type == MT_SPIKE or enemy.type == MT_TNTBARREL or enemy.type == MT_WALLSPIKE)
			if enemy.health <=2 or (enemy.type == MT_TNTBARREL)
				SpawnFaker(enemy, mo.target.player)
			else
				P_DamageMobj(enemy, mo.target, mo.target, 2)
			end
			if enemy.type == MT_SPIKE or enemy.type == MT_WALLSPIKE
				P_KillMobj(enemy, mo.target, mo.target)
			end
		end
        return false --
    end
end
addHook("MobjCollide", CheckFling, MT_PLAYER)
addHook("MobjMoveCollide", CheckFling, MT_PLAYER)
addHook("MobjCollide", footsweep, MT_FOOTSWEEP)
addHook("MobjMoveCollide", footsweep, MT_FOOTSWEEP)

local function fakerDied(mo)
	if mo.valid and not mo.kill and mo.targetenemy.valid
		mo.kill = true
		if mo.targetenemy.valid and mo.targetenemy.flags & (MF_ENEMY|MF_BOSS)
			SpawnBoostEnergy(mo, 4, 1)
			mo.targetplayer.player.enemyscore = $+100
		end
		if mo.targetenemy.type == MT_GSNAPPER	
		and mo.targetenemy.tracer
		and mo.targetenemy.tracer.tracer
		and mo.targetenemy.tracer.tracer.tracer
		and mo.targetenemy.tracer.tracer.tracer.tracer
		and mo.targetenemy.tracer.tracer.tracer.tracer.tracer
			local snappersAreFuckingStupid = 
			{
				mo.targetenemy.tracer,
				mo.targetenemy.tracer.tracer,
				mo.targetenemy.tracer.tracer.tracer,
				mo.targetenemy.tracer.tracer.tracer.tracer,
				mo.targetenemy.tracer.tracer.tracer.tracer.tracer
			}
			local fucker
			for i = 1,5
				fucker = snappersAreFuckingStupid[i]
				if fucker and fucker.valid
					P_RemoveMobj(fucker)
				end
			end
		end
		if mo.targetenemy.explode
			--P_RadiusAttack(mo, mo.targetplayer, 1000*FU)
			local explosionmobj = P_SpawnMobjFromMobj(mo, 0,0,0, MT_GFZFLOWER1)
			explosionmobj.flags2 = $|MF2_DONTDRAW
			explosionmobj.fuse = 65
			S_StartSound(explosionmobj, sfx_bkpoof)
			local px = mo.x
			local py = mo.y
			local br = 525*FU
			searchBlockmap("objects", function(mo, found)
				if found.valid and (found.flags & MF_ENEMY) and not found.flung
					SpawnFaker(found, mo.targetplayer.player)
					S_IncrementModernChain(mo.targetplayer)
					found.explode = true
				end
			end, mo, px-br, px+br, py-br, py+br)
			mo.targetenemy.explode = nil
		end
		mo.targetenemy.state = mo.targetenemy.info.deathstate
		if mo.targetenemy.valid
			P_KillMobj(mo.targetenemy, mo.targetplayer, mo.targetplayer)
		end
		P_RemoveMobj(mo) 
	end
end

addHook("MobjThinker", function(mo)
	if mo.valid and mo.targetenemy and mo.targetenemy.valid
		local speed = R_PointToDist2(0,0, mo.momx, mo.momy)
		mo.targetenemy.rollangle = $ + abs(FixedAngle(mo.momz + (P_RandomRange(1, 15)*FU)))*(-mo.switch)
		mo.targetenemy.angle = $ - abs(FixedAngle(speed)+mo.random)*mo.switch
		mo.storedz = (abs(mo.momz) > 0) and mo.momz or $
		if mo.momz == 0
		and abs(mo.storedz) > FU
			mo.momz = -mo.storedz
			PlayEnemySound(mo, 1)
		end
		mo.targetenemy.flags = $ & ~MF_SOLID
		if mo.targetenemy.type == MT_PYREFLY
			mo.targetenemy.state = mo.targetenemy.info.spawnstate
		end
		if mo.storedtype == MT_PTERABYTE
			mo.pterabyteTimer = $==nil and 1 or $-1
			if mo.pterabyteTimer == 0
				mo.pmo.player.powers[pw_ignorelatch] = 0
			elseif mo.pterabyteTimer == 1
				mo.pmo.player.powers[pw_ignorelatch] = 32769
			end
		end
		if mo.targetenemy 
			P_MoveOrigin(mo.targetenemy, mo.x, mo.y, mo.z)
			mo.targetenemy.health = 0
		end
		if mo.dontkillthisthing 
			mo.dontkillthisthing = $-1
		end
		if P_IsObjectOnGround(mo) and mo.dontkillthisthing == 0
			fakerDied(mo)
		end
		
	end
end, MT_FOUNDYOUFAKER)

addHook("MobjMoveBlocked", fakerDied, MT_FOUNDYOUFAKER)
addHook("MobjRemoved", fakerDied, MT_FOUNDYOUFAKER)
addHook("MobjDeath", fakerDied, MT_FOUNDYOUFAKER)

