addHook("JumpSpecial", function(player)
	local mo = player.mo
	if mo.skin != "modernsonic"
	or player.pflags & PF_JUMPSTASIS
	or player.pflags & PF_JUMPDOWN
		return --
	end
	
	if ((P_IsObjectOnGround(mo) or mo.eflags&MFE_JUSTHITFLOOR)
	and not (player.pflags&PF_JUMPED))
	or player.modernwallslide or player.climbing
		player.pflags = $ &~ PF_SPINNING
		local jumpfactor = player.jumpfactor
		local climbing = player.climbing
		if player.modernwallslide
			
			--P_InstaThrust(mo, player.drawangle, max(WALLJUMPTHRUST*mo.scale, player.speed*3/2))
			
			--player.pflags = $ &~ PF_JUMPED
			--P_DoJump(player, false)
			
			player.modernwallslide = 0
			player.modernwalljump = true
			LineJump(player)
			--mo.state = S_PLAY_TRICK1_1
			--mo.tics = -1
		else
			
			P_DoJump(player, false)
			mo.state = S_PLAY_JUMP
		end
		
		player.jumpfactor = jumpfactor
		
		//Oh, guess we didn't actually jump
		if P_IsObjectOnGround(mo)
			player.pflags = $ &~ PF_JUMPED
		end
		return true
	end
end)

rawset(_G,"CR_QTE", 69)

addHook("ThinkFrame", do
	for player in players.iterate
		local p = player --Golden Shine: to make this easier on me.
		local s = p.mo
		
		if not (s and s.skin=="modernsonic") --For the non Moderns.
			if p.ret and p.ret.valid
				p.rettarget = 0
				P_RemoveMobj(p.ret)
				p.ret = 0
			end
			if p.overlay and p.overlay.valid
				P_RemoveMobj(p.overlay)
			end
			p.overlay = nil
			if p.shoesoverlay and p.shoesoverlay.valid
				P_RemoveMobj(p.shoesoverlay)
				p.shoesoverlay = nil
			end
			if p.clothoverlay and p.clothoverlay.valid
				P_RemoveMobj(p.clothoverlay)
				p.clothoverlay = nil
			end
			if p.flameoverlay and p.flameoverlay.valid
				P_RemoveMobj(p.flameoverlay)
				p.flameoverlay = nil
			end
			if p.superaura and p.superaura.valid
				P_RemoveMobj(p.superaura)
				p.superaura = nil
			end
			if p.wasjustmodern and p.wasjustmoderntimer
				p.wasjustmoderntimer = $-1
			end
			if not p.wasjustmoderntimer
				p.wasjustmodern = nil
			end
			p.dontdisplaymarker = false			
			continue --
		end
		
		--From here on out, we're modern sonic and have a player mo!
		
		if p.variablesset == nil
			resetmodern(p)
		end
		--2D mode check
		local twod = false
		if (twodlevel) or (player.mo.flags2 & MF2_TWOD) 
			twod = true
		end
		--Golden Shine: throwing stuff in
		if s.boostfailpuff
			s.boostfailpuff = $-1
		end
		if s.boostcashback and leveltime%5==0
			if p.airboostheld or p.boosting
				s.boostcashback = $-1
			end
		end
		--Fixing the "Sonic jet-ass" glitch after homing attacks
		if not p.mysticsuper and not p.powers[pw_super]
			if not P_IsObjectOnGround(s)
			--	print("Airboost:"+p.airboost+" boosting:\x84"+p.boosting)
				if p.powers[pw_carry] or (p.airboost and p.boostmeter and p.boosting or p.boosting)
					s.modernjetspeed = p.speed+(8*s.scale) --This is fine, continue.
					s.MS_NoDragTime = 3
				else
					local MAX = 96*s.scale
					if s.modernjetspeed and (s.state==S_PLAY_AIRBOOST or p.panim==PA_FALL) and (abs(s.momz) < 9*s.scale) --Set it right.
						local ringspeed = 0
						if p.rings ringspeed = p.rings/17 end
						if (s.modernjetspeed < (36+ringspeed)*s.scale)
							s.modernjetspeed = (36+ringspeed)*s.scale
						elseif (s.modernjetspeed > (114+ringspeed)*s.scale) and (s.modernjetspeed != 931<<16)
							s.modernjetspeed = (114+ringspeed)*s.scale
						end
						s.MS_NoDragTime = 0
						MAX = max($, s.modernjetspeed)
					else
						s.MS_NoDragTime = (s.MS_NoDragTime or 0)+1
						if (s.MS_NoDragTime > 5) MAX = 50*s.scale end
					end
					if (p.speed > MAX) and (player.mo.state ~= S_PLAY_AIRKICK)
						if (p.normalspeed >  s.modernjetspeed)
							p.normalspeed = s.modernjetspeed
						end
						ModernSpeedSystem(s,p) --Slow the fuck down.
					end
				end	
			else
				s.modernjetspeed = p.speed+(8*s.scale)
			end
		end
		
		
		if (player.powers[pw_carry] == CR_NIGHTSMODE)
			player.mo.frame = $|FF_FULLBRIGHT
		end
		if player.minecartjumpframe > 5
			player.minecartjumpframe = 0
		end
		//funni idle
		if player.mo.state == S_PLAY_STND --and player.powers[pw_super] == 0
			if player.cmd.buttons & BT_TOSSFLAG and player.cmd.buttons & BT_FIRENORMAL
				player.mo.state = S_PLAY_BOREDOM
			end
		end
		if player.mo.state == S_PLAY_BOREDOM
			if player.speed > 0
				player.mo.state = S_PLAY_WALK
			end
		end
		if player.mo.state == S_PLAY_WAIT
			if player.mo.useAltFrames == nil
			and player.mo.sprite2 != SPR2_CNT1
				player.mo.useAltFrames = P_RandomChance(FU/2)
			end
			local theFrames = player.mo.useAltFrames and 2 or 0
			if (player.mo.frame & FF_FRAMEMASK) == A+theFrames
			and player.mo.sprite2 != SPR2_CNT1
				player.mo.frame = $ & (~FF_FRAMEMASK)|abs(theFrames-2)
			end
		else
			player.mo.useAltFrames = nil
		end
		//shit for boss perfect and other stuff lmao
		if (player.mo.eflags & MFE_JUSTHITFLOOR and player.mo.eflags & MFE_ONGROUND)
		or P_IsObjectOnGround(player.mo)
			if player.pflags & PF_SLIDING
			and player.mo.eflags & MFE_TOUCHWATER
			and not (player.mo.eflags & MFE_UNDERWATER)
				--player.mo.state = S_PLAY_SLIDE
				if player.powers[pw_super]
					player.mo.sprite2 = SPR2_SLID|FF_SPR2SUPER 
				else
					player.mo.sprite2 = SPR2_SLID
				end
				player.mo.frame = $ & (~FF_FRAMEMASK)|A
				if player.powers[pw_super]
					player.mo.frame = $|FF_FULLBRIGHT
				end
			end
			if #player.bossperfect > 1
				player.bossperfect = {0}
				S_EndCombo(player.mo)
			end
			if not player.mo.enemyComboTimer
				if player.mo.enemyCombo
					player.mo.enemyComboTimer = min(100, (player.mo.enemyComboPreTimer or TICRATE/4))
					player.mo.enemyComboPreTimer = 0
				end
			elseif player.mo.enemyComboTimer == 1
				S_EndCombo(player.mo)
			end
		end
		if player.chainPointsTimer
			P_AddPlayerScore(player, 250)
		end
		player.mo.enemyComboTimer = ($ or 0)>0 and max(1, ($ or 1) - 1) or 0
		player.mo.HUDEnemyTimerFade = max(0, ($ or 1) - 1) 
		player.mo.HUDEnemyTimer = max(0, ($ or 1) - 1) 
		player.mo.HUDEnemyTimerInit = max(0, ($ or 1) - 1)
		player.chainPointsTimer = max(0, ($ or 1) - 1)
		if not player.mo.HUDEnemyTimerFade
			player.mo.storedEnemyCombo = 0
		end
		if player.lastangle == nil
			player.lastangle = player.drawangle
		end
		if player.angleturn == nil
			player.angleturn = 0
		end
		if player.manualdrifting == false
			if player.angleturn < 0
				player.angleturn = $+1
			elseif player.angleturn > 0
				player.angleturn = $-1
			end
		end
		if not player.candrift
			player.driftcancel = 0
		end
		if player.driftcancel > 10
			player.candrift = false
			player.manualdrifting = false
		elseif player.driftcancel > 0 and leveltime % 2 == 1
			player.driftcancel = $-1
		end
		
		//Drift but smooth
		if p.modernmenu.contents[2][6].value == 1 and p.playerstate == PST_LIVE -- Drift
		or p.modernmenu.contents[2][6].value == 2 and not p.boosting and p.playerstate == PST_LIVE -- Drift
		
			p.driftangle = (AngleFixed(R_PointToAngle2(0, 0, p.mo.momx, p.mo.momy)-p.lastangle)/FU)
			
			//auto drift while boosting
			if (p.boosting == true or (p.cmd.buttons & BT_ATTACK))
			and not (p.pflags & PF_SLIDING)
			and not (twodlevel)
			and not (p.mo.flags2 & MF2_TWOD)
			and FixedHypot(p.mo.momx, p.mo.momy) > 20*p.mo.scale
			and not (p.powers[pw_carry])
			and not (p.exiting)
			and P_IsObjectOnGround(p.mo)
			and not (p.pflags & PF_SPINNING)
			and not p.quickstepping
				if ((p.driftangle < 357 and p.driftangle > 180 and p.manualdrifting == false)
				or ((p.cmd.sidemove > 2 and (p.cmd.buttons & BT_ATTACK))) and P_IsObjectOnGround(p.mo))
				and p.manualdrifting == false
					if p.angleturn <= 1
					and p.angleturn >= -1
						p.driftdirection = 1
						p.angleturn = p.bsoldanalog and 8 or 4
						p.candrift = true
					end
				elseif (
				(p.driftangle > 2 and p.driftangle < 180)
				or ((p.cmd.sidemove < -2 and (p.cmd.buttons & BT_ATTACK))) and P_IsObjectOnGround(p.mo)
				) 
				and p.manualdrifting == false
					if p.angleturn <= 1
					and p.angleturn >= -1
						p.angleturn = p.bsoldanalog and -8 or -4
						p.driftdirection = -1
						p.candrift = true
					end
				elseif not (p.cmd.buttons & BT_ATTACK)
					p.candrift = false
					p.driftdirection = 0
				end
				if p.cmd.sidemove ~= 0
				and (p.cmd.buttons & BT_ATTACK)
				and p.candrift
				and not p.manualdrifting
					p.manualdrifting = true
					if p.modernmenu.contents[6][1].value == 1 -- Voices
						if p.modernmenu.contents[6][2].value == 0
							PlayModernSound(player, 31)
						elseif p.modernmenu.contents[6][2].value == 1
							PlayModernSound(player, 32)
						elseif p.modernmenu.contents[6][2].value == 2
							PlayModernSound(player, 33)
						elseif p.modernmenu.contents[6][2].value == 3
							PlayModernSound(player, 34)
						elseif p.modernmenu.contents[6][2].value == 4
							PlayModernSound(player, 25)
						elseif p.modernmenu.contents[6][2].value == 5
							PlayModernSound(player, 26)
						end
					end
				end
			elseif p.manualdrifting == false
				p.candrift = false
				p.driftdirection = 0
			end
			if (p.pflags & PF_ANALOGMODE) and not (p.pflags & PF_DIRECTIONCHAR)
				p.bsoldanalog = true
			else
				p.bsoldanalog = false
			end
			//manual drift
			if P_IsObjectOnGround(s)
			and p.manualdrifting 
			and p.candrift
			and not (p.pflags & PF_SPINNING)
				if p.angleturntimer == nil
					p.angleturntimer = 0
				end
				p.sliding = 0
				p.angleturntimer = $+1
				if p.cmd.sidemove > 1
					if p.angleturntimer > 3
					and p.angleturn < 12
						p.angleturn = $ + (p.bsoldanalog and (p.boosting and 4 or 2) or (p.boosting and 2 or 1))
						p.angleturntimer = 0
					end
					if p.angleturn < 0
						p.angleturn = 1
						p.driftdirection = 1
						p.driftsens = 0
					end
				elseif p.cmd.sidemove < -1
					if p.angleturntimer > 3 
					and p.angleturn > -12
						p.angleturn = $ - (p.bsoldanalog and (p.boosting and 4 or 2) or (p.boosting and 2 or 1))
						p.angleturntimer = 0
					end
					if p.angleturn > 0
						p.angleturn = -1
						p.driftdirection = -1
						p.driftsens = 0
					end
				elseif p.cmd.sidemove <= 1
				and p.cmd.sidemove >= -1
					if p.angleturn > 1
						p.angleturn = $ - (p.bsoldanalog and (p.boosting and 4 or 2) or (p.boosting and 2 or 1))
						p.driftdirection = 1
					end
					if p.angleturn < -1
						p.angleturn = $ + (p.bsoldanalog and (p.boosting and 4 or 2) or (p.boosting and 2 or 1))
						p.driftdirection = -1
					end
				end
				local sidemove = ((p.cmd.sidemove)/5)*FU
				if (p.modernmenu.contents[2][6].value == 1 or (p.modernmenu.contents[2][6].value == 2 and not (p.boosting))) -- Drift
					if p.cmd.sidemove >= 2 
						p.mimicangle = $-FixedAngle(min(sidemove+2*FU,p.angleturn*FU))
					elseif p.cmd.sidemove <= -2
						p.mimicangle = $-FixedAngle(max(sidemove-2*FU,p.angleturn*FU))
					else
						p.mimicangle = $-FixedAngle(p.angleturn*FU) 
					end
				end
				if p.angleturn > 12
					p.angleturn = 12
				end
				if p.angleturn < -12
					p.angleturn = -12
				end
				if p.angleturn < 1
				and p.driftdirection == 1
				and p.cmd.sidemove < -1
					if p.modernmenu.contents[6][1].value == 1 -- Voices
						if p.modernmenu.contents[6][2].value == 0
							PlayModernSound(player, 31)
						elseif p.modernmenu.contents[6][2].value == 1
							PlayModernSound(player, 32)
						elseif p.modernmenu.contents[6][2].value == 2
							PlayModernSound(player, 33)
						elseif p.modernmenu.contents[6][2].value == 3
							PlayModernSound(player, 34)
						elseif p.modernmenu.contents[6][2].value == 4
							PlayModernSound(player, 25)
						elseif p.modernmenu.contents[6][2].value == 5
							PlayModernSound(player, 26)
						end
					end
					p.driftsens = 0
					p.angleturn = -1
					p.driftdirection = -1
				end
				if p.angleturn > -1
				and p.driftdirection == -1
				and p.cmd.sidemove > 1
					if p.modernmenu.contents[6][1].value == 1 -- Voices
						if p.modernmenu.contents[6][2].value == 0
							PlayModernSound(player, 31)
						elseif p.modernmenu.contents[6][2].value == 1
							PlayModernSound(player, 32)
						elseif p.modernmenu.contents[6][2].value == 2
							PlayModernSound(player, 33)
						elseif p.modernmenu.contents[6][2].value == 3
							PlayModernSound(player, 34)
						elseif p.modernmenu.contents[6][2].value == 4
							PlayModernSound(player, 25)
						elseif p.modernmenu.contents[6][2].value == 5
							PlayModernSound(player, 26)
						end
					end
					p.driftsens = 0
					p.angleturn = 1
					p.driftdirection = 1
				end
				if p.angleturn == 0
				and p.cmd.sidemove <= 1
				and p.cmd.sidemove >= -1
					if p.driftdirection == 1
						p.angleturn = 1
					end
					if p.driftdirection == -1
						p.angleturn = -1
					end
				end
				if not p.quickstepping
					local driftspeed = p.boosting and p.boostspeed or p.normalspeed
					P_InstaThrust(s, p.mimicangle, FixedMul(driftspeed, s.scale))
					p.charflags = $|SF_NOSKID
				end
			end
			
			if P_PlayerInPain(player) 
			or p.quickstepping
			or not P_IsObjectOnGround(s)
			or FixedHypot(s.momx, s.momy) < 20*s.scale
			or (((p.driftangle >= 357) or (p.driftangle <= 2)) and not p.manualdrifting)
			or (p.exiting)
				p.candrift = false
				p.manualdrifting = false
			end
			if not (p.cmd.buttons & BT_ATTACK) 
				p.manualdrifting = false
			end
			if P_IsObjectOnGround(s) 
			and p.candrift == true
				if p.drifttime == nil
					p.drifttime = 0
				else
					p.drifttime = $+1
				end
				if (p.drifttime >= (p.boosting and 10 or 6))
					p.boostmeter = $ + 1
					p.drifttime = 0
				end
				if not p.driftsens
					p.driftsens = 1
				else
					p.driftsens = $+1
				end
				if p.driftsens
				and p.driftsens <= 6
					p.drawangle = p.mimicangle
				end
				if (p.driftsens > 6) //Spam drifting sounds and smoke!
					p.drawangle = R_PointToAngle2(0, 0, s.momx, s.momy) + (p.driftdirection == 1 and -ANG30 or ANG30)
					local i = 0 while i <= (leveltime%7)/2 // 1, 2, 3 or 4 particles
						local particle = P_SpawnMobj(s.x, s.y, s.z, MT_SPINDUST)
						P_TryMove(particle, particle.x+P_ReturnThrustX(nil,p.drawangle+ANGLE_180,s.radius),
						particle.y+P_ReturnThrustY(nil,p.drawangle+ANGLE_180,s.radius), true)

						if s.eflags & (MFE_TOUCHWATER|MFE_UNDERWATER)
							particle.state = S_SMALLBUBBLE
						elseif (p.powers[pw_shield] & SH_NOSTACK) == SH_ELEMENTAL
						or p.firesonic
							particle.state = S_SPINDUST_FIRE1
						end
						
						particle.target = s
						particle.fuse = TICRATE/4 
						particle.destscale = (2*s.scale)/3
						P_SetScale(particle, particle.destscale)
						if (s.eflags & MFE_VERTICALFLIP) // readjust z position if needed
							particle.z = s.z + s.height - particle.height
						end
						local prandom = {}
						prandom[0] = P_RandomFixed()<<2 // P_RandomByte()<<10
						prandom[1] = P_RandomRange(-30, 30) // P_RandomRange(-ANG30/FRACUNIT, ANG30/FRACUNIT)*FRACUNIT
						prandom[2] = P_RandomFixed()<<3 // P_RandomByte()<<11
						P_SetObjectMomZ(particle, p.maxdash/50 + prandom[0], false)
						P_InstaThrust(particle,
								p.drawangle + (prandom[1]*ANG1),
								-FixedMul(p.maxdash/12 + FRACUNIT + prandom[2], s.scale))
						particle.momx = $+s.momx
						particle.momy = $+s.momy
						P_TryMove(particle, particle.x+particle.momx, particle.y+particle.momy, true)
						
						i = $+1
					end
					if p.driftdirection == 1
						s.state = S_PLAY_DRIFTRIGHT
					end
					if p.driftdirection == -1
						s.state = S_PLAY_DRIFTLEFT
					end
					if not (p.driftmobj and p.driftmobj.valid) then
						p.driftmobj = P_SpawnMobj(s.x, s.y, s.z, MT_GFZFLOWER1)
						p.driftmobj.flags2 = $|MF2_DONTDRAW
						if not (s.eflags & MFE_TOUCHWATER)
							S_StartSoundAtVolume(p.driftmobj, sfx_drift, 155)
						end
						P_MoveOrigin(p.driftmobj, s.x, s.y, s.z)
						p.driftmobj.fuse = 65
					elseif (p.driftmobj and p.driftmobj.valid)
						P_MoveOrigin(p.driftmobj, s.x, s.y, s.z)
					end
				end
			elseif p.driftsens and P_IsObjectOnGround(s)
				p.driftsens = 0
			end
			
			p.lastangle = R_PointToAngle2(0, 0, s.momx, s.momy)
			
			if p.candrift == false and p.driftmobj and p.driftmobj.valid
				S_StopSound(p.driftmobj) P_RemoveMobj(p.driftmobj)
			end
			if p.candrift == false
			or p.driftsens <= 6
				if s.state == S_PLAY_DRIFTRIGHT
				or s.state == S_PLAY_DRIFTLEFT
					if not p.quickstepping
						if P_IsObjectOnGround(s)
							s.state = S_PLAY_RUN
						else
							s.state = S_PLAY_FALL
						end
					end
				end
			end
			p.lastangleturn = p.cmd.angleturn
		end
		
		//drift but fixed
		if p.modernmenu.contents[2][6].value==0 and p.playerstate == PST_LIVE -- Drift
		or p.modernmenu.contents[2][6].value==2 and p.boosting and p.playerstate == PST_LIVE
		
			p.driftangle = (AngleFixed(R_PointToAngle2(0, 0, s.momx, s.momy)-p.lastangle)/FU)
			
			//auto drift while boosting
			if (p.boosting == true or (p.cmd.buttons & BT_ATTACK))
			and not (p.pflags & (PF_SPINNING|PF_SLIDING))
			and not (twodlevel) and not (s.flags2 & MF2_TWOD)
			and FixedHypot(s.momx, s.momy) > 20*s.scale
			
				if (p.driftangle < 357 and p.driftangle > 180)
				or (p.cmd.sidemove > 2) and (p.cmd.buttons & BT_ATTACK)
					if p.driftdirection == -1
						p.driftsens = 0
						if p.modernmenu.contents[6][1].value == 1 -- Voices
							if p.modernmenu.contents[6][2].value == 0
								PlayModernSound(player, 31)
							elseif p.modernmenu.contents[6][2].value == 1
								PlayModernSound(player, 32)
							elseif p.modernmenu.contents[6][2].value == 2
								PlayModernSound(player, 33)
							elseif p.modernmenu.contents[6][2].value == 3
								PlayModernSound(player, 34)
							elseif p.modernmenu.contents[6][2].value == 4
								PlayModernSound(player, 25)
							elseif p.modernmenu.contents[6][2].value == 5
								PlayModernSound(player, 26)
							end
						end
					end
					p.driftdirection = 1
					p.candrift = true
				elseif (p.driftangle > 2 and p.driftangle < 180)
				or p.cmd.sidemove < -2 and (p.cmd.buttons & BT_ATTACK)
					if p.driftdirection == 1
						p.driftsens = 0
						if p.modernmenu.contents[6][1].value == 1 -- Voices
							if p.modernmenu.contents[6][2].value == 0
								PlayModernSound(player, 31)
							elseif p.modernmenu.contents[6][2].value == 1
								PlayModernSound(player, 32)
							elseif p.modernmenu.contents[6][2].value == 2
								PlayModernSound(player, 33)
							elseif p.modernmenu.contents[6][2].value == 3
								PlayModernSound(player, 34)
							elseif p.modernmenu.contents[6][2].value == 4
								PlayModernSound(player, 25)
							elseif p.modernmenu.contents[6][2].value == 5
								PlayModernSound(player, 26)
							end
						end
					end
					p.driftdirection = -1
					p.candrift = true
				elseif not (p.cmd.buttons & BT_ATTACK)
					p.candrift = false
					p.driftdirection = 0
				end
				if p.cmd.sidemove ~= 0
				and (p.cmd.buttons & BT_ATTACK)
				and p.candrift
				and not p.manualdrifting
				and not (p.pflags & PF_SPINNING)
					p.manualdrifting = true
					if p.modernmenu.contents[6][1].value == 1 -- Voices
						if p.modernmenu.contents[6][2].value == 0
							PlayModernSound(player, 31)
						elseif p.modernmenu.contents[6][2].value == 1
							PlayModernSound(player, 32)
						elseif p.modernmenu.contents[6][2].value == 2
							PlayModernSound(player, 33)
						elseif p.modernmenu.contents[6][2].value == 3
							PlayModernSound(player, 34)
						elseif p.modernmenu.contents[6][2].value == 4
							PlayModernSound(player, 25)
						elseif p.modernmenu.contents[6][2].value == 5
							PlayModernSound(player, 26)
						end
					end
				end
			elseif p.manualdrifting == false
				p.candrift = false
				p.driftdirection = 0
			end
			if (p.pflags & PF_ANALOGMODE)
				p.bsoldanalog = true
			else
				p.bsoldanalog = false
			end
			//manual drift
			if P_IsObjectOnGround(s)
			and p.manualdrifting 
			and p.candrift
			and not (p.pflags & PF_SPINNING)
			--and (s.state == S_PLAY_DRIFTLEFT or s.state == S_PLAY_DRIFTRIGHT)
				local sidemove = (abs(p.cmd.sidemove*FU)/10)+(1*FU)
				if p.driftdirection == 1
					p.mimicangle = $ - (p.cmd.sidemove > 0 and FixedAngle(4*FU+sidemove) or FixedAngle(4*FU))
				else --if p.driftdirection == -1
					p.mimicangle = $ + (p.cmd.sidemove < 0 and FixedAngle(4*FU+sidemove) or FixedAngle(4*FU))
				end
				P_InstaThrust(s, p.mimicangle, p.boosting and p.boostspeed or p.normalspeed)
				p.charflags = $|SF_NOSKID
			end
			if P_PlayerInPain(player) or not P_IsObjectOnGround(s) or FixedHypot(s.momx, s.momy) < 10*s.scale
			or ((p.driftangle>=357) or (p.driftangle<=2)) and not p.manualdrifting
				p.candrift = false
				p.manualdrifting = false
			end
			if not (p.cmd.buttons & BT_ATTACK)
				p.manualdrifting = false
			end
					
			if P_IsObjectOnGround(s) and p.candrift == true and not (p.pflags & PF_SPINNING)
				if p.drifttime == nil
					p.drifttime = 0
				else
					p.drifttime = $+1
				end
				if (p.drifttime >= 5)
					p.boostmeter = $ + 1
					p.drifttime = 0
				end
				if not p.driftsens
					p.driftsens = 1
				else
					p.driftsens = $+1
				end
				
				if (p.driftsens > 6) //Spam drifting sounds and smoke!
					p.drawangle = R_PointToAngle2(0, 0, s.momx, s.momy) + (p.driftdirection == 1 and -ANG30 or ANG30)

					local particle
					local prandom = {}
					local i = 0 while i <= (leveltime%7)/2 // 1, 2, 3 or 4 particles
						particle = P_SpawnMobj(s.x, s.y, s.z, MT_SPINDUST)
						P_TryMove(particle, particle.x+P_ReturnThrustX(nil,p.drawangle+ANGLE_180,s.radius),
						particle.y+P_ReturnThrustY(nil,p.drawangle+ANGLE_180,s.radius), true)

						if s.eflags & (MFE_TOUCHWATER|MFE_UNDERWATER)
							particle.state = S_SMALLBUBBLE
						elseif (p.powers[pw_shield] & SH_NOSTACK) == SH_ELEMENTAL
						or p.firesonic
							particle.state = S_SPINDUST_FIRE1
						end
						
						particle.target = s
						particle.destscale = (2*s.scale)/3
						P_SetScale(particle, particle.destscale)
						if (s.eflags & MFE_VERTICALFLIP) // readjust z position if needed
							particle.z = s.z + s.height - particle.height
						end
						prandom[0] = P_RandomFixed()<<2 // P_RandomByte()<<10
						prandom[1] = P_RandomRange(-30, 30) // P_RandomRange(-ANG30/FRACUNIT, ANG30/FRACUNIT)*FRACUNIT
						prandom[2] = P_RandomFixed()<<3 // P_RandomByte()<<11
						P_SetObjectMomZ(particle, p.maxdash/50 + prandom[0], false)
						P_InstaThrust(particle, p.drawangle + (prandom[1]*ANG1), -FixedMul(p.maxdash/12 + FRACUNIT + prandom[2], s.scale))
						particle.momx = $+s.momx
						particle.momy = $+s.momy
						P_TryMove(particle, particle.x+particle.momx, particle.y+particle.momy, true)
						
						i = $+1
					end
					if p.driftdirection == 1
						s.state = S_PLAY_DRIFTRIGHT
					end
					if p.driftdirection == -1
						s.state = S_PLAY_DRIFTLEFT
					end
					if not (p.driftmobj and p.driftmobj.valid) then
						p.driftmobj = P_SpawnMobj(s.x, s.y, s.z, MT_GFZFLOWER1)
						p.driftmobj.flags2 = $|MF2_DONTDRAW
						S_StartSound(p.driftmobj, sfx_drift)
						P_MoveOrigin(p.driftmobj, s.x, s.y, s.z)
						p.driftmobj.fuse = 65
					elseif (p.driftmobj and p.driftmobj.valid)
						P_MoveOrigin(p.driftmobj, s.x, s.y, s.z)
					end
				end
			elseif p.driftsens and P_IsObjectOnGround(s)
				p.driftsens = 0
			end
			
			p.lastangle = R_PointToAngle2(0, 0, s.momx, s.momy)
			
			if p.candrift == false and p.driftmobj and p.driftmobj.valid
				S_StopSound(p.driftmobj) P_RemoveMobj(p.driftmobj)
			end
			if p.candrift == false or p.driftsens <= 6
				if s.state == S_PLAY_DRIFTRIGHT
				or s.state == S_PLAY_DRIFTLEFT
					if P_IsObjectOnGround(s)
						s.state = S_PLAY_RUN
					else
						s.state = S_PLAY_FALL
					end
				end
			end
			p.lastangleturn = p.cmd.angleturn
		end
		
		
		
		s.MS_WepPrev = (p.cmd.buttons & BT_WEAPONPREV) and (s.MS_WepPrev or 0)+1 or 0
		s.MS_WepNext = (p.cmd.buttons & BT_WEAPONNEXT) and (s.MS_WepNext or 0)+1 or 0
		// ...... Quick Stepping?
		if s.MS_WepNext==1 or s.MS_WepPrev==1
			if ((p.quickstepping or 0) < 4) 
				if P_IsObjectOnGround(s)
				or p.panim==PA_WALK or p.panim==PA_RUN or p.panim==PA_DASH
					if not (p.exiting) and not p.nomovecounter
				/*	and not p.abilitylock
					and not (p.crouching)
					and not (p.crawling)
					and not (p.sliding)
					and not (p.manualdrifting)		*/	
					
						local LEFTRIGHT = 0
						if s.MS_WepNext==1 and abs(p.drawangle - (p.cmd.angleturn<<16)) < ANGLE_90
						or s.MS_WepPrev==1 and abs(p.drawangle - (p.cmd.angleturn<<16)) >= ANGLE_90
							LEFTRIGHT = 1
						end
						if s.MS_WepPrev==1 and abs(p.drawangle - (p.cmd.angleturn<<16)) < ANGLE_90
						or s.MS_WepNext==1 and abs(p.drawangle - (p.cmd.angleturn<<16)) >= ANGLE_90
							LEFTRIGHT = -1
						end
						
						if LEFTRIGHT!=0
							p.qsdirection = LEFTRIGHT
							p.quickstepping = 10
							S_StartSound(s, (s.eflags & MFE_UNDERWATER) and sfx_quiksw or sfx_quiks)
							p.jt = -4
							s.MS_WepNext,s.MS_WepPrev = 99<<16,99<<16
							if not P_IsObjectOnGround(s)
								P_SetObjectMomZ(s, -5<<16, true)
							end
						end
					end
				end
			end
		end
		--if S_SoundPlaying(s, sfx_sonicd)
			--S_StopSoundByID(s, sfx_sonicd)
		--end
		if p.quickstepping 
			p.quickstepping = $-1
			if p.quickstepping > 5
				p.pflags = $ & ~(PF_SPINNING|PF_STARTDASH|PF_SLIDING)
				s.state = S_PLAY_QUICKSTEP
				if p.qsdirection == 1
					P_Thrust(s, p.drawangle-ANGLE_90, 23<<16)
					s.sprite2 = SPR2_QKSR
				else--if p.qsdirection == -1
					P_Thrust(s, p.drawangle+ANGLE_90, 23<<16)
					s.sprite2 = SPR2_QKSL
				end
				P_SpawnGhostMobj(s)
				if (p.pflags & PF_STARTJUMP) and (p.cmd.buttons & BT_JUMP)
					p.quickstepping = min($,6)
				end
			else
				if p.quickstepping == 5
					P_InstaThrust(s, p.prevangle, min(p.speed, p.modernprevspeed or 0))
				end
				if (p.pflags & PF_STARTJUMP) and (p.cmd.buttons & BT_JUMP)
					p.quickstepping = min($,1)
				end
			end
		else
			p.modernprevspeed = FixedHypot(s.momx, s.momy)
			p.prevangle = R_PointToAngle2(0,0, s.momx, s.momy) --s.angle
		end
		if p.playerstate == PST_DEAD
		or p.modernmenu.contents[4][1].value == 0
			p.rushmode = 0
		end
		
		if p.tauntwait > 0
			p.tauntwait = $ - 1
		end
		if p.pflags & PF_JUMPED
		and not (p.powers[pw_shield] == SH_ARMAGEDDON)
			p.pflags = $|PF_USEDOWN
		end
		if  (p.powers[pw_carry])
		or (p.pflags & PF_SLIDING)
		or ((p.quickstepping or 0)>4)
			p.crouching = false
			p.sliding = 0
			p.tricking = false
			p.trickable = false
		end
		if p.trickable == true
		and p.tricking == false
		and not (p.pflags & PF_JUMPED)
		and not (P_IsObjectOnGround(s))
		and p.paintimer == 0
			p.pflags = $|PF_JUMPED
			p.jumptimer = 4
			p.justjumped = true
		end
		if P_IsObjectOnGround(s)
		and p.pflags & PF_JUMPED
			p.pflags = $ & ~PF_JUMPED
		end
		if not p.frontflip
			p.frontflip = false
		end
		if not p.timer
			p.timer = 0
		end
		if p.timer > 0
			p.timer = $ - 1
		end
		if not p.frontfliplock
			p.frontfliplock = false
		end
		if (p.superanim or 0) > 0  
			p.frontflip = false
		end
		
		if (s.state == S_PLAY_SPRING)
			p.frontflip = true
			p.powers[pw_strong] = 0
		end
		if p.frontflip == true
			p.frontfliplock = true
		end
		if p.frontfliplock == true
		and (s.state == S_PLAY_FALL)
		and p.stomping == false
			s.state = S_PLAY_ROLL
			p.timer=17
		end
		if p.timer == 0
		and not (player.pflags & PF_THOKKED)
		and player.frontfliplock == true
		and s.state == S_PLAY_ROLL
			s.state = S_PLAY_FALL
			player.frontflip = false
			player.frontfliplock = false 
		end
		if P_IsObjectOnGround(player.mo)
		//or player.pflags & PF_THOKKED
		or player.pflags & PF_THOKKED
		or player.abilitylock == true and player.boosting == false
		or player.stomping == true
		or player.airboost == true
			player.timer = 0
			player.frontflip = 0
			player.frontfliplock = 0
		end
		if player.mo.state >= S_PLAY_TAUNT1
		and player.mo.state <= S_PLAY_TAUNT4
			player.panim = PA_DASH
end
enendayertons & BT_TOSSFLAG)
        and not P_PlayerInPain(player)
		and player.cmd.buttons & BT_CUSTOM2
        and player.playerstate == PST_LIVE
		and P_IsObjectOnGround(player.mo)
		and not (player.mo.eflags & MFE_UNDERWATER)
		and player.tauntwait == 0
		and player.speed == 0
		and not (player.powers[pw_super])
		and player.abilitylock == false
		and not (player.pflags & PF_STARTDASH)
		and player.crouching == false
		and player.mo.state ~= S_PLAY_MODERNVICTORY
			player.powers[pw_nocontrol] = 64
			player.mo.state = S_PLAY_TAUNT1
			player.tauntwait = 70
			if player.modernmenu.contents[6][1].value == 1 -- Voices
				if player.modernmenu.contents[6][2].value == 0
					S_StartSound(player.mo, sfx_taunt1)
				elseif player.modernmenu.contents[6][2].value == 1
					S_StartSound(player.mo, sfx_taunt2)
				elseif player.modernmenu.contents[6][2].value == 2
					S_StartSound(player.mo, sfx_taunt3)
				elseif player.modernmenu.contents[6][2].value == 3
					S_StartSound(player.mo, sfx_taunt4)
				elseif player.modernmenu.contents[6][2].value == 4
					S_StartSound(player.mo, sfx_flgood)
				elseif player.modernmenu.contents[6][2].value == 5
					S_StartSound(player.mo, sfx_goodj)
				end
			end
        end
		if (player.cmd.buttons & BT_TOSSFLAG)
		and player.mo.state == S_PLAY_TAUNT4
			player.powers[pw_nocontrol] = 1
			player.tauntwait = 1
			player.panim = PA_DASH
		elseif not (player.cmd.buttons & BT_TOSSFLAG)
		and player.mo.state == S_PLAY_TAUNT4
			player.mo.state = S_PLAY_STND
		end
		if (player.cmd.buttons & BT_TOSSFLAG)
        and not P_PlayerInPain(player)
		and player.cmd.buttons & BT_CUSTOM3
        and player.playerstate == PST_LIVE
		and P_IsObjectOnGround(player.mo)
		and not (player.mo.eflags & MFE_UNDERWATER)
		and player.tauntwait == 0
		and player.speed == 0
		and not (player.powers[pw_super])
		and player.abilitylock == false
		and not (player.pflags & PF_STARTDASH)
		and player.crouching == false
		and player.mo.state ~= S_PLAY_MODERNVICTORY
			player.powers[pw_nocontrol] = 64
			player.mo.state = S_PLAY_BREAKDANCE1
			player.tauntwait = 70
			if player.modernmenu.contents[6][1].value == 1 -- Voices
				if player.modernmenu.contents[6][2].value == 0
					S_StartSound(player.mo, sfx_taunt5)
				elseif player.modernmenu.contents[6][2].value == 1
					S_StartSound(player.mo, sfx_taunt6)
				elseif player.modernmenu.contents[6][2].value == 2
					S_StartSound(player.mo, sfx_taunt7)
				elseif player.modernmenu.contents[6][2].value == 3
					S_StartSound(player.mo, sfx_taunt8)
				elseif player.modernmenu.contents[6][2].value == 4
					S_StartSound(player.mo, sfx_flgood)
				elseif player.modernmenu.contents[6][2].value == 5
					S_StartSound(player.mo, sfx_goodj)
				end
			end
        end
		if player.mo.state == S_PLAY_BREAKDANCE2
			player.mo.fuck = 1
		end
		if player.mo.state == S_PLAY_BREAKDANCE3
		and not (player.cmd.buttons & BT_TOSSFLAG)
		and player.mo.frame&FF_FRAMEMASK == 13
		and not player.mo.fuck
			player.powers[pw_nocontrol] = 10
			player.tauntwait = 16
			player.mo.state = S_PLAY_BREAKDANCE4
		elseif player.mo.state == S_PLAY_BREAKDANCE3
			if player.mo.fuck and player.mo.fuck < 8
				player.mo.fuck = $+1
				player.mo.state = $
			elseif player.mo.fuck == 8
				player.mo.fuck = nil
			end
			player.powers[pw_nocontrol] = 1
			player.tauntwait = 2
		end
		if player.mo.state == S_PLAY_BREAKDANCE2
		or player.mo.state == S_PLAY_BREAKDANCE3
	-- 		if leveltime %3 == 0
	-- 			player.mo.state = $
	-- 		end
			
			if leveltime %6 == 0
				S_StartSound(player.mo, sfx_bkdnce)
			end
			if leveltime %2 == 0
				DoSpinDashDust(player, 100*FRACUNIT)
			end
			player.drawangle = $+ANGLE_45
		elseif player.mo.state == S_PLAY_BREAKDANCE4
		    if leveltime %1 == 0
				player.mo.state = $
			end
			player.drawangle = player.breakdance_prevdrawangle
		else
			player.breakdance_prevdrawangle = player.drawangle
		end
		if (player.cmd.buttons & BT_TOSSFLAG)
        and not P_PlayerInPain(player)
		and (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 1) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 0)) -- Actionswap
        and player.playerstate == PST_LIVE
		and P_IsObjectOnGround(player.mo)
		and not (player.mo.eflags & MFE_UNDERWATER)
		and player.tauntwait == 0
		and player.speed == 0
		and not (player.powers[pw_super])
		and not (player.pflags & PF_STARTDASH)
		and player.mo.state ~= S_PLAY_MODERNVICTORY
			player.powers[pw_nocontrol] = 64
			player.mo.state = S_PLAY_SA_POSE1
			player.tauntwait = 70
			if player.modernmenu.contents[6][1].value == 1 -- Voices
				if player.modernmenu.contents[6][2].value == 0
					S_StartSound(player.mo, sfx_taunt9)
				elseif player.modernmenu.contents[6][2].value == 1
					S_StartSound(player.mo, sfx_taunt9)
				elseif player.modernmenu.contents[6][2].value == 2
					S_StartSound(player.mo, sfx_taunt9)
				elseif player.modernmenu.contents[6][2].value == 3
					S_StartSound(player.mo, sfx_taunt9)
				elseif player.modernmenu.contents[6][2].value == 4
					S_StartSound(player.mo, sfx_flgood)
				elseif player.modernmenu.contents[6][2].value == 5
					S_StartSound(player.mo, sfx_goodj)
				end
			end
			S_StartSound(player.mo, sfx_uptant)
        end
		if player.mo.state == S_PLAY_SA_POSE2
		and (player.cmd.buttons & BT_TOSSFLAG)
			player.powers[pw_nocontrol] = 1
			player.tauntwait = 1
		elseif player.mo.state == S_PLAY_SA_POSE2
		and not player.tauntwait
			player.mo.state = S_PLAY_STND
		end
		
		
		
		if player.modernmenu.contents[2][3].value == 1 -- ModernFOV
			if player.boosting == true
			or player.superboost == true
			or player.airboost == true
			or player.customhoming
				if player.camerascale > FRACUNIT*5/4
					player.camerascale = $1-8000
				else
					player.camerascale = FRACUNIT*5/4
				end
			elseif not (player.mo.state >= S_PLAY_MODERNTRANSFORM1 and player.mo.state <= S_PLAY_MODERNTRANSFORM11)
				if player.camerascale > FRACUNIT
					
					player.camerascale = player.usedhomingattack and $1-15000 or $1-8000
				end
			end
		else
			player.camerascale = FRACUNIT
		end
		if player.camerascale < FU
		and not (player.mo.state >= S_PLAY_MODERNTRANSFORM1	and player.mo.state <= S_PLAY_MODERNTRANSFORM11)
			player.camerascale = FU
		end
	////////////MISC	
		if not (player.powers[pw_carry] == CR_GRINDRAIL)
		and not player.boostheld
			player.startboost = false
		end
		--top speed check
		if player.topspeed < FixedHypot(player.mo.momx, player.mo.momy)
			player.topspeed = FixedHypot(player.mo.momx, player.mo.momy)
		end
		--shit sound
		if player.modernsound 
			player.modernsound = $-1
		end
		--HUD Check
		if player.wasjustmodern == nil
			player.wasjustmodern = true
		else
			player.wasjustmoderntimer = 2
		end
		
		if not player.powers[pw_extralife]
			player.musicplaying = S_MusicName(player)
		else
			player.powers[pw_extralife] = 0
		end
		--gens airdash :P
		if not player.gensdash 
			player.gensangle = player.mo.angle
		else
			player.gensdash = $ - 1
			if player.modernmenu.contents[2][1].value == 3 --Jump Ability
				if player.gensdash > 1
					P_SetObjectMomZ(player.mo, 0)
					P_InstaThrust(player.mo, player.gensangle, 60*player.mo.scale)
					player.mo.state = S_PLAY_JUMP
				else
					--P_InstaThrust(player.mo, player.gensangle, 0)
					player.mo.momx = $*4/8
					player.mo.momy = $*4/8
					player.mo.state = S_PLAY_FALL
				end
			else
				if player.gensdash == 9
					P_SetObjectMomZ(player.mo, 0)
					P_InstaThrust(player.mo, player.gensangle, 90*player.mo.scale)
					player.mo.state = S_PLAY_JUMP
				elseif player.gensdash == 1
					player.mo.state = S_PLAY_FALL
				end
			end
		end
		--SP Color
		if not (player.powers[pw_super])
			if player.spcolor ~= nil
			and not multiplayer
			and not (player.powers[pw_shield] & SH_FIREFLOWER)
			and not player.mysticsuper
			and not (player.spcolor > #skincolors)
				player.mo.color = player.spcolor
			end
		end
		if (player.powers[pw_shield] & SH_FIREFLOWER)
