				if player.mo.state == S_PLAY_DASH
				or player.mo.state == S_PLAY_BOOSTRUN
					player.mo.state = S_PLAY_FIRESONICBOOST
				end
				if player.boosting == false
				and player.mo.state == S_PLAY_FIRESONICBOOST
					player.mo.state = S_PLAY_FIRESONICRUN
				end
				if player.speed <= player.runspeed--*player.mo.scale
