			end
		end
		//Victory
		if player.cleartimer 
			if player.cleartimer <= 4*TICRATE
				player.dontdovictory = true
			end
			if player.cleartimer > 4*TICRATE
				player.dontdovictory = false
			end
			if player.cleartimer == 4*TICRATE
				if player.rank == "E"
					S_StartSound(player.mo, sfx_mranke, player)
				elseif player.rank == "A"
					S_StartSound(player.mo, sfx_mranka, player)
				elseif player.rank == "S"
					S_StartSound(player.mo, sfx_mranks, player)
				end
				S_StartSound(player.mo, sfx_mrankc, player)
			elseif player.cleartimer > 4*TICRATE
			and player.clearranktimer < 10
				player.clearranktimer = $+1
			end
		end
		if not (player.exiting)
			player.dontdovictory = false
			player.levelended = false
		end
		if player.cleartimer and player.cleartimer < 4*TICRATE and player.cleartimer > 0
			player.mo.state = S_PLAY_STND
		end
		if player.exiting
		and P_IsObjectOnGround(player.mo)
		and player.speed == 0
		and player.mo.state ~= S_PLAY_MODERNVICTORY
		and player.mo.state ~= S_PLAY_WAIT
		and player.mo.state ~= S_PLAY_BOREDOM
		and player.playerstate == PST_LIVE --idk if i need this...just throwing it in incase you somehow...die in godmode..?
		and player.dontdovictory == false
		and not (player.powers[pw_super])
			if player.cleartimer > 4*TICRATE
				if player.rank == "S"
