			and player.mo.frame <= 268435462
			or player.mo.frame == 268435465
				if player.mo.anim_duration > 3
					player.mo.anim_duration = 3
				end
			elseif player.mo.frame == 268435466
				player.mo.anim_duration = 3
			end
		end
		if not (player.powers[pw_carry] == CR_MINECART) 
