			if S_SoundPlaying(player.mo, sfx_grind)
				S_StopSoundByID(player.mo, sfx_grind)
			end
		end
		if player.powers[pw_carry] == CR_MINECART
		and player.mo.tracer
		and P_IsObjectOnGround(player.mo.tracer)
			if not player.minecartonground
				player.minecartonground = true
				S_StartSound(player.mo, sfx_grndl)
			end
		else
			player.minecartonground = false
		end
		if player.boosting == false
		and player.airboost == false
		and player.superboost == false
		and player.minecartboost == false
		and not (player.boostheld == true and player.powers[pw_carry] == CR_ROLLOUT and player.boostmeter > 0)
		or player.airboost == true and player.airboostheld == false
		or player.boostmeter == 0
			if player.splat
			and player.splat2
				P_RemoveMobj(player.splat)
				P_RemoveMobj(player.splat2)
				player.splat = 0
				player.splat2 = 0
			end
		end
		//water splashes
		if leveltime % 3 == 0
		and P_IsObjectOnGround(player.mo)
		and player.mo.eflags & MFE_TOUCHWATER
		and not (P_PlayerTouchingSectorSpecial(player, 1, 3))
		and player.charflags & SF_RUNONWATER
		and (FixedHypot(player.mo.momx, player.mo.momy) > 50*FU or player.candrift == true)
			for i = -1, 1, 2
				local ang = i * ANG10
				local factor = FixedMul(4*player.mo.scale, cos(ang))
				local x = P_ReturnThrustX(player.mo, player.drawangle + ANGLE_180 + ang, 24*player.mo.scale)
				local y = P_ReturnThrustY(player.mo, player.drawangle + ANGLE_180 + ang, 24*player.mo.scale)
				local dust = P_SpawnMobjFromMobj(player.mo, x, y, 0, MT_THOK)
				dust.scale = 2*$/3
				dust.angle = R_PointToAngle2(dust.x, dust.y, player.mo.x, player.mo.y)
				dust.state = S_KICKDUST
				dust.momx = FixedMul(factor, cos(dust.angle - i*ANGLE_90))
				dust.momy = FixedMul(factor, sin(dust.angle - i*ANGLE_90))
			end
		end
		--teehee
		if (player.mo.state == S_PLAY_SKID)
			if not (player.mo.frame&FF_ANIMATE) player.mo.frame = $|FF_ANIMATE end
			if (player.mo.anim_duration > 2)
				player.mo.anim_duration = 2
			end
		end
		if player.phinvultime 
			player.phinvultime  = max($-1, 0)
		end
		local sectorthing = P_PlayerTouchingSectorSpecial(player, 4, 1)
		if sectorthing and sectorthing.valid then
			if player.fakestarpostnum == nil
			or player.fakestarpostnum ~= player.starpostnum
				player.fakestarpostnum = player.starpostnum
				SpawnBoostEnergy(player.mo, 12, 0)
				S_StartSound(player.mo, sfx_chkbst)
			end
		end
		if P_IsObjectOnGround(player.mo)
			player.usedhomingattack = false
		end
		--Golden Shine note: I'll randomly just put this here! Spork, move this where-ever you like.
		if (player.mo.state==S_PLAY_WALK) --Walking frames specifically.
		and P_IsObjectOnGround(player.mo) --Can only bounce off the ground. Even if Modern rarely airwalks anyway.
		and (player.speed > 2*s.scale) and (player.speed < 15*s.scale) --Initial startup only
		and not (player.mo.eflags & MFE_UNDERWATER)
		and (abs(p.cmd.forwardmove)>3 or abs(p.cmd.sidemove)>3) --Only with player input.
			if (player.mo.tics > 1)	--Do this twice.
				player.mo.tics = $-1
				if (player.mo.tics > 1) and (player.speed < 11*player.mo.scale)
					player.mo.tics = $-1
				end
			end

			
			--Welp, fuck calculations, I guess, simple wins the day. I'll keep the calculation arounds for the lulz.
			local FRAME = (s.frame&FF_FRAMEMASK)
			if (FRAME & C) or (FRAME & G)
				player.modernyoffset = 144000 --Peak height
			elseif (FRAME & B) or (FRAME & F)
				player.modernyoffset = 65000 --Transition into peak height
			else
				player.modernyoffset = 0 --Default again
			end
			player.mo.spriteyoffset = player.modernyoffset --Make sure overlapping items copy Sonic's spriteyoffset too.
			
		elseif player.modernyoffset != nil
		
			player.modernyoffset = nil
			player.mo.spriteyoffset = 0 --Reset offset or there'll be problems.
			
		end
		if P_IsObjectOnGround(player.mo)
		and player.mo.state == S_PLAY_WALK
		and not (player.mo.eflags & MFE_UNDERWATER)
		and ( (player.cmd.forwardmove and (player.cmd.forwardmove > 3 or player.cmd.forwardmove < -3)
		or player.cmd.sidemove and (player.cmd.sidemove > 3 or player.cmd.sidemove < -3) )	)
		and player.speed > 28*player.mo.scale
			player.runspeedtimer = min($+1, TICRATE/3)
		elseif player.mo.state ~= S_PLAY_RUN
			player.runspeedtimer = 0
		end
		if player.runspeedtimer >= TICRATE/3
		or player.boosting == true
		or player.airboost == true
			player.runspeed = 28*FRACUNIT
		elseif player.speed < 28*player.mo.scale
			player.runspeed =  1000*FRACUNIT
		end
		if player.speed > 40*player.mo.scale
			player.runspeedtimer = TICRATE/3
		end
		
	//MENU SHIT
		if player.cmd.buttons & BT_CUSTOM3
		and player.speed < FixedMul(3, player.mo.scale)
		and P_IsObjectOnGround(player.mo)
		and player.playerstate == PST_LIVE
			if player.custom3down == false
				player.custom3downtimer = min($+1, 20)
			end
			if player.custom3downtimer > 19
				player.custom3downtimer = 0
				if player.modernmenu.show == false
				and player.custom3down == false
					--COM_BufInsertText(player, "modernmenu")
					player.modernmenu.show = true
					P_PlayJingleMusic(player, "MMENU", nil, true, JT_OTHER)
					player.custom3down = true
					LoadModernSettings(player)
				end
				if player.modernmenu.show == true
				and player.custom3down == false
					player.modernmenu.show = false
					player.powers[pw_flashing] = 35
					P_RestoreMusic(player)
					if player == consoleplayer
						COM_BufInsertText(player, "savemodernsettings")
					end
				end
			end
		else
			player.custom3downtimer = 0
			player.custom3down = false
		end 

		//rush color
		if player.modernmenu.contents[4][3].value == 1
		and player.modernmenu.contents[4][1].value == 1
			if player.modernmenu.contents[4][4].value == 0
				if multiplayer
					player.rushcolor = ColorOpposite(player.skincolor)
				elseif player.spcolor ~= nil
					player.rushcolor = ColorOpposite(player.spcolor)
				end
			else
				player.rushcolor = player.modernmenu.contents[4][4].value
			end
		else
			player.rushcolor = player.mo.color
		end
		//Boost Aura Color
		if player.modernmenu.contents[8][1].value == 0 -- Colors
			if player.modernmenu.contents[7][1].value == 3
				player.boostauracolor = SKINCOLOR_RAINBOW
			else
				player.boostauracolor = FindMyColor(player, supercolor, 1)
			end
		else
			player.boostauracolor = player.modernmenu.contents[8][1].value
		end
		if player.boostauracolor and player.boostauracolor > #skincolors
			player.modernmenu.contents[8][1].value = player.modernmenu.contents[8][1].defaultvalue
		end
		//Boost Trail Color
		if player.modernmenu.contents[8][2].value == 0 -- Colors
			player.boosttrailcolor = FindMyColor(player, supercolor, 2)
		else
			player.boosttrailcolor = player.modernmenu.contents[8][2].value
		end
		if player.boosttrailcolor and player.boosttrailcolor > #skincolors
			player.modernmenu.contents[8][2].value = player.modernmenu.contents[8][2].defaultvalue
		end
		//Stomp Color
		if player.modernmenu.contents[8][3].value == 0 -- Colors
			player.stompcolor = FindMyColor(player, supercolor, 3)
		else
			player.stompcolor = player.modernmenu.contents[8][3].value
		end
		if player.stompcolor and player.stompcolor > #skincolors
			player.modernmenu.contents[8][3].value = player.modernmenu.contents[8][3].defaultvalue
		end
		//Stomp Trail Color
		if player.modernmenu.contents[8][4].value == 0 -- Colors
			player.stomptrailcolor = FindMyColor(player, supercolor, 4)
		else
			player.stomptrailcolor = player.modernmenu.contents[8][4].value
		end
		if player.stomptrailcolor and player.stomptrailcolor > #skincolors
			player.modernmenu.contents[8][4].value = player.modernmenu.contents[8][4].defaultvalue
		end
		//Homing Trail Color
		if player.modernmenu.contents[8][5].value == 0 -- Colors
			player.homingtrailcolor = FindMyColor(player, supercolor, 5)
		else
			player.homingtrailcolor = player.modernmenu.contents[8][5].value
		end
		if player.homingtrailcolor and player.homingtrailcolor > #skincolors
			player.modernmenu.contents[8][5].value = player.modernmenu.contents[8][5].defaultvalue
		end
		//Jump Aura Color
		if player.modernmenu.contents[8][6].value == 0 -- Colors
			player.jumpauracolor = FindMyColor(player, supercolor, 6)
		else
			player.jumpauracolor = player.modernmenu.contents[8][6].value
		end
		if player.jumpauracolor and player.jumpauracolor > #skincolors
			player.modernmenu.contents[8][6].value = player.modernmenu.contents[8][6].defaultvalue
		end
		//Slide Sparks
		if player.modernmenu.contents[8][7].value == 0 -- Colors
			player.slidesparkscolor = FindMyColor(player, supercolor, 7)
		else
			player.slidesparkscolor = player.modernmenu.contents[8][7].value
		end
		if player.slidesparkscolor and player.slidesparkscolor > #skincolors
			player.modernmenu.contents[8][7].value = player.modernmenu.contents[8][7].defaultvalue
		end
		//Reticle Color
		if player.modernmenu.contents[8][8].value == 0 -- Colors
			player.reticlecolor = ColorOpposite(player.skincolor)
		else
			player.reticlecolor = player.modernmenu.contents[8][8].value
		end
		if player.reticlecolor and player.reticlecolor > #skincolors
			player.modernmenu.contents[8][8].value = player.modernmenu.contents[8][8].defaultvalue
		end
		//Perfect Ring Color
		if player.modernmenu.contents[8][9].value == 0 -- Colors
			player.perfectringcolor = ColorOpposite(player.reticlecolor)
		else
			player.perfectringcolor = player.modernmenu.contents[8][9].value 
		end
		if player.perfectringcolor and player.perfectringcolor > #skincolors
			player.modernmenu.contents[8][9].value = player.modernmenu.contents[8][9].defaultvalue
		end
		//SP Color
		if player.modernmenu.contents[8][10].value == 0 -- Colors
			player.spcolor = SKINCOLOR_UNLEASHED
		else
			player.spcolor = player.modernmenu.contents[8][10].value
		end
		if player.spcolor and player.spcolor > #skincolors
			player.modernmenu.contents[8][10].value = player.modernmenu.contents[8][10].defaultvalue
		end
		//Shoe Color
		if player.firesonic
			player.modernshoecolor = SKINCOLOR_SUPERTAN2
		else
			if player.modernmenu.contents[8][11].value == 0 -- Colors
				if multiplayer
					player.modernshoecolor = ColorOpposite(player.skincolor)
				else
					player.modernshoecolor = ColorOpposite(player.spcolor)
				end
			else
				player.modernshoecolor = player.modernmenu.contents[8][11].value
			end
		end
		if player.modernshoecolor and player.modernshoecolor > #skincolors
			player.modernmenu.contents[8][11].value = player.modernmenu.contents[8][11].defaultvalue
		end
		//Cloth Color
		if player.modernmenu.contents[8][12].value == 0 -- Colors
			if multiplayer
				player.modernclothcolor = ColorOpposite(player.skincolor)
			else
				player.modernclothcolor = ColorOpposite(player.spcolor)
			end
		else
			player.modernclothcolor = player.modernmenu.contents[8][12].value
		end
		if player.modernclothcolor and player.modernclothcolor > #skincolors
			player.modernmenu.contents[8][12].value = player.modernmenu.contents[8][12].defaultvalue
		end
		//Super Aura Color
		if player.modernmenu.contents[8][13].value == 0 -- Colors
			player.superauracolor = ColorOpposite(player.skincolor)
		else
			player.superauracolor = player.modernmenu.contents[8][13].value
		end
		if player.superauracolor and player.superauracolor > #skincolors
			player.modernmenu.contents[8][13].value = player.modernmenu.contents[8][13].defaultvalue
		end
		//colors end
		if player.lightdashing > 1
		or player.boosting == true
		or (player.stomping == true and not (player.powers[pw_super]))
		or player.gotflag
		or player.active_supertrans == true
		or (player.mo.state >= S_PLAY_TAUNT1 and player.mo.state <= S_PLAY_TAUNT4)
		or (player.mo.state >= S_PLAY_BREAKDANCE1 and player.mo.state <= S_PLAY_BREAKDANCE4)
		--or player.manualdrifting == true
		--or player.crouching == true
			player.abilitylock = true
		elseif player.lightdashing == 0 
		and not (player.mo.state >= S_PLAY_TAUNT1 and player.mo.state <= S_PLAY_TAUNT4) 
		and not (player.mo.state >= S_PLAY_BREAKDANCE1 and player.mo.state <= S_PLAY_BREAKDANCE4)
		and player.boosting == false 
		and player.stomping == false 
		and not (player.gotflag)
			player.abilitylock = false
		end
		if (P_PlayerInPain(player) or player.gotbonked == true) 
		and not P_IsObjectOnGround(player.mo)
			player.paintimer = $1+1 
		else
			if P_IsObjectOnGround(player.mo)
			or not player.mo.state == S_PLAY_PAIN
				player.paintimer = 0
				player.gotbonked = false
			end
		end	
		if not (player.pflags & PF_STARTDASH)
			player.dashspeed = 0
		end
		if player.paintimer >= 29 
		and player.mo.state == S_PLAY_PAIN
		and not P_IsObjectOnGround(player.mo)
		and not (player.pflags & PF_SLIDING)
		and (player.cmd.buttons & BT_JUMP) 
			P_DoJump(player, true)
			player.paintimer = 0
			player.jumptimer = 5
			player.gotbonked = false
			player.trickable = false
			player.tricking = false
			player.mo.state = S_PLAY_JUMP
		end
		if not (player.powers[pw_super])
		and not (player.powers[pw_carry] == CR_NIGHTSMODE)
			player.charflags = $ & ~SF_SUPER
		elseif (player.powers[pw_carry] == CR_NIGHTSMODE)
			player.charflags = $|SF_SUPER
		end
		//player.charflags = $|SF_SUPER -- Wtf
		//Characters switch to falling animation after running off of a ledge
		if (player.pflags == player.pflags & ~(PF_JUMPED|PF_SPINNING))
       	and not (P_PlayerInPain(player))
		and not (player.powers[pw_super] > 0 and player.powers[pw_super] < 25)
		and not (P_IsObjectOnGround(player.mo))
		and player.airboost == false
		and not (player.powers[pw_carry])
		and player.playerstate == PST_LIVE
		and not (player.powers[pw_nocontrol])
			if ((player.mo.state == S_PLAY_STND)
			or (player.mo.state == S_PLAY_WAIT)
			or (player.mo.state == S_PLAY_WALK)
			or (player.mo.state == S_PLAY_RUN)) 
			or (player.mo.state == S_PLAY_BOOSTRUN)
			or (player.mo.state == S_PLAY_FIRESONICRUN)
			or (player.mo.state == S_PLAY_FIRESONICBOOST)
				if player.boosting == true
					if player.mo.momz*P_MobjFlip(player.mo) > 0
						player.mo.state = S_PLAY_AIRBOOST
					elseif player.mo.state == S_PLAY_AIRBOOST
						player.mo.state = S_PLAY_FALL
					end
				end
				player.falltimer = $+1
			end
		end
		if player.falltimer > 3
		and not (P_PlayerInPain(player))
		and player.mo.state ~= S_PLAY_PAIN
			player.mo.state = S_PLAY_SPRING
			player.falltimer = 0
		end
		if not P_IsObjectOnGround(player.mo)
		and player.mo.momz*P_MobjFlip(player.mo) > 1*FU
		and not (player.pflags & PF_JUMPED)
		and not (player.boosting)
		and not (P_PlayerInPain(player))
		and player.mo.state ~= S_PLAY_PAIN
		and player.airboost == false
		and not player.lightdashing
		and player.paintimer == 0
		and not player.trickable
		and not (player.powers[pw_carry])
		and player.superanim == 0
		and player.playerstate == PST_LIVE
			player.mo.state = S_PLAY_SPRING
			player.trickable = true
		end
		
		if P_IsObjectOnGround(player.mo)
			player.falltimer = 0
		end
		if player.speed > 0
		and player.mo.state == S_PLAY_STND
		and not (player.powers[pw_carry])
			player.mo.state = S_PLAY_WALK
		end
		if player.mo.state == S_PLAY_JUMP
		or player.mo.state == S_PLAY_ROLL
		or player.mo.state == S_PLAY_AIRKICK
			player.pflags = $ & ~PF_NOJUMPDAMAGE
		else
			player.pflags = $|PF_NOJUMPDAMAGE
		end
		if player.powers[pw_carry] == CR_MACESPIN
		and player.mo.state ~= S_PLAY_ROLL
			player.mo.state = S_PLAY_ROLL
		end
		if player.powers[pw_nocontrol]
			player.jumptimer = 0
		end
		if player.justhitballoon == true
			P_SetObjectMomZ(player.mo, 13*FRACUNIT, false)
			player.justhitballoon = false
		end
		
	///////BOOST
		//rail fix?
		if player.boosting
			player.startboost = true
		end
		--spinboost + zoomtoom fix
		if player.powers[pw_carry] == CR_ZOOMTUBE
		and player.boosting
			player.boosting = false
			player.inzoomtube = true
		end
		if not (player.powers[pw_carry] == CR_ZOOMTUBE)
		and player.inzoomtube
			if (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 1) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 0)) -- Actionswap
				player.boosting = true
			end
			player.inzoomtube = false
		end
		--STUPID FIX FOR STUPID BUG
		if player.powers[pw_carry] == CR_ROLLOUT
		and player.boostmeter == 0
			player.mo.gensboostaura = nil
		end
		if not (P_IsObjectOnGround(player.mo))
		and player.boosting == true
		and player.pflags & PF_SPINNING
			player.retainspinboost = true
		end
		if P_IsObjectOnGround(player.mo)
		and player.boosting 
		and player.retainspinboost
			player.pflags = $|PF_SPINNING
			player.reainspinboost = false
		end
		if not player.boosting
			player.retainspinboost = false
		end
		if player.boostfuckedbywall
		and leveltime % 2 == 1
			player.boostfuckedbywall = $-1
		end
		if player.boostfuckedbywall > 3
			player.boosting = false
			player.superboost = false
		end
		if player.boosting == true
		or player.airboost == true and player.airboostheld == true
			player.powers[pw_strong] = 256
		end
		if player.boosting == true
		and (player.powers[pw_shield] == SH_FLAMEAURA
		or player.firesonic)
			if leveltime % 5  == 1
				player.flameshieldboost = $ + 1
			end
		else
			player.flameshieldboost = 0
		end
		if player.pflags & PF_JUMPED
		and player.boosting
			if player.mo.momz*P_MobjFlip(player.mo) > 0
				player.mo.state = S_PLAY_AIRBOOST
			elseif player.mo.state == S_PLAY_AIRBOOST
			and player.airboost == false
				player.frontflip = true
				player.mo.state = S_PLAY_SPRING
			end
		end
		if player.mo.eflags & MFE_SPRUNG
			player.dropdashing = false
			player.boostcanceltimer = 10
		end
		if player.speed > FixedMul(player.runspeed, player.mo.scale)
			player.jumpfactor = FRACUNIT*6/5
		else
			player.jumpfactor = FRACUNIT
		end
		if player.firesonic
			player.firesonicspeed = 20*FU
		else
			player.firesonicspeed = 0
		end
		if player.boosting == true
			player.speedwhileboosting = player.speed
			if P_IsObjectOnGround(player.mo)
				if player.modernmenu.contents[2][7].value == 1
					if player.rings <= 200
						player.normalspeed = (36*FRACUNIT+(player.rings/7)*FRACUNIT) + player.firesonicspeed
					else
						player.normalspeed = 64*FRACUNIT + player.firesonicspeed
					end
				else
					player.normalspeed = 36*FU + player.firesonicspeed
				end
			else
				--player.normalspeed = 80*FRACUNIT
			end
		else
			if player.speedwhileboosting > 0
				player.speedwhileboosting = $1-60000
			end
			if player.powers[pw_sneakers]
			or player.powers[pw_super]
				if player.modernmenu.contents[2][7].value == 1
					if player.rings <= 200
						player.normalspeed = ((36*FRACUNIT+(player.rings/7)*FRACUNIT) + (player.speedwhileboosting*55/168)) + player.firesonicspeed
					else
						player.normalspeed = ((64*FRACUNIT+(player.speedwhileboosting*55/168))) + player.firesonicspeed
					end
				else
					player.normalspeed = 36*FU + player.firesonicspeed
				end
			elseif P_IsObjectOnGround(player.mo)
			or (player.airboost == true and player.airboostheld == false)
				if player.modernmenu.contents[2][7].value == 1
					if player.rings <= 200
						player.normalspeed = (36*FRACUNIT+(player.rings/7)*FRACUNIT) + (player.speedwhileboosting/2) + player.firesonicspeed
					else
						player.normalspeed = 64*FRACUNIT+(player.speedwhileboosting/2) + player.firesonicspeed
					end
				else
					player.normalspeed = 36*FU + player.firesonicspeed
				end
			end
		end
		if player.speed < player.speedwhileboosting
			player.speedwhileboosting = player.speed
		end
		if player.hudring and player.hudring > 0 
			player.hudring = $1-1
		end
		player.hudring2 = max(1, $-1)
		local ringsToRemove = {}
		for i = 1, #player.hudring3
			player.hudring3[i] = max(0, $-1)
			if not player.hudring3[i]
				table.insert(ringsToRemove, i)
			end
		end
		local removed = 0
		for i = 1, #ringsToRemove
			table.remove(player.hudring3, ringsToRemove[i]-removed)
			removed = $ + 1
		end
		if (player.speed > FixedMul(65*FRACUNIT, player.mo.scale) and not (player.powers[pw_carry] == CR_MINECART) and not (player.powers[pw_sneakers]) and not (player.powers[pw_nocontrol]))
		or player.minecartboost == true
		or player.customhoming > 0
			player.boostlinetimer = $1+1
		end
		if player.boostlinetimer > 9
			player.boostlinetimer = 1
		end
		if player.rings > player.prevrings
		and player.playerstate == PST_LIVE
			if player.hudring == 0
				player.hudring = 6
			end
			player.hudring2 = 6
			table.insert(player.hudring3, 6)
			player.boostmeter = $1+(player.rings-player.prevrings)*2
			if player.rushmode > 0 then player.rushmode = $+((player.rings-player.prevrings)*6) end
			player.prevrings = player.rings
			player.boostregentimer = 0
		end
		if player.powers[pw_carry] == CR_ROLLOUT
			player.boostregentimer = 0
		else
			if player.rockringattract and player.rockringattract.valid
				P_RemoveMobj(player.rockringattract)
				player.rockringattract = nil
			end
			if (player.boostmobj3 and player.boostmobj3.valid)
				S_StopSound(player.boostmobj3)
				P_RemoveMobj(player.boostmobj3)
			end
			if (player.boostmobj4 and player.boostmobj4.valid)
				S_StopSound(player.boostmobj4)
				P_RemoveMobj(player.boostmobj4)
			end
		end
		if player.rings < player.prevrings
			player.prevrings = player.rings
		end
		if player.powers[pw_super]
			player.boostmeter = 117
		end
		if player.mo.msflameboost
		player.mo.msflameboost = $-1
		end
		if player.rings == 0 
		or player.playerstate == PST_DEAD
			player.prevrings = 0
		end
		if player.boostcanceltimer > 0
			player.boostcanceltimer = $1-1
		end
		if player.boosting == false
		and player.airboost == false
		and player.superboost == false
		and player.customhoming == 0
		and player.minecartboost == false
			player.boostlinetimer = 0
		end
		if (player.powers[pw_carry] and not player.powers[pw_carry] == CR_GRINDRAIL)
		or player.exiting
		or P_PlayerInPain(player)
		or player.powers[pw_nocontrol]
		--or (player.pflags & PF_SLIDING and player.speed < 45*FU)
			player.boosting = false
			player.airboost = false
			player.airboostheld = false
			player.superboost = false
		end
		if player.boosting == false
		and player.airboost == false
		and player.superboost == false
		and player.minecartboost == false
			player.boostregentimer = $1+1
		else
			player.boostregentimer = 0
		end
		if player.mysticsuper
			player.airboost = false
			player.airboostheld = false
		end
		if P_IsObjectOnGround(player.mo)
		and (player.mo.state == S_PLAY_BOOSTRUN
		or player.mo.state == S_PLAY_FIRESONICBOOST)
		and not (player.pflags & PF_DIRECTIONCHAR)
		and (player.pflags & PF_ANALOGMODE)
			player.drawangle = R_PointToAngle2(player.mo.x, player.mo.y, (player.mo.x+player.mo.momx), (player.mo.y+player.mo.momy))
		end
		if player.playerstate == PST_LIVE
			if player.boosting == true
			or player.airboost == true
			or player.superboost == true
				if player.rushmode > 0
					player.usedboostduringrush = true
				end
				if (player.powers[pw_shield] == SH_ELEMENTAL or player.powers[pw_shield] == SH_FLAMEAURA)
				or player.firesonic
					if P_IsObjectOnGround(player.mo) and not (player.mo.eflags & (MFE_UNDERWATER|MFE_TOUCHWATER)) and (leveltime & 1)
						P_ElementalFire(player)
					end
					if not player.powers[pw_super]
						player.mo.msflameboost = 2 --To give Modern Sonic flameboost colors.
					end
				end
				if player.powers[pw_super]
					if player.superboost == true
						if (leveltime % 4 == 0)
							player.rings = player.rings-1
						end
					
						if not (P_IsObjectOnGround(player.mo))
							player.pflags = $|PF_JUMPED
						else
							player.pflags = $ & ~PF_THOKKED
						end
						player.pflags = $|PF_THOKKED
						player.doublejumped = true
						player.justjumped = true
						if player.cmd.buttons & BT_JUMP
							P_SetObjectMomZ(player.mo, 2*FRACUNIT,true)
						elseif (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
							player.usedown = true
							player.stompdown = true
							P_SetObjectMomZ(player.mo, -2*FRACUNIT,true)
						end
						if player.mo.momz
							if not ((((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) and not (player.cmd.buttons & BT_JUMP) -- Actionswap
							or ((((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1))) and player.cmd.buttons & BT_JUMP) -- Actionswap
								player.mo.momz = $ - $/abs($)*abs(P_GetMobjGravity(player.mo))
							end
						end
						if player.mo.state != S_PLAY_DRIFTRIGHT
						and player.mo.state != S_PLAY_DRIFTLEFT
						and player.mo.state != S_PLAY_GRND
						and player.mo.state != S_PLAY_ROLL
						and player.mo.state != S_PLAY_FIRESONICBOOST
							player.mo.state = S_PLAY_BOOSTRUN
						end
						player.mo.flags = $|MF_NOGRAVITY
					else
						player.mo.flags = $ & ~MF_NOGRAVITY
					end
				end
			else
				player.mo.flags = $ & ~MF_NOGRAVITY
			end
		end
		if player.boostmeter
			if player.boostmeter > 117
				player.boostmeter = 117
			elseif player.boostmeter < 0
				player.boostmeter = 0
				player.boosting = false
			end
		end
		if (player.speed > FixedMul(45*FRACUNIT, player.mo.scale) or player.mysticsuper)
		and player.stomping == false
		and player.customhoming == 0
			player.charflags = $|SF_RUNONWATER
		else
			player.charflags = $ & ~SF_RUNONWATER
		end
		if not (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 1) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 0)) -- Actionswap
			player.minecartboost = false
		end
		if P_IsObjectOnGround(player.mo)
			player.airboost = false
		end
		if player.playerstate == PST_LIVE
			if player.speed == 0 
			and P_IsObjectOnGround(player.mo)
			and player.realtime > 3*TICRATE
			and player.crouching == true
			or player.boostregentimer > 4*TICRATE
			or player.sliding == 1
				player.boostregen = $1+1
				if player.boostregen > 7
				and player.sliding == 0
					if player.boostmeter 
					or player.boostmeter == 0
						if player.boostmeter < 80
							player.boostmeter = $1+1
						end
					end
					player.boostregen = 0
				end
				if player.boostregen > 7
				and player.sliding == 1
					if player.boostmeter < 80
						player.boostmeter = $1+2
					end
					player.boostregen = 0
				end
			end
		end
		if player.airboost == true
		or player.customhoming > 0
			player.boosting = false
		end
		if not (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 1) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 0)) -- Actionswap
		and player.airboost == true
		and player.airboostheld == true
		or (player.speed < 45*player.mo.scale)
			player.airboostheld = false
		end
		player.thrustblock = max($-1, 0)
		if (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 1) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 0)) -- Actionswap
			if P_IsObjectOnGround(player.mo)
			or player.modernwallslide 
				player.airdashheld = true
			end
		else
			player.airdashheld = false
		end
		if (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 1) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 0)) -- Actionswap
		and player.boostheld == false
		and player.airboostheld == false
		and not player.boostmeter
		and not (player.exiting)
		and player.playerstate == PST_LIVE
		and player.airboost == false
		and not (P_PlayerInPain(player))
		and player.customhoming == 0
		and player.abilitylock == false
		and not (player.pflags & PF_FULLSTASIS)
		and not (player.pflags & PF_STASIS)
		and not (player.silv_grabbed)
		and player.tricking == false
		and player.sliding == 0
		--and not (player.pflags & PF_SPINNING)
		and not (player.powers[pw_carry] == CR_ROLLOUT)
		and not (P_IsObjectOnGround(player.mo))
		and player.airdashheld == false
		and player.modernwallslide == 0
		and not (player.powers[pw_carry] == CR_GRINDRAIL)
		and not player.nomovecounter
			player.airboost = true
			player.airboostheld = false
			player.boosting = false
			player.boostheld = false
			if not (player.mo.eflags & MFE_UNDERWATER)
				S_StartSound(player.mo, sfx_mthok)
			else
				S_StartSound(player.mo, sfx_mthokw)
			end
			player.airboostcounter = $+1
			player.mo.state = S_PLAY_AIRBOOST
			player.pflags = $ & ~PF_SPINNING
			player.jumptimer = 0
			if player.mo.momz*P_MobjFlip(player.mo) <= 0
				player.mo.momz = 0
			else
				player.mo.momz = $/2
			end
			player.drawangle = player.mo.angle
			player.pflags = $ & ~PF_JUMPED
			if player.speed < 34*player.mo.scale
				P_InstaThrust(player.mo, player.mo.angle, 34*player.mo.scale)
			else 
				P_InstaThrust(player.mo, player.mo.angle,  FixedHypot(player.mo.momx, player.mo.momy) + 5*FU)
			end
		end
		if (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 1) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 0)) -- Actionswap
		and player.boostheld == false
		and player.airboostheld == false
		and player.boostmeter and player.boostmeter > 0
		and not (player.exiting)
		and player.playerstate == PST_LIVE
		and player.airboost == false
		and not (P_PlayerInPain(player))
		and player.customhoming == 0
		and player.abilitylock == false
		and not (player.pflags & PF_FULLSTASIS)
		and not (player.pflags & PF_STASIS)
		and not (player.silv_grabbed)
		and player.tricking == false
		--and player.sliding == 0
		--and not (player.pflags & PF_SPINNING)
		and not (player.powers[pw_carry] == CR_ROLLOUT)
		and not (player.powers[pw_carry] == CR_GRINDRAIL)
		and not player.nomovecounter
			player.stomping = false
			player.sliding = 0
			if (player.powers[pw_carry] == CR_MINECART)
			and P_IsObjectOnGround(player.mo.tracer)
				if player.minecartboost == false
					if player.modernmenu.contents[2][3].value == 1 -- ModernFOV
						player.camerascale = 7*FRACUNIT/2
					end
					if not (player.powers[pw_super])
						player.boostmeter = $ - 10
					end
					if player.modernmenu.contents[10][2].value == 3
						S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_wtbst1 or sfx_boost1)
					elseif player.modernmenu.contents[10][2].value == 4
					or player.modernmenu.contents[10][2].value == 2
						S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_fwbst1 or sfx_fbost1)
					elseif player.modernmenu.contents[10][2].value == 0	
						S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_rwbst1 or sfx_rbost1)
					elseif player.modernmenu.contents[10][2].value == 1
						S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_06bstw or sfx_06bost)					
					end
					
					if player.modernmenu.contents[6][1].value == 1 -- Voices
						if player.modernmenu.contents[6][2].value == 0
							PlayModernSound(player, 2)
						elseif player.modernmenu.contents[6][2].value == 1
							PlayModernSound(player, 14)
						elseif player.modernmenu.contents[6][2].value == 2
							PlayModernSound(player, 8)
						elseif player.modernmenu.contents[6][2].value == 3
							PlayModernSound(player, 20)
						elseif player.modernmenu.contents[6][2].value == 4
							PlayModernSound(player, 25)
						elseif player.modernmenu.contents[6][2].value == 5
							PlayModernSound(player, 26)
						end
					end
					player.boostshake = 8
				
					local boostshockwave = P_SpawnMobjFromMobj(player.mo, 0, 0, 0, MT_BOOSTSHOCKWAVE)
					boostshockwave.target = player.mo
					if player.powers[pw_super]
					or player.mysticsuper
						boostshockwave.color = FindMyColor(player, SKINCOLOR_GOLDENROD)
					elseif (player.powers[pw_shield] == SH_ELEMENTAL)
					and not (player.mo.eflags & MFE_UNDERWATER)
					and player.powers[pw_super] == 0
						boostshockwave.color = SKINCOLOR_ORANGE
					elseif player.powers[pw_shield] == SH_FLAMEAURA
					or player.firesonic
						boostshockwave.color = SKINCOLOR_KETCHUP
					else
						boostshockwave.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 1, "boost1")
					end
					boostshockwave.scale = player.mo.scale
					boostshockwave.momx = player.mo.momx/2
					boostshockwave.momy = player.mo.momy/2
					boostshockwave.momz = player.mo.momz
					player.minecartboost = true
				end
			end
			if player.boosting == false
			and player.airboost == false
			and not (player.powers[pw_carry])
			and player.powers[pw_nocontrol] == 0
			and not (P_PlayerInPain(player))
			and player.modernwallslide == 0
			and not player.dropdashing
			and not (player.pflags & PF_STARTDASH)
			and not (player.pflags & BT_TOSSFLAG)
				if player.modernmenu.contents[2][3].value == 1 -- ModernFOV
					player.camerascale = 7*FRACUNIT/2
				end
				player.charflags = $|SF_RUNONWATER
				if P_IsObjectOnGround(player.mo)
					player.boosting = true
					player.boostcanceltimer = 5
					player.thrustblock = 5
					player.airboost = false
					player.airboostheld = false
					if player.modernmenu.contents[2][7].value == 1
						if player.rings <= 200
							P_InstaThrust(player.mo, (twod and player.drawangle or player.mo.angle), FixedMul(80*FRACUNIT+((player.rings/3)*FRACUNIT), player.mo.scale))
						else
							P_InstaThrust(player.mo, (twod and player.drawangle or player.mo.angle), FixedMul(146*FRACUNIT, player.mo.scale))
						end
					else
						P_InstaThrust(player.mo, (twod and player.drawangle or player.mo.angle), 80*FRACUNIT)
					end
					if not (player.powers[pw_super])
						player.boostmeter = $ - 10
					end
					player.boostheld = true
					if player.modernmenu.contents[10][2].value == 2
						S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_wtbst1 or sfx_boost1)
					elseif player.modernmenu.contents[10][2].value == 4
					or player.modernmenu.contents[10][2].value == 3
						S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_fwbst1 or sfx_fbost1)
					elseif player.modernmenu.contents[10][2].value == 0
						S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_rwbst1 or sfx_rbost1)
					elseif player.modernmenu.contents[10][2].value == 1
						S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_06bstw or sfx_06bost)	
					end
					
				elseif not (player.pflags & PF_STASIS)
				and not (player.pflags & PF_FULLSTASIS)
				
					if not (player.powers[pw_super])
						player.airboost = true
						player.airboostheld = true 
						player.boosting = true
						player.airboostcounter = $+1
						if player.modernmenu.contents[10][2].value == 2
							S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_wtbst2 or sfx_boost2)
						elseif player.modernmenu.contents[10][2].value == 4
						or player.modernmenu.contents[10][2].value == 3
							S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_fwbst2 or sfx_fbost2)
						elseif player.modernmenu.contents[10][2].value == 0
							S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_rwbst1 or sfx_rbost1)
						elseif player.modernmenu.contents[10][2].value == 1
							S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_06bstw or sfx_06bost)	
						end
					else
						if player.modernmenu.contents[10][2].value == 2
							S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_wtbst1 or sfx_boost1)
						elseif player.modernmenu.contents[10][2].value == 4
						or player.modernmenu.contents[10][2].value == 3
							S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_fwbst1 or sfx_fbost1)
						elseif player.modernmenu.contents[10][2].value == 0
							S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_rwbst1 or sfx_rbost1)
						elseif player.modernmenu.contents[10][2].value == 1
							S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_06bstw or sfx_06bost)	
						end
						player.superboost = true
						player.boostcanceltimer = 5
					end
					
					player.jumptimer = 0
					player.mo.state = S_PLAY_AIRBOOST
					player.pflags = $ & ~PF_SPINNING
					if not (player.powers[pw_super])
						player.boostmeter = $ - 12
					end
					if player.mo.momz*P_MobjFlip(player.mo) > 0
						player.mo.momz = 0
					end
					player.boostheld = true
					player.pflags = $ & ~PF_JUMPED
					if player.speed < FixedMul(66*FRACUNIT, player.mo.scale)
						if player.modernmenu.contents[2][7].value == 1
							if player.rings < 200
								P_InstaThrust(player.mo, (twod and player.drawangle or player.mo.angle), FixedMul(66*FRACUNIT+(player.rings/3)*FRACUNIT, player.mo.scale))
							else
								P_InstaThrust(player.mo, (twod and player.drawangle or player.mo.angle), FixedMul(133*FRACUNIT, player.mo.scale))
							end
						else
							P_InstaThrust(player.mo, (twod and player.drawangle or player.mo.angle), 66*FU)
						end
					else		
						P_InstaThrust(player.mo, (twod and player.drawangle or player.mo.angle),  FixedHypot(player.mo.momx, player.mo.momy))
					end
					if not player.usedwalljump
						if player.modernmenu.contents[2][7].value == 1
							if player.rings < 200
								player.normalspeed = FixedMul(66*FRACUNIT+(player.rings/3)*FRACUNIT, player.mo.scale)
								player.speedwhileboosting = FixedMul(66*FRACUNIT+(player.rings/3)*FRACUNIT, player.mo.scale)	
							else
								player.normalspeed = FixedMul(133*FRACUNIT, player.mo.scale)
								player.speedwhileboosting = FixedMul(133*FRACUNIT, player.mo.scale)
							end
						else
							player.normalspeed =  66*FU
						end
					end
					player.sonic_ringrangeair = P_SpawnMobj(player.mo.x + player.mo.momx, player.mo.y+ player.mo.momy, player.mo.z + player.mo.momz + player.mo.height/2 - 80*player.mo.scale, MT_RINGRANGE)
					player.sonic_ringrangeair.scale = (player.sonic_ringcharge and 2 or 1)*player.mo.scale
					player.sonic_ringrangeair.height = $*(player.powers[pw_super] and 2 or 1)
					player.sonic_ringrangeair.radius = $*(player.powers[pw_super] and 2 or 1)
					player.sonic_ringrangeair.target = player.mo
					player.sonic_ringrangeair.fuse = 3
				end
				player.drawangle = player.mo.angle
				player.boostshake = 8
				
				local boostshockwave = P_SpawnMobjFromMobj(player.mo, 0, 0, 0, MT_BOOSTSHOCKWAVE)
				boostshockwave.target = player.mo
				if player.powers[pw_super]
				or player.mysticsuper
					boostshockwave.color = FindMyColor(player, SKINCOLOR_GOLDENROD)
				elseif (player.powers[pw_shield] == SH_ELEMENTAL)
				and not (player.mo.eflags & MFE_UNDERWATER)
				and player.powers[pw_super] == 0
					boostshockwave.color = SKINCOLOR_ORANGE
				elseif player.powers[pw_shield] == SH_FLAMEAURA
				or player.firesonic
					boostshockwave.color = SKINCOLOR_KETCHUP
				else
					boostshockwave.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 1, "boost1")
				end
				boostshockwave.scale = player.mo.scale
				boostshockwave.momx = player.mo.momx/2
				boostshockwave.momy = player.mo.momy/2
				boostshockwave.momz = player.mo.momz
				if player.modernmenu.contents[6][1].value == 1 -- Voices
					if player.modernmenu.contents[6][2].value == 0
						PlayModernSound(player, 2)
					elseif player.modernmenu.contents[6][2].value == 1
						PlayModernSound(player, 14)
					elseif player.modernmenu.contents[6][2].value == 2
						PlayModernSound(player, 8)
					elseif player.modernmenu.contents[6][2].value == 3
						PlayModernSound(player, 20)
					elseif player.modernmenu.contents[6][2].value == 4
						PlayModernSound(player, 25)
					elseif player.modernmenu.contents[6][2].value == 5
						PlayModernSound(player, 26)
					end
				end
			end
		end
		if P_IsObjectOnGround(player.mo)
		and (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 1) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 0)) -- Actionswap
		and player.boostheld == true
		and (player.airboostheld == true or player.superboost == true)
		and not (player.pflags & BT_TOSSFLAG)
			player.boosting = true
			player.airboost = false
			player.airboostheld = false
		end
		if player.boostshake > 0
		or player.stompshake > 0
			player.boostshake = $1-1
			if client and client.valid and client.mo
				local dist = P_AproxDistance(P_AproxDistance((client.mo.x - player.mo.x)/FRACUNIT, (client.mo.y - player.mo.y)/FRACUNIT), (client.mo.z - player.mo.z)/FRACUNIT)
				if dist >= 0 and dist < (player.powers[pw_super] and 512 or 256)*player.mo.scale/FRACUNIT
					if (player.modernmenu.contents[2][4].value == 0 and player ~= displayplayer) -- Quakes
						P_StartQuake(25*FRACUNIT, 1)
					end
				end
			end
		end

		if not (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 1) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 0)) -- Actionswap
			if P_IsObjectOnGround(player.mo)
				player.airboostheld = false
			end
			player.boostheld = false
			player.boosting = false
			player.boostsound = false
			if player.superboost == true
				player.superboost = false
				if player.mo.momz*P_MobjFlip(player.mo) > 0
					player.mo.momz = $/6
				end
				--player.mo.momy = $*5/8
				--player.mo.momx = $*5/8
			end
		end
		if player.mysticsuper
		or player.pflags & PF_FINISHED and not (player.exiting)
			if player.boostmeter < 117
				player.boostmeter = $+1
			end
		elseif player.pflags & PF_GODMODE
			player.boostmeter = 116
		end
		if player.boostmeter == 0
			player.minecartboost = false
			player.boosting = false
		end
		if player.minecartboost == true
		and not (player.powers[pw_carry] == CR_MINECART)
			player.minecartboost = false
		end
		if ((player.boosting == true or player.superboost == true) or (player.airboost == true and player.airboostheld == true))
		and player.playerstate == PST_LIVE
		and ((player.pflags & PF_SLIDING or player.pflags & PF_SPINNING) or (player.speed >= 45*player.mo.scale and not (player.powers[pw_super])) or (player.boostcanceltimer > 0) or (player.boostfuckedbywall <= 3) or (player.speed >= 10*player.mo.scale and (player.powers[pw_super])))
		--and player.airboost == false
		and player.powers[pw_nocontrol] == 0
		and not (P_PlayerInPain(player))
		or player.minecartboost == true
		-- New Boost Aura lifted from SMSreborn. MobjThinker part is above the rest of the code and very important.	
		
			//This function is called on to display the boostaura now.
			if player.modernmenu.contents[7][1].value == 0 -- Boost Aura
				ModernSonicRebornBoost(player.mo)
			elseif player.modernmenu.contents[7][1].value == 1 -- Boost Aura
			or player.modernmenu.contents[7][1].value == 2 -- Boost Aura
				ModernSonicGenerationsBoost(player.mo)					
			elseif player.modernmenu.contents[7][1].value == 3 -- Boost Aura
				ModernSonicColorsBoost(player.mo)					
			elseif player.modernmenu.contents[7][1].value == 4 -- Boost Aura
				ModernSonicRushBoost(player.mo)
			elseif player.modernmenu.contents[7][1].value == 5 -- Boost Aura
				ModernSonicForcesBoost(player.mo)
			elseif player.modernmenu.contents[7][1].value == 7 -- Boost Aura
				ModernSonicOldBoost(player.mo)
			elseif player.modernmenu.contents[7][1].value == 8 -- Boost Aura
				ModernSonicRebornBoost(player.mo)
				ModernSonicGenerationsBoost(player.mo)
				ModernSonicColorsBoost(player.mo)
				ModernSonicRushBoost(player.mo)
				ModernSonicForcesBoost(player.mo)
				ModernSonicOldBoost(player.mo)
			end
			if player.firesonic
				FireSonicFireSpawn(player)
			end
			player.boostheld = true
			if player.ringrange == 0
			and (maptol & TOL_SP or maptol & TOL_COOP)
			
				player.sonic_ringrange = P_SpawnMobj(player.mo.x + player.mo.momx, player.mo.y+ player.mo.momy, player.mo.z + player.mo.momz + player.mo.height/2 - 80*player.mo.scale, MT_RINGRANGE)
				player.sonic_ringrange.scale = (player.sonic_ringcharge and 2 or 1)*player.mo.scale
				
				if player.powers[pw_super]
					player.sonic_ringrange.radius = $*2
					player.sonic_ringrange.height = $*2
				else
					player.sonic_ringrange.radius = $*3/4
					player.sonic_ringrange.height = $*3/4
				end
				player.sonic_ringrange.target = player.mo
				player.ringrange = 1
			end
			if player.sonic_ringrange and player.sonic_ringrange.valid
				P_MoveOrigin(player.sonic_ringrange, player.mo.x, player.mo.y, player.mo.z)
			end
			player.charflags = $|SF_NOSKID
			if player.powers[pw_super] == 0
				player.boostdecrease = $1+1
			end
			if player.powers[pw_carry] == CR_MINECART
				if player.boostdecrease >= 5
					player.boostmeter = $ - 1
					player.boostdecrease = 0
				end
			else
				if player.boostmeter > 0
					if (player.boostdecrease >= 3)
					and not (player.mo.state == S_PLAY_DRIFTRIGHT or player.mo.state == S_PLAY_DRIFTLEFT)
						player.boostmeter = $ - 1
						player.boostdecrease = 0
					end
				end
			end
			if (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 1) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 0)) -- Actionswap
				player.boostheld = true
			end
			--if P_IsObjectOnGround(player.mo)
			if player.driftsens ~= nil and player.driftsens < 6
			and player.powers[pw_carry] ~= CR_MINECART
			and not (player.powers[pw_carry] == CR_GRINDRAIL)
				player.drawangle =  R_PointToAngle2(player.mo.x, player.mo.y, (player.mo.x+player.mo.momx), (player.mo.y+player.mo.momy))
			end
			if P_IsObjectOnGround(player.mo) or player.pflags & PF_SLIDING
				if (player.powers[pw_super])
				or player.mysticsuper
				or player.powers[pw_sneakers]
					if player.modernmenu.contents[2][7].value == 1
						if player.rings <= 200
							player.boostspeed = FixedMul(100*FRACUNIT+(player.rings/3)*FRACUNIT, player.mo.scale)+ player.flameshieldboost*FRACUNIT + player.firesonicspeed
						else
							player.boostspeed = FixedMul(184*FRACUNIT, player.mo.scale)+ player.flameshieldboost*FRACUNIT + player.firesonicspeed
						end
					else
						player.boostspeed = 100*player.mo.scale+ player.flameshieldboost*FRACUNIT + player.firesonicspeed
					end
				else
					if player.modernmenu.contents[2][7].value == 1
						if player.rings <= 200
							player.boostspeed = FixedMul(80*FRACUNIT+((player.rings/3)*FRACUNIT), player.mo.scale) + player.flameshieldboost*FRACUNIT + player.firesonicspeed
						else
							player.boostspeed = FixedMul(147*FRACUNIT, player.mo.scale)+ player.flameshieldboost*FRACUNIT + player.firesonicspeed
						end
					else
						player.boostspeed = 80*player.mo.scale+ player.flameshieldboost*FRACUNIT + player.firesonicspeed
					end
				end
			end
			if (player.powers[pw_super] and not P_IsObjectOnGround(player.mo))
			and not (player.powers[pw_carry] == CR_MINECART)
			and not (player.powers[pw_carry] == CR_GRINDRAIL)
				player.drawangle =  R_PointToAngle2(player.mo.x, player.mo.y, (player.mo.x+player.mo.momx), (player.mo.y+player.mo.momy))
				--player.boostspeed = 90*player.mo.state + player.firesonicspeed
				if player.rings <= 200
					player.boostspeed = FixedMul(90*FRACUNIT+((player.rings/3)*FRACUNIT), player.mo.scale) + player.flameshieldboost*FRACUNIT + player.firesonicspeed
				else
					player.boostspeed = FixedMul(157*FRACUNIT, player.mo.scale)+ player.flameshieldboost*FRACUNIT + player.firesonicspeed
				end
				if player.speed < player.boostspeed
					P_Thrust(player.mo, player.mo.angle, FRACUNIT*10)
				end
			end
			
			if player.speed < player.boostspeed
			and player.thrustblock == 0
			and not (player.pflags & PF_JUMPED)
			and not (player.mo.eflags & MFE_SPRUNG)
			and not (player.powers[pw_super] and not P_IsObjectOnGround(player.mo))
			and player.airboost == false
			and not (player.powers[pw_carry] == CR_MINECART)
				if not (player.pflags & PF_DIRECTIONCHAR)
				and (player.pflags & PF_ANALOGMODE)
					P_Thrust(player.mo, player.drawangle, player.boostspeed - player.speed)
				else
					//P_Thrust(player.mo, player.drawangle, player.boostspeed - player.speed)
					if player.pflags & PF_SPINNING
						P_Thrust(player.mo, player.mo.angle, player.boostspeed - player.speed)
					else
						P_Thrust(player.mo, player.speed < 10*player.mo.scale and player.mo.angle or R_PointToAngle2(player.mo.x, player.mo.y, (player.mo.x+player.mo.momx), (player.mo.y+player.mo.momy)), player.boostspeed - player.speed)
						--P_Thrust(player.mo, player.mo.angle, player.boostspeed - player.speed)
					end
				end
			end		
			if not (player.boostmobj1 and player.boostmobj1.valid) then
				player.boostmobj1 = P_SpawnMobj(player.mo.x, player.mo.y, player.mo.z, MT_GFZFLOWER1)
				player.boostmobj1.flags2 = $|MF2_DONTDRAW
				if not (player.mo.eflags & MFE_UNDERWATER)
					if player.modernmenu.contents[10][2].value == 2
					or player.modernmenu.contents[10][2].value == 3
						S_StartSound(player.boostmobj1, sfx_boost3)
					elseif player.modernmenu.contents[10][2].value == 4
					and (player.modernmenu.contents[7][2].value == 1
					or (player.modernmenu.contents[7][2].value == 2 and player.rushmode))
						S_StartSound(player.boostmobj1, sfx_fbost3)
					end
				else
					if player.modernmenu.contents[10][2].value == 2
					or player.modernmenu.contents[10][2].value == 3
						S_StartSound(player.boostmobj1, sfx_wtbst3)
					elseif player.modernmenu.contents[10][2].value == 4
					and (player.modernmenu.contents[7][2].value == 1
					or (player.modernmenu.contents[7][2].value == 2 and player.rushmode))
						S_StartSound(player.boostmobj1, sfx_fwbst3)
					end
				end					
				P_MoveOrigin(player.boostmobj1, player.mo.x, player.mo.y, player.mo.z)
			elseif (player.boostmobj1 and player.boostmobj1.valid)
				P_MoveOrigin(player.boostmobj1, player.mo.x, player.mo.y, player.mo.z)
				if player.modernmenu.contents[10][2].value == 4
				and (player.modernmenu.contents[7][2].value == 1
				or (player.modernmenu.contents[7][2].value == 2 and player.rushmode))
					if not (player.mo.eflags & MFE_UNDERWATER)
						if not (S_SoundPlaying(player.boostmobj1, sfx_fbost3))
						and not (S_SoundPlaying(player.boostmobj1, sfx_fbost4))
							S_StartSound(player.boostmobj1, sfx_fbost4)
						end
					else
						if not (S_SoundPlaying(player.boostmobj1, sfx_fwbst4))
						and not (S_SoundPlaying(player.boostmobj1, sfx_fwbst4))
							S_StartSound(player.boostmobj1, sfx_fwbst4)
						end
					end
				end
			end
			if not (player.boostmobj2 and player.boostmobj2.valid) then
				player.boostmobj2 = P_SpawnMobj(player.mo.x, player.mo.y, player.mo.z, MT_GFZFLOWER1)
				player.boostmobj2.flags2 = $|MF2_DONTDRAW
				P_MoveOrigin(player.boostmobj2, player.mo.x, player.mo.y, player.mo.z)
			elseif (player.boostmobj2 and player.boostmobj2.valid)
				if player.modernmenu.contents[10][2].value != 0
				and player.modernmenu.contents[10][2].value != 1
					if not (player.mo.eflags & MFE_UNDERWATER)
						if not (S_SoundPlaying(player.boostmobj2, sfx_boost4))
							S_StartSound(player.boostmobj2, sfx_boost4)
						end
					else
						if not (S_SoundPlaying(player.boostmobj2, sfx_wtbst4))
							S_StartSound(player.boostmobj2, sfx_wtbst4)
						end
					end
				end
				P_MoveOrigin(player.boostmobj2, player.mo.x, player.mo.y, player.mo.z)
			end
		elseif player.airboost == false
		and player.boosting == false
		or (player.speed < FixedMul(45*FRACUNIT, player.mo.scale) and not (player.powers[pw_super]))
		or (player.speed < FixedMul(20*FRACUNIT, player.mo.scale) and (player.powers[pw_super]))
			if (player.boostmobj1 and player.boostmobj1.valid)
				S_StopSound(player.boostmobj1)
				P_RemoveMobj(player.boostmobj1)
			end
			if (player.boostmobj2 and player.boostmobj2.valid)
				S_StopSound(player.boostmobj2)
				P_RemoveMobj(player.boostmobj2)
				S_SetInternalMusicVolume(100, player)
			end
			player.ringrange = 0
			if player.sonic_ringrange and player.sonic_ringrange.valid
				P_RemoveMobj(player.sonic_ringrange)
			end
			if player.candrift == false
				player.charflags = $ & ~SF_NOSKID
			end
		end
		if ((player.speed >= FixedMul(45*FRACUNIT, player.mo.scale) and not (player.powers[pw_super])) or (player.speed >= FixedMul(20*FRACUNIT, player.mo.scale) and (player.powers[pw_super])))
		and player.airboost == true
		and not (P_IsObjectOnGround(player.mo))
		and not (P_PlayerInPain(player))
		and player.playerstate == PST_LIVE
		and not (player.powers[pw_carry])
		and player.airboostheld == true --Hopefully this line doesnt break
			if player.mo.state == S_PLAY_AIRBOOST
			or player.boostheld == true --We're also gonna call the Boost Aura function here.
				if player.modernmenu.contents[7][1].value == 0 -- Boost Aura
					ModernSonicRebornBoost(player.mo)
				elseif player.modernmenu.contents[7][1].value == 1 -- Boost Aura
				or player.modernmenu.contents[7][1].value == 2 -- Boost Aura
					ModernSonicGenerationsBoost(player.mo)					
				elseif player.modernmenu.contents[7][1].value == 3 -- Boost Aura
					ModernSonicColorsBoost(player.mo)					
				elseif player.modernmenu.contents[7][1].value == 4 -- Boost Aura
					ModernSonicRushBoost(player.mo)
				elseif player.modernmenu.contents[7][1].value == 5 -- Boost Aura
					ModernSonicForcesBoost(player.mo)
				elseif player.modernmenu.contents[7][1].value == 7 -- Boost Aura
					ModernSonicOldBoost(player.mo)
				elseif player.modernmenu.contents[7][1].value == 8 -- Boost Aura
					ModernSonicRebornBoost(player.mo)
					ModernSonicGenerationsBoost(player.mo)
					ModernSonicColorsBoost(player.mo)
					ModernSonicRushBoost(player.mo)
					ModernSonicForcesBoost(player.mo)
					ModernSonicOldBoost(player.mo)
				end
				if player.firesonic
					FireSonicFireSpawn(player)
				end
			end
			if player.airboost == true
			and player.mo.state ~= S_PLAY_AIRBOOST
			and player.boostheld == true
				if not (player.boostmobj1 and player.boostmobj1.valid) then
					player.boostmobj1 = P_SpawnMobj(player.mo.x, player.mo.y, player.mo.z, MT_GFZFLOWER1)
					player.boostmobj1.flags2 = $|MF2_DONTDRAW
					player.boostmobj1.fuse = 250
					if not (player.mo.eflags & MFE_UNDERWATER)
						S_StartSound(player.boostmobj1, sfx_boost3)
					else
						S_StartSound(player.boostmobj1, sfx_wtbst3)
					end
					P_MoveOrigin(player.boostmobj1, player.mo.x, player.mo.y, player.mo.z)
				elseif (player.boostmobj1 and player.boostmobj1.valid)
					P_MoveOrigin(player.boostmobj1, player.mo.x, player.mo.y, player.mo.z)
				end
				if not (player.boostmobj2 and player.boostmobj2.valid) then
					player.boostmobj2 = P_SpawnMobj(player.mo.x, player.mo.y, player.mo.z, MT_GFZFLOWER1)
					player.boostmobj2.flags2 = $|MF2_DONTDRAW
					P_MoveOrigin(player.boostmobj2, player.mo.x, player.mo.y, player.mo.z)
					player.boostmobj2.fuse = 250
				elseif (player.boostmobj2 and player.boostmobj2.valid)
					if player.modernmenu.contents[10][2].value != 0
					and player.modernmenu.contents[10][2].value != 1
						if not (player.mo.eflags & MFE_UNDERWATER)
							if not (S_SoundPlaying(player.boostmobj2, sfx_boost4))
								S_StartSound(player.boostmobj2, sfx_boost4)
							end
						else
							if not (S_SoundPlaying(player.boostmobj2, sfx_wtbst4))
								S_StartSound(player.boostmobj2, sfx_wtbst4)
							end
						end
					end
					P_MoveOrigin(player.boostmobj2, player.mo.x, player.mo.y, player.mo.z)
				end
				if	not (player.sonic_ringrangeairboost) 
					player.sonic_ringrangeairboost = P_SpawnMobj(player.mo.x + player.mo.momx, player.mo.y+ player.mo.momy, player.mo.z + player.mo.momz + player.mo.height/2 - 80*player.mo.scale, MT_RINGRANGE)
					player.sonic_ringrangeairboost.scale = (player.sonic_ringcharge and 2 or 1)*player.mo.scale
					player.sonic_ringrangeairboost.height = $*(player.powers[pw_super] and 2 or 1)
					player.sonic_ringrangeairboost.radius = $*(player.powers[pw_super] and 2 or 1)
					player.sonic_ringrangeairboost.target = player.mo
				end
			end
		end
		if player.airboost == true
		and player.boostheld == true
		and ((player.speed >= FixedMul(45*FRACUNIT, player.mo.scale) and not (player.powers[pw_super])) or (player.speed >= FixedMul(20*FRACUNIT, player.mo.scale) and (player.powers[pw_super])))
			if player.sonic_ringrangeairboost and player.sonic_ringrangeairboost.valid
				P_MoveOrigin(player.sonic_ringrangeairboost, player.mo.x, player.mo.y, player.mo.z)
			end
		else
			if player.sonic_ringrangeairboost and player.sonic_ringrangeairboost.valid
				P_RemoveMobj(player.sonic_ringrangeairboost)
				player.sonic_ringrangeairboost = nil
			end
		end
		if player.boosting == true
		or player.superboost == true
		or player.sliding == 1
		or (player.customhoming > 0)
		or (player.mo.state == S_PLAY_AIRBOOST or (player.airboost == true and player.mo.state == S_PLAY_FALL))
		or player.lightdashing > 0
		or (player.powers[pw_super] and player.speed >= FixedMul(10*FRACUNIT, player.mo.scale) and not (player.powers[pw_carry]))
			if player.flungrange == 0
			or player.flungrange == nil
				player.sonic_flung = P_SpawnMobj(player.mo.x , player.mo.y, player.mo.z, MT_FAKEAURA)
				player.sonic_flung.scale = player.mo.scale*3/2
				player.sonic_flung.height = player.mo.height
				player.sonic_flung.radius = player.mo.radius
				player.sonic_flung.target = player.mo
				player.flungrange = 1
			end
			if player.sonic_flung.valid
				if player.boosting == true
				or player.superboost == true
					player.sonic_flung.radius = player.mo.radius*3
				elseif player.sliding == 1
					player.sonic_flung.radius = player.mo.radius*2
				elseif player.customhoming > 0
					player.sonic_flung.radius = player.mo.radius*4
				end
				if player.customhoming > 0
					P_MoveOrigin(player.sonic_flung, player.mo.x, player.mo.y, player.mo.z-40*FRACUNIT)
				else
					P_MoveOrigin(player.sonic_flung, player.mo.x, player.mo.y, player.mo.z)
				end
			end
		else
			player.flungrange = 0
			if player.sonic_flung and player.sonic_flung.valid
				P_RemoveMobj(player.sonic_flung)
			end
		end
		if ((player.speed < 45*player.mo.scale and not (player.powers[pw_super])) or (player.speed < 10*player.mo.scale and (player.powers[pw_super])) and not (player.boostfuckedbywall <= 3))
		and (player.boosting == true or player.superboost == true)
		and player.boostcanceltimer == 0
		
			if (player.boostheld == false or player.mo.state == S_PLAY_SPRING)
			or ((player.boostheld == true and (player.mo.state == S_PLAY_WALK) or (player.mo.state == S_PLAY_STND) or (player.mo.state == S_PLAY_SPINDASH) or (player.mo.state == S_PLAY_RUN) or (player.mo.state == S_PLAY_BOOSTRUN) or (player.mo.state == S_PLAY_FIRESONICBOOST)) and player.boostfuckedbywall > 3)
			or (not (P_IsObjectOnGround(player.mo)))
				player.boosting = false
				player.superboost = false
			end
		end
		if P_IsObjectOnGround(player.mo)
		and not (player.pflags & (PF_SPINNING|PF_STARTDASH))
		and not (player.powers[pw_carry])
		//and not (player.powers[pw_super])
		and player.sliding == 0
		and player.playerstate == PST_LIVE
		and not (player.pflags & PF_SLIDING)
			player.superboost = false
			if player.boosting == true
				if player.mo.state != S_PLAY_DRIFTRIGHT
				and player.mo.state != S_PLAY_DRIFTLEFT
				and player.mo.state != S_PLAY_GRND
				and player.mo.state != S_PLAY_ROLL
				and player.mo.state != S_PLAY_FIRESONICBOOST
					player.mo.state = S_PLAY_BOOSTRUN
				end
			end
		end
		if player.sonic_rings
			for i = table.maxn(player.sonic_rings), 1, -1
				local ring = player.sonic_rings[i]
				if not (ring.valid and ring.health)
					table.remove(player.sonic_rings,i)
					continue
				end
				if not ring.ringchasetimer
					P_RemoveMobj(ring)
					table.remove(player.sonic_rings,i)
					continue
				end
				if P_AproxDistance(player.mo.z - ring.z,P_AproxDistance(player.mo.x - ring.x, player.mo.y - ring.y)) <= 256*player.mo.scale
					ring.flags = $ & ~MF_NOCLIP
				else
					ring.flags = $ | MF_NOCLIP
				end
				ring.ringchasetimer = $ - 1
				A_HomingChase(ring,min((6*TICRATE-ring.ringchasetimer)*8, max(48, FixedHypot(FixedHypot(player.mo.momx, player.mo.momy), player.mo.momz)/FRACUNIT + 100))*FRACUNIT)
			end
		end	
		if player.boostenergy
			for i = table.maxn(player.boostenergy), 1, -1
				local boostenergy = player.boostenergy[i]
				if not (boostenergy.valid and boostenergy.health)
					table.remove(player.boostenergy,i)
					continue
				end
				if not boostenergy.boostchasetimer
					P_RemoveMobj(boostenergy)
					table.remove(player.boostenergy,i)
					continue
				end
				boostenergy.boostchasetimer = $ - 1
				if leveltime & 3
					local boostsparkle = P_SpawnMobjFromMobj(boostenergy,
					P_RandomRange(-20, 20)*FRACUNIT,
					P_RandomRange(-20, 20)*FRACUNIT,
					P_RandomRange(-20, 20)*FRACUNIT,
					MT_BOXSPARKLE)
					boostsparkle.fuse = 6
					boostsparkle.colorized = true
				end
				boostenergy.rollangle = $1 + ANG10
				local ghs = P_SpawnGhostMobj(boostenergy)
				ghs.scale = boostenergy.scale/2
				ghs.destscale = boostenergy.scale/4
				ghs.fuse = 8
				ghs.sprite = SPR_THOK
				ghs.frame = A|FF_TRANS80|FF_FULLBRIGHT
				if boostenergy.boostchasetimer
					if boostenergy.boostchasetimer > 0
					and boostenergy.boostchasetimer <= 6*TICRATE
						boostenergy.flags = $|MF_SPECIAL
						if boostenergy.target and boostenergy.target
							//boostenergy.destscale = boostenergy.target.scale
							boostenergy.scale = boostenergy.target.scale
						end
						if P_AproxDistance(player.mo.z - boostenergy.z,P_AproxDistance(player.mo.x - boostenergy.x, player.mo.y - boostenergy.y)) <= 256*player.mo.scale
							boostenergy.flags = $ & ~MF_NOCLIP
						else
							boostenergy.flags = $ | MF_NOCLIP
						end
						A_HomingChase(boostenergy,min((6*TICRATE-boostenergy.boostchasetimer)*8, max(48, FixedHypot(FixedHypot(player.mo.momx, player.mo.momy), player.mo.momz)/FRACUNIT + 100))*FRACUNIT)
	
					end
				end
			end
		end

		//////////SPINDASH
		//WHy the fuck am I DoInG Thhhisisi???!?
		if player.crouching 
		and P_IsObjectOnGround(player.mo)
		and player.speed < 1*player.mo.scale
		and (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
		and player.modernmenu.contents[2][10].value == 1
			player.pflags = $|PF_JUMPSTASIS
			if player.cmd.buttons & BT_JUMP
			and not (player.spindashheld)
				player.pflags = $|PF_SPINNING|PF_STARTDASH
				player.modernspindash = true
				if player.modernmenu.contents[10][5].value == 0
					S_StopSound(player.mo)
					S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_ruspnw or sfx_ruspin)
				elseif player.modernmenu.contents[10][5].value == 1
				and not S_SoundPlaying(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_06spnw or sfx_06spin)
					S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_06spnw or sfx_06spin)
				elseif player.modernmenu.contents[10][5].value == 2
					S_StopSound(player.mo)
					S_StartSound(player.mo, sfx_mspdsh)
				elseif player.modernmenu.contents[10][5].value == 3
					S_StopSound(player.mo)
					S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_sdpdsw or sfx_sdpdsh)
				elseif player.modernmenu.contents[10][5].value == 4
					S_StopSound(player.mo)
					S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_cspdsw or sfx_cspdsh)
				end
				if player.dashspeed < 110*player.mo.scale
					player.dashspeed = $ + 15*player.mo.scale
				else
					player.dashspeed = 110*player.mo.scale
				end
				player.jt = -4
			end
			player.spindashheld = player.cmd.buttons & BT_JUMP
			
			if player.pflags & PF_STARTDASH
			and player.dashspeed < 110*player.mo.scale
				if leveltime % 10 == 1
					if player.modernmenu.contents[10][5].value == 0
						S_StopSound(player.mo)
						S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_ruspnw or sfx_ruspin)
					elseif player.modernmenu.contents[10][5].value == 1
					and not S_SoundPlaying(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_06spnw or sfx_06spin)
						S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_06spnw or sfx_06spin)
					elseif player.modernmenu.contents[10][5].value == 2
						S_StopSound(player.mo)
						S_StartSound(player.mo, sfx_mspdsh)
					elseif player.modernmenu.contents[10][5].value == 3
						S_StopSound(player.mo)
						S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_sdpdsw or sfx_sdpdsh)
					elseif player.modernmenu.contents[10][5].value == 4
						S_StopSound(player.mo)
						S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_cspdsw or sfx_cspdsh)
					end
				end
				player.dashspeed = $+FU
			end
		end
		if player.modernspindash
		and P_IsObjectOnGround(player.mo)
		and not (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
		and player.playerstate == PST_LIVE
			P_InstaThrust(player.mo, player.mo.angle, player.dashspeed)
			S_StopSound(player.mo)
			if player.modernmenu.contents[10][7].value == 0
				S_StartSound(player.mo,player.mo.eflags & MFE_UNDERWATER and sfx_ruzomw or sfx_ruzoom)
			elseif player.modernmenu.contents[10][7].value == 1
				S_StartSound(player.mo,player.mo.eflags & MFE_UNDERWATER and sfx_06zomw or sfx_06zoom)
			elseif player.modernmenu.contents[10][7].value == 2
				S_StartSound(player.mo,player.mo.eflags & MFE_UNDERWATER and sfx_sdpzmw or sfx_sdpzom)
			elseif player.modernmenu.contents[10][7].value == 3
				S_StartSound(player.mo,player.mo.eflags & MFE_UNDERWATER and sfx_wdpzom or sfx_mdpzom)
			elseif player.modernmenu.contents[10][7].value == 4
				S_StartSound(player.mo,player.mo.eflags & MFE_UNDERWATER and sfx_gzomw or sfx_gzoom)
			end
			player.mo.state = S_PLAY_ROLL
			player.pflags = $ & ~PF_STARTDASH
			player.modernspindash = false
		end
		if not (player.pflags & PF_SPINNING)
			player.modernspindash = false
			player.dashspeed = 30*FU
		end
		if player.modernspindash
			if (player.mo.state != S_PLAY_SPINDASH)
				player.mo.state = S_PLAY_SPINDASH
			else
				player.mo.tics = 1
			end
		end
//DROP DASH
		
		if player.dropdashing == nil
			player.dropdashing = false
		end
		if player.dropdashspeed == nil
		or player.dropdashing == false
			player.dropdashspeed = max(36*FU, player.speed)
		end
		if player.dropdash_zerogravitytimer == nil
			player.dropdash_zerogravitytimer = 0
		elseif player.dropdash_zerogravitytimer != 0
			player.dropdash_zerogravitytimer = $ - 1
		end
		if not (player.cmd.buttons & BT_JUMP)
			player.dropdashable = false
		end
		if player.dropdashable
			if not player.customhoming
			and not player.dropdashdown
			and (player.cmd.buttons & BT_JUMP)
			and not player.dropdashing
				if (player.modernmenu.contents[2][9].value == 1 -- Drop Dash
				or player.modernmenu.contents[2][9].value == 2)
					if not (player.superboost)
					and not player.modernwallslide
						player.dropdashmobj = P_SpawnMobjFromMobj(player.mo, 0,0,0, MT_OVERLAY)
						player.dropdashmobj.target = player.mo
						player.dropdashmobj.tics = -1
						if player.modernmenu.contents[10][6].value == 0
							S_StartSound(player.dropdashmobj, player.mo.eflags & MFE_UNDERWATER and sfx_ruspnw or sfx_ruspin)
						elseif player.modernmenu.contents[10][6].value == 1
							S_StartSound(player.dropdashmobj, player.mo.eflags & MFE_UNDERWATER and sfx_06spnw or sfx_06spin)
						elseif player.modernmenu.contents[10][6].value == 2
							S_StartSound(player.dropdashmobj, sfx_mspdsh)
						elseif player.modernmenu.contents[10][6].value == 3
							S_StartSound(player.dropdashmobj, player.mo.eflags & MFE_UNDERWATER and sfx_sdpdsw or sfx_sdpdsh)
						elseif player.modernmenu.contents[10][6].value == 4
							S_StartSound(player.dropdashmobj, player.mo.eflags & MFE_UNDERWATER and sfx_cspdsw or sfx_cspdsh)
						elseif player.modernmenu.contents[10][6].value == 5
							S_StartSound(player.dropdashmobj, player.mo.eflags & MFE_UNDERWATER and sfx_wdpdsh or sfx_mdpdsh)
						elseif player.modernmenu.contents[10][6].value == 6
							S_StartSound(player.dropdashmobj, player.mo.eflags & MFE_UNDERWATER and sfx_gdrpdw or sfx_gdrpds)
						end
						player.jt = 4
						player.dropdashing = true
						player.dropdashable = false	
					end
				end
			end
		end
		if player.dropdashing
		and not (P_PlayerInPain(player))
		and player.playerstate == PST_LIVE
			if not (player.mo.state == S_PLAY_JUMP)
				player.mo.state = S_PLAY_JUMP
			end
			if (player.cmd.buttons & BT_JUMP or (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1))) -- Actionswap
			and (player.pflags & PF_JUMPED)
				if player.stompdown
					player.dropdashspeed = abs(player.prevmomz)*2
				end
				--min(player.dropdashspeed+FU, 140*FU)
				if player.dropdashspeed < 140*FU
					player.dropdashspeed = $+FU
				end
				--player.dropdashspeed = $+FU
				player.dropdashdown = true
			elseif not P_IsObjectOnGround(player.mo)
				player.dropdashing = false
			end
			if P_IsObjectOnGround(player.mo)
			and player.playerstate == PST_LIVE
			and not (player.pflags & PF_STARTDASH)
			and (player.cmd.buttons & BT_JUMP
			or (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1))) -- Actionswap		
				if player.modernmenu.contents[10][7].value == 0
					S_StartSound(player.mo,player.mo.eflags & MFE_UNDERWATER and sfx_ruzomw or sfx_ruzoom)
				elseif player.modernmenu.contents[10][7].value == 1
					S_StartSound(player.mo,player.mo.eflags & MFE_UNDERWATER and sfx_06zomw or sfx_06zoom)
				elseif player.modernmenu.contents[10][7].value == 2
					S_StartSound(player.mo,player.mo.eflags & MFE_UNDERWATER and sfx_sdpzmw or sfx_sdpzom)
				elseif player.modernmenu.contents[10][7].value == 3
					S_StartSound(player.mo,player.mo.eflags & MFE_UNDERWATER and sfx_wdpzom or sfx_mdpzom)
				elseif player.modernmenu.contents[10][7].value == 4
					S_StartSound(player.mo,player.mo.eflags & MFE_UNDERWATER and sfx_gzomw or sfx_gzoom)
				end
				player.mo.state = S_PLAY_ROLL
				player.FORCETHEFUCKINGSPIN = 3
				player.pflags = $|PF_SPINNING
				P_InstaThrust(player.mo, (twod and player.drawangle or player.mo.angle), max((player.mo.eflags & MFE_UNDERWATER and player.dropdashspeed/2 or player.dropdashspeed) , player.speed+10*FU))
				player.dropdashing = false
			end
		elseif not player.dropdashing
			if player.dropdashmobj and player.dropdashmobj.valid
				P_RemoveMobj(player.dropdashmobj)
				player.dropdashmobj = nil
			end
		end
		if player.FORCETHEFUCKINGSPIN
			player.FORCETHEFUCKINGSPIN = $-1
		end
		if player.FORCETHEFUCKINGSPIN
		and P_IsObjectOnGround(player.mo)
		and player.playerstate == PST_LIVE
			player.pflags = $|PF_SPINNING
			player.mo.state = S_PLAY_ROLL
			P_InstaThrust(player.mo, (twod and player.drawangle or player.mo.angle), max((player.mo.eflags & MFE_UNDERWATER and player.dropdashspeed/2 or player.dropdashspeed) , player.speed+10*FU))
		end
		if player.dropdashing  and P_IsObjectOnGround(player.mo)
		and not (player.cmd.buttons & BT_JUMP and not (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1))) -- Actionswap))
			player.dropdashing = false
		end
		if player.playerstate != PST_LIVE
			player.dropdashing = false
		end
		if not (player.cmd.buttons & BT_JUMP and not (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1))) -- Actionswap))
			player.dropdashdown = false
		end
		
		if player.mo.prevz == nil
			player.mo.prevz = 0
		end
		
		local rmomz = player.mo.z - player.mo.prevz
		if player.mo.eflags & MFE_VERTICALFLIP
			rmomz = -$
		end
		
		if (player.pflags & PF_SPINNING)
		and player.boosting == true
			if (player.mo.state != S_PLAY_SPINDASH)
				player.mo.state = S_PLAY_SPINDASH
			else
				player.mo.tics = 1
			end
			if player.dropdash_prevslope
			and player.mo.standingslope != player.dropdash_prevslope
			and rmomz > 0
				player.dropdash_zerogravitytimer = TICRATE
				P_SetObjectMomZ(player.mo, abs(player.dropdash_prevslope.zdelta*20), true)
			end
		elseif (player.pflags & PF_SPINNING)
		and player.boosting == false
		and not (player.pflags & PF_STARTDASH)
		and player.playerstate == PST_LIVE
		--and P_IsObjectOnGround(player.mo)
			if (player.mo.state == S_PLAY_SPINDASH)
				player.mo.state = S_PLAY_ROLL
			end
		end
		if player.dropdash_zerogravitytimer
		and player.mo.state == S_PLAY_ROLL
		and player.boosting == true
			P_SetObjectMomZ(player.mo, gravity, true)
		end
		player.dropdash_prevslope = player.mo.standingslope
		player.dropdash_onground = P_IsObjectOnGround(player.mo)
		player.mo.prevz = player.mo.z

	//////ROLLING
		if player.cmd.buttons & BT_FIRENORMAL
		and not player.firenormaldown
		and P_IsObjectOnGround(player.mo)
			if not (player.pflags & PF_SPINNING)
			and FixedHypot(player.mo.momx, player.mo.momy) >= 5*FRACUNIT
				player.slidecanceltimer = 0
				player.sliding = 0
				player.pflags = $|PF_SPINNING
				player.mo.state = S_PLAY_ROLL
				if player.modernmenu.contents[10][4].value == 0
					S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_ruspnw or sfx_ruspin)
				elseif player.modernmenu.contents[10][4].value == 1
					S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_06zomw or sfx_06zoom)
				elseif player.modernmenu.contents[10][4].value == 2
					S_StartSound(player.mo, sfx_mspdsh)
				elseif player.modernmenu.contents[10][4].value == 3
					S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_ssbrlw or sfx_ssbrol)
				elseif player.modernmenu.contents[10][4].value == 4
					S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_gspnw or sfx_gspin)
				end
			elseif (player.pflags & PF_SPINNING)
				player.retainspinboost = false
				player.pflags = $ & ~PF_SPINNING
				player.mo.state = S_PLAY_WALK
			end
		end
	////////JUMP
		if player.customhoming > 0
		and not (P_PlayerInPain(player))
		and player.playerstate == PST_LIVE
		and player.paintimer == 0
			player.pflags = $|PF_JUMPED
			player.airboost = false
			player.airboostheld = false
		end
		if not (player.cmd.buttons & BT_JUMP)
			player.trickheld = false
			player.hopdown = false
			player.trickhold = false
		elseif player.tricking == false
			player.trickhold = true
		end
		if (player.mysticsuper or player.powers[pw_shield] == SH_BUBBLEWRAP)
		and player.mo.eflags & MFE_UNDERWATER
		and player.doublejumped == true
			player.doublejumped = false
			player.pflags = $ & ~PF_THOKKED
			player.jumptimer = 4
		end
		if P_IsObjectOnGround(player.mo)
		or not (player.pflags & PF_JUMPED)
		or P_PlayerInPain(player)
			player.justjumped = false
			player.finishedtrick = false
		end
		/////////////Jump Aura
		
		if (player.pflags & PF_JUMPED or player.powers[pw_carry] == CR_MINECART)
		and player.modernmenu.contents[7][4].value != 4
		and (player.mo.state == S_PLAY_JUMP)
		and player.mo.state ~= S_PLAY_HOP
		and (player.jumptimer > 3 or player.pflags & PF_THOKKED or player.powers[pw_carry] == CR_MINECART)
		and player.playerstate == PST_LIVE
		or (player.mo.state == S_PLAY_JUMP)
		and (player.customhoming)
		or (player.pflags & PF_SPINNING)
		and (player.mo.state == S_PLAY_ROLL)
		or (player.pflags & PF_SPINNING)
		and (player.mo.state == S_PLAY_SPINDASH)
		or player.dropdashing 
			if (player.modernmenu.contents[7][4].value == 1 -- Jump Style
			or player.modernmenu.contents[7][4].value == 4)
			and not (player.mo.state == S_PLAY_SPINDASH)
				player.mo.sprite2 = SPR2_DRPD
				player.mo.frame = leveltime % 6
			elseif player.modernmenu.contents[7][4].value == 2 -- Jump Style
				if player.modernmenu.contents[7][5].value == 4 -- Jump Aura
				or player.modernmenu.contents[7][5].value == 0 -- Jump Aura
					if not (player.mo.state == S_PLAY_SPINDASH)
						player.mo.sprite2 = SPR2_TAL2
					else	
						player.mo.sprite2 = SPR2_TAL3
					end
				else
					if not (player.mo.state == S_PLAY_SPINDASH)
						player.mo.sprite2 = SPR2_GBAR
					else	
						player.mo.sprite2 = SPR2_GBAS
					end
				end
				player.mo.frame = leveltime % 4
			elseif	player.modernmenu.contents[7][4].value == 3 -- Jump Style
				if player.modernmenu.contents[7][5].value == 4 -- Jump Aura
				or player.modernmenu.contents[7][5].value == 0 -- Jump Aura
					if not (player.mo.state == S_PLAY_SPINDASH)
						player.mo.sprite2 = SPR2_TAL4
					else	
						player.mo.sprite2 = SPR2_TAL5
					end
				else
					if not (player.mo.state == S_PLAY_SPINDASH)
						player.mo.sprite2 = SPR2_TAL0
					else	
						player.mo.sprite2 = SPR2_TAL1
					end
				end
				player.mo.frame = leveltime % 4
			
			end
		
			if player.modernmenu.contents[7][5].value != 3 -- Jump Aura
				player.mo.tics = 1
				--local jumpsphere = P_SpawnMobj(player.mo.x, player.mo.y, player.mo.z-FixedMul(player.mo.height/5, P_GravAndScale(player.mo)), MT_MODERNOVERLAY)
				local jumpsphere = P_SpawnMobjFromMobj(player.mo,0,0,0,MT_OVERLAY)
				jumpsphere.state = S_THOK
				jumpsphere.target = player.mo
				jumpsphere.skin = "modernsonic"
				jumpsphere.sprite = SPR_PLAY
				if (player.mo.state == S_PLAY_SPINDASH)
					if player.modernmenu.contents[7][5].value == 0 -- Jump Aura
						jumpsphere.sprite2 = SPR2_SPNR
					elseif player.modernmenu.contents[7][5].value == 1 -- Jump Aura
						jumpsphere.sprite2 = SPR2_SPNU
					elseif player.modernmenu.contents[7][5].value == 2 -- Jump Aura
						jumpsphere.sprite2 = SPR2_SPNC
					elseif player.modernmenu.contents[7][5].value == 4 -- Jump Aura
						jumpsphere.sprite2 = SPR2_SPNF
					end
				else
					if player.modernmenu.contents[7][5].value == 0 -- Jump Aura
						jumpsphere.sprite2 = SPR2_JMPR
					elseif player.modernmenu.contents[7][5].value == 1 -- Jump Aura
						jumpsphere.sprite2 = SPR2_JMPU
					elseif player.modernmenu.contents[7][5].value == 2 -- Jump Aura
						jumpsphere.sprite2 = SPR2_JMPC
					elseif player.modernmenu.contents[7][5].value == 4 -- Jump Aura
						jumpsphere.sprite2 = SPR2_JMPF
					end
				end
				jumpsphere.tics = 1
				if player.modernmenu.contents[5][2].value == 1 -- Jump Aura Blending
					jumpsphere.blendmode = AST_ADD
					jumpsphere.frame = (leveltime % 6 & ~FF_TRANSMASK)|FF_TRANS10|FF_FULLBRIGHT
-- 					jumpsphere.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 6, "jump")
					if player.modernmenu.contents[7][5].value == 0 -- Jump Aura
						jumpsphere.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 6, "srb2jump")
					elseif player.modernmenu.contents[7][5].value == 1 -- Jump Aura
						jumpsphere.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 6, "unleashedjump")
					elseif player.modernmenu.contents[7][5].value == 2 -- Jump Aura
						jumpsphere.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 6, "colorsjump")
					elseif player.modernmenu.contents[7][5].value == 4 -- Jump Aura
						jumpsphere.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 6, "frontiersjump")
					end
				else
					jumpsphere.frame = (leveltime % 6 & ~FF_TRANSMASK)|FF_TRANS40|FF_FULLBRIGHT
					if player.mo.color == SKINCOLOR_UNLEASHED
						jumpsphere.color = SKINCOLOR_SAPPHIRE
					else
						jumpsphere.color = FindMyColor(player, SKINCOLOR_GOLDENROD)
					end
				end
				jumpsphere.rollangle = player.mo.rollangle
				if jumpsphere.target.flags2 & MF2_DONTDRAW
					jumpsphere.flags2 = $|MF2_DONTDRAW
				else
					jumpsphere.flags2 = $ & ~MF2_DONTDRAW
				end
				jumpsphere.angle = player.drawangle
				jumpsphere.spritexscale = player.mo.spritexscale
				jumpsphere.spriteyscale = player.mo.spriteyscale
				jumpsphere.spriteyoffset = player.mo.spriteyoffset
				jumpsphere.dispoffset = 2
				--A_CapeChase(jumpsphere)
				--P_MoveOrigin(jumpsphere, jumpsphere.target.x+jumpsphere.target.momx, jumpsphere.target.y+jumpsphere.target.momy, jumpsphere.target.z+jumpsphere.target.momz+(jumpsphere.target.height/2)-(jumpsphere.height/2))
				if player.modernmenu.contents[7][5].value == 0 -- Jump Aura
					jumpsphere.scale = player.mo.scale*6/5
				else
					jumpsphere.scale = player.mo.scale
				end
				jumpsphere.fuse = 1
				if player.rushmode > 0
				and player.modernmenu.contents[4][1].value == 1
				and player.rushcolor != player.mo.color
					local pulsatingsphere = P_SpawnMobjFromMobj(player.mo,0,0,0,MT_OVERLAY)
					pulsatingsphere.target = player.mo
					pulsatingsphere.skin = "modernsonic"
					pulsatingsphere.sprite = SPR_PLAY
					if (player.mo.state == S_PLAY_SPINDASH)
						if player.modernmenu.contents[7][5].value == 0 -- Jump Aura
							pulsatingsphere.sprite2 = SPR2_SPNR
						elseif player.modernmenu.contents[7][5].value == 1 -- Jump Aura
							pulsatingsphere.sprite2 = SPR2_SPNU
						elseif player.modernmenu.contents[7][5].value == 2 -- Jump Aura
							pulsatingsphere.sprite2 = SPR2_SPNC
						elseif player.modernmenu.contents[7][5].value == 4 -- Jump Aura
							pulsatingsphere.sprite2 = SPR2_SPNF
						end
					else
						if player.modernmenu.contents[7][5].value == 0 -- Jump Aura
							pulsatingsphere.sprite2 = SPR2_JMPR
						elseif player.modernmenu.contents[7][5].value == 1 -- Jump Aura
							pulsatingsphere.sprite2 = SPR2_JMPU
						elseif player.modernmenu.contents[7][5].value == 2 -- Jump Aura
							pulsatingsphere.sprite2 = SPR2_JMPC
						elseif player.modernmenu.contents[7][5].value == 4 -- Jump Aura
							pulsatingsphere.sprite2 = SPR2_JMPF
						end
					end
					pulsatingsphere.rollangle = player.mo.rollangle
					if player.modernmenu.contents[5][2].value == 1 -- Jump Aura Blending
						pulsatingsphere.colorized = true
						if player.overlaytimer > 2
							pulsatingsphere.blendmode = AST_ADD
						else
							pulsatingsphere.blendmode = AST_TRANSLUCENT
						end
					else
						pulsatingsphere.blendmode = AST_TRANSLUCENT
						pulsatingsphere.colorized = player.mo.colorized
					end
					if player.rushcolor == nil
						player.rushcolor = SKINCOLOR_ORANGE
					end
					pulsatingsphere.color = player.rushcolor
					pulsatingsphere.spriteyoffset = player.mo.spriteyoffset
					if pulsatingsphere.target.flags2 & MF2_DONTDRAW
						pulsatingsphere.flags2 = $|MF2_DONTDRAW
					else
						pulsatingsphere.flags2 = $ & ~MF2_DONTDRAW
					end
					pulsatingsphere.angle = player.drawangle
					pulsatingsphere.spritexscale = player.mo.spritexscale
					pulsatingsphere.spriteyscale = player.mo.spriteyscale
					pulsatingsphere.dispoffset = 1
					if player.modernmenu.contents[7][5].value == 0 -- Jump Aura
						pulsatingsphere.scale = player.mo.scale*6/5
					else
						pulsatingsphere.scale = player.mo.scale
					end
					pulsatingsphere.fuse = 1
					if player.overlaytimer > 38 and player.overlaytimer <= 40
						jumpsphere.frame = leveltime % 6|FF_TRANS50|FF_FULLBRIGHT
						pulsatingsphere.frame = leveltime % 6|FF_TRANS90|FF_FULLBRIGHT 
					elseif player.overlaytimer > 36 and player.overlaytimer <= 38
						jumpsphere.frame = leveltime % 6|FF_TRANS60|FF_FULLBRIGHT
						pulsatingsphere.frame = leveltime % 6|FF_TRANS80|FF_FULLBRIGHT 
					elseif player.overlaytimer > 34 and player.overlaytimer <= 36
						jumpsphere.frame = leveltime % 6|FF_TRANS70|FF_FULLBRIGHT 
						pulsatingsphere.frame = leveltime % 6|FF_TRANS70|FF_FULLBRIGHT 
					elseif player.overlaytimer > 32 and player.overlaytimer <= 34
						jumpsphere.frame = leveltime % 6|FF_TRANS80|FF_FULLBRIGHT 
						pulsatingsphere.frame = leveltime % 6|FF_TRANS60|FF_FULLBRIGHT 
					elseif player.overlaytimer > 30 and player.overlaytimer <= 32
						jumpsphere.frame = leveltime % 6|FF_TRANS90|FF_FULLBRIGHT 
						pulsatingsphere.frame = leveltime % 6|FF_TRANS50|FF_FULLBRIGHT 
					elseif player.overlaytimer > 20 and player.overlaytimer <= 30
						jumpsphere.frame = leveltime % 6|FF_TRANS90|FF_FULLBRIGHT 
						pulsatingsphere.frame = leveltime % 6|FF_TRANS40|FF_FULLBRIGHT 
					elseif player.overlaytimer > 18 and player.overlaytimer <= 20
						jumpsphere.frame = leveltime % 6|FF_TRANS90|FF_FULLBRIGHT 
						pulsatingsphere.frame = leveltime % 6|FF_TRANS50|FF_FULLBRIGHT 
					elseif player.overlaytimer > 16 and player.overlaytimer <= 18
						jumpsphere.frame = leveltime % 6|FF_TRANS80|FF_FULLBRIGHT 
						pulsatingsphere.frame = leveltime % 6|FF_TRANS60|FF_FULLBRIGHT 
					elseif player.overlaytimer > 14 and player.overlaytimer <= 16
						jumpsphere.frame = leveltime % 6|FF_TRANS70|FF_FULLBRIGHT 
						pulsatingsphere.frame = leveltime % 6|FF_TRANS70|FF_FULLBRIGHT 
					elseif player.overlaytimer > 12 and player.overlaytimer <= 14
						jumpsphere.frame = leveltime % 6|FF_TRANS60|FF_FULLBRIGHT 
						pulsatingsphere.frame = leveltime % 6|FF_TRANS80|FF_FULLBRIGHT 
					elseif player.overlaytimer > 10 and player.overlaytimer <= 12
						jumpsphere.frame = leveltime % 6|FF_TRANS50|FF_FULLBRIGHT 
						pulsatingsphere.frame = leveltime % 6|FF_TRANS90|FF_FULLBRIGHT 
					elseif player.overlaytimer >= 0 and player.overlaytimer <= 10
						jumpsphere.frame = leveltime % 6|FF_TRANS40|FF_FULLBRIGHT 
						pulsatingsphere.frame = leveltime % 6|FF_TRANS90|FF_FULLBRIGHT 
					end
				end
			end
		end
		if player.pflags & PF_JUMPED
		and not (player.powers[pw_carry])
		and not (player.mo.state == S_PLAY_ROLL)
		and not (player.pflags & PF_THOKKED)
		and player.stomping == false
		and player.mo.state ~= S_PLAY_FALL
		and player.mo.state ~= S_PLAY_SPRING
		and player.finishedtrick == false
		and not (player.powers[pw_nocontrol])
		and not (player.pflags & PF_FULLSTASIS)
			player.jumptimer = $1+1
			if player.jumptimer <= 3
				if player.boosting == true
					player.mo.state = S_PLAY_AIRBOOST
				else
					player.mo.state = S_PLAY_HOP
				end
				if not (s.eflags & MFE_UNDERWATER)
				and (s.momz*P_MobjFlip(s) > 0)
					if p.jumptimer == 3 --Golden Shine: Quicker rise to simulate Unleashed/Gens physics.
						s.momz = $*24/41
					else
						s.momz = $*5/4
					end
				end
			end
			if player.cmd.buttons & BT_JUMP
			and player.mo.state == S_PLAY_HOP
			and (player.jumptimer > 3)
			and player.hopdown == true
				if player.modernmenu.contents[10][1].value != 0
				and player.modernmenu.contents[10][1].value != 2
					S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_spnwtr or sfx_airspn)
				end
				player.mo.state = S_PLAY_JUMP
			end
			if player.jumptimer > 3
			and player.mo.state == S_PLAY_FALL
				player.mo.state = S_PLAY_HOPFALL
			end
		else
			player.jumptimer = 0
		end
		if player.powers[pw_carry] 
			player.stomping = false
			player.airboost = false
			player.airboostheld = false
			player.hopdown = false
			player.justjumped = false
		end
		if P_IsObjectOnGround(player.mo)
		or not (player.pflags & PF_JUMPED)
			player.doublejumped = false
			
		end
		if player.airboostcounter  and player.airboostcounter < 0
			player.airboostcounter = 0
		end
		if P_IsObjectOnGround(player.mo)
			if player.mo.state == S_PLAY_FALL
			or player.mo.state == S_PLAY_HOPFALL
				player.mo.state = S_PLAY_STND
			end
			player.airboostcounter = 0
		end
		if player.pflags & PF_JUMPED
		and not (player.mo.state == S_PLAY_SPRING)
		and not (player.mo.state == S_PLAY_FALL)
		and player.airboost == false
		and player.hopdown == false
		and player.justjumped == false
		and player.stomping == false
		and not (player.powers[pw_carry])
		//and not (player.mo.state == S_PLAY_ROLL)
		//and not (player.pflags & PF_THOKKED)
		and player.superboost == false
		and not P_IsObjectOnGround(player.mo)
		and player.customhoming == 0
		and player.cmd.buttons & BT_JUMP
		and not (player.mo.state >= S_PLAY_TRICKALT_1 and player.mo.state <= S_PLAY_TRICKALT_3) 
		and not (player.mo.state >= S_PLAY_TRICK_1 and player.mo.state <= S_PLAY_TRICKEND) 
		and not (player.pflags & PF_FULLSTASIS)
		and player.trickheld == false
			player.justjumped = true
			player.mo.state = S_PLAY_HOP
			player.hopdown = true
			if not (player.mo.eflags & MFE_UNDERWATER)
				if player.modernmenu.contents[10][1].value == 1
					S_StartSound(player.mo, sfx_mjump)
				elseif player.modernmenu.contents[10][1].value == 3
					S_StartSound(player.mo, sfx_mjump2)
				elseif player.modernmenu.contents[10][1].value == 4
					S_StartSound(player.mo, sfx_mjump3)
				elseif player.modernmenu.contents[10][1].value == 0
					S_StartSound(player.mo, sfx_mjump5)
				elseif player.modernmenu.contents[10][1].value == 2
					S_StartSound(player.mo, sfx_mjump6)
				end
			else 
				if player.modernmenu.contents[10][1].value == 1
					S_StartSound(player.mo, sfx_jumpwt)
				elseif player.modernmenu.contents[10][1].value == 3
					S_StartSound(player.mo, sfx_jmpwt2)
				elseif player.modernmenu.contents[10][1].value == 4
					S_StartSound(player.mo, sfx_jmpwt3)
				elseif player.modernmenu.contents[10][1].value == 0
					S_StartSound(player.mo, sfx_jmpwt5)
				elseif player.modernmenu.contents[10][1].value == 2
					S_StartSound(player.mo, sfx_jmpwt6)
				end
			end
			if player.modernmenu.contents[6][1].value == 1 -- Voices
				if player.modernmenu.contents[6][2].value == 0
					PlayModernSound(player, 1)
				elseif player.modernmenu.contents[6][2].value == 1
					PlayModernSound(player, 13)
				elseif player.modernmenu.contents[6][2].value == 2
					PlayModernSound(player, 7)
				elseif player.modernmenu.contents[6][2].value == 3
					PlayModernSound(player, 19)
				elseif player.modernmenu.contents[6][2].value == 4
					PlayModernSound(player, 25)	
				elseif player.modernmenu.contents[6][2].value == 5
					PlayModernSound(player, 26)
				end
			end
		end
		if (player.powers[pw_carry] == CR_ROLLOUT)
			player.customhoming = 0
			if player.pflags & PF_JUMPED
			and (player.mo.state == S_PLAY_JUMP or player.mo.state == S_PLAY_ROLL)
				player.pflags = $ & ~PF_JUMPED
				player.mo.state = S_PLAY_WALK
			end
		end
		if P_PlayerInPain(player)
			player.footsweepattack = 0
			player.customhoming = 0
			player.mo.target = nil
		end
		if player.powers[pw_carry]
		and player.customhoming > 0
			player.customhoming = 0
			player.pflags = $ & ~PF_JUMPED
		end
		
		//Homing
		if player.cmd.buttons & BT_FIRENORMAL
		and not player.firenormaldown
		and player.customhoming == 0
		and player.rettarget and player.rettarget.valid and player.rettarget.health
		and not (player.rettarget.flags2 & MF2_FRET)
		and player.rettarget.type ~= MT_BIGMINE
		and player.rettarget.type ~= MT_EGGSHIELD
		and player.rettarget.type ~= MT_TNTBARREL
		and player.rettarget.type ~= MT_FAKEMOBILE
		and (player.rettarget.flags & MF_SHOOTABLE or player.rettarget.flags2 & MF2_INVERTAIMABLE or player.rettarget.flags & MF_SPRING or player.rettarget.type == MT_METALSONIC_BATTLE or player.rettarget.type == MT_NIGHTSBUMPER or player.rettarget.type == MT_PULLEYHANDLE)
		and not (player.rettarget and player.rettarget.state == S_METALSONIC_VECTOR)
		and player.stomping == false
		and player.ret and player.ret.valid
		and player.modernmenu.contents[2][11].value == 2 --Homing Input
			if player.perfectCapable
				player.boostmeter = $ + 10
				S_IncrementModernChain(player.mo)
				player.doubledamage = true
				S_StartSound(player.mo, sfx_perfhm)
				if (player.modernmenu.contents[2][4].value == 1 and player == displayplayer) -- Quakes
					P_StartQuake(15*FRACUNIT, 5)
				end
			end
			player.thrustblock = 5
			if player.modernmenu.contents[2][5].value == 1 -- HomingCam
				player.camerascale = 7*FRACUNIT/2
			end
			player.customhoming = 3*TICRATE
			player.gotbonked = false
			if not (player.mo.eflags & MFE_UNDERWATER)
				if player.modernmenu.contents[10][9].value == 0
					S_StartSound(player.mo, sfx_ruthok)
				elseif player.modernmenu.contents[10][9].value == 1
					S_StartSound(player.mo, sfx_06thok)
				elseif player.modernmenu.contents[10][9].value == 2
					S_StartSound(player.mo, sfx_mthok)
				elseif player.modernmenu.contents[10][9].value == 3
					S_StartSound(player.mo, sfx_sdpzom)					
				end
			else
				if player.modernmenu.contents[10][9].value == 0
					S_StartSound(player.mo, sfx_ruthkw)
				elseif player.modernmenu.contents[10][9].value == 1
					S_StartSound(player.mo, sfx_06thkw)
				elseif player.modernmenu.contents[10][9].value == 2
					S_StartSound(player.mo, sfx_mthokw)
				elseif player.modernmenu.contents[10][9].value == 3
					S_StartSound(player.mo, sfx_sdpzmw)					
				end
			end
			if player.modernmenu.contents[6][1].value == 1 -- Voices
				if player.modernmenu.contents[6][2].value == 0
					PlayModernSound(player, 4)
				elseif player.modernmenu.contents[6][2].value == 1
					PlayModernSound(player, 16)
				elseif player.modernmenu.contents[6][2].value == 2
					PlayModernSound(player, 10)
				elseif player.modernmenu.contents[6][2].value == 3
					PlayModernSound(player, 22)
				elseif player.modernmenu.contents[6][2].value == 4
					PlayModernSound(player, 25)
				elseif player.modernmenu.contents[6][2].value == 5
					PlayModernSound(player, 26)
				end
			end
		end
		player.firenormaldown = player.cmd.buttons & BT_FIRENORMAL
		
		if player.customhoming > 0
		and player.modernmenu.contents[2][5].value == 2 -- HomingCam
			camera.momx = 0
			camera.momy = 0
			camera.momz = 0
		end
		if player.gotbonked
			player.mo.state = S_PLAY_PAIN
		end
		if player.customhoming > 0
		and player.thrustblock == 0
		and FixedHypot(FixedHypot(player.mo.momx, player.mo.momy), player.mo.momz) < 10*FU
			player.customhoming = 0
			player.mo.state = S_PLAY_PAIN
			player.pflags = $ & ~(PF_JUMPED|PF_THOKKED|PF_STARTJUMP|PF_NOJUMPDAMAGE)
			player.gotbonked = true
			player.paintimer = 20
			player.trickable = false
			player.tricking = false
			S_StartSound(player.mo, sfx_mcol)
			if player.modernmenu.contents[6][1].value == 1 -- Voices
				if player.modernmenu.contents[6][2].value == 0
					PlayModernSound(player, 27)
				elseif player.modernmenu.contents[6][2].value == 1
					PlayModernSound(player, 29)
				elseif player.modernmenu.contents[6][2].value == 2
					PlayModernSound(player, 30)
				elseif player.modernmenu.contents[6][2].value == 3
					PlayModernSound(player, 28)
				elseif player.modernmenu.contents[6][2].value == 4
					PlayModernSound(player, 25)
				elseif player.modernmenu.contents[6][2].value == 5
					PlayModernSound(player, 26)
				end
			end
			P_InstaThrust(player.mo, player.mo.angle, -FixedMul(player.actionspd >> 4, player.mo.scale))
			P_SetObjectMomZ(player.mo, player.actionspd >> 4, false)
			if player.mo.eflags & MFE_UNDERWATER
				player.mo.momz = $ / 2
			end
		end
		if (P_IsObjectOnGround(player.mo) and not player.customhoming) or not (player.pflags & PF_JUMPED)
			player.customhoming = 0
			--player.usedhomingattack = false
		end
		if player.customhoming > 0 and not (P_PlayerInPain(player)) and not (player.powers[pw_carry]) and player.playerstate == PST_LIVE
			HandleHoming(player)
		else
			player.customhoming = 0
		end
		if player.homingacceltimer > 0
			player.homingacceltimer = $1-1
			player.accelstart = 170
			player.thrustfactor = 8
		elseif not player.footsweepattack
			player.accelstart = skins[player.mo.skin].accelstart
			player.thrustfactor = skins[player.mo.skin].thrustfactor
		end
		if P_IsObjectOnGround(player.mo)
		or P_PlayerInPain(player)
			player.homingacceltimer = 0
		end
		
	/////////LIGHTDASH
		if not player.lightdashing
			player.lightdashing = 0
		end
		if player.lightdashing > 0
			player.lightdashing = $1-1
		end
		if not (player.wasjustlightdashing)
			player.wasjustlightdashing = false
		end
		if not (player.cmd.buttons & BT_CUSTOM2)
		and player.lightdashing == 0
			player.readytolightdash = false
		end
		if player.speed == 0
		and player.lightdashing > 0
			player.lightdashing = 0
		end
		if player.powers[pw_carry]
			player.lightdashing = 0
			player.readytolightdash = false
			player.wasjustlightdashing = false
		end
		if (player.cmd.buttons & BT_CUSTOM2)
		and player.boosting == false
		and not P_PlayerInPain(player)
		and P_CanPickupItem(player)
		and not (player.powers[pw_carry])
		and not (player.powers[pw_nocontrol])
		and player.lightdashdown == false
		and not (player.silv_grabbed)
		and not (player.powers[pw_shield] == SH_ATTRACT)
		and not (player.powers[pw_shield] == SH_THUNDERCOIN)
		and player.tricking == false
		and not (player.exiting)
		and not player.modernmenu.show
		and not player.nomovecounter
			if player.lightdashing == 0
			and player.abilitylock == false
				player.readytolightdash = true
			end
			player.lightdashdown = true
		end
		if not (player.cmd.buttons & BT_CUSTOM2) 
			player.lightdashdown = false
		end
		if player.lightdashing > 0
			player.lightdashcounter = $1+1
		else
			player.lightdashcounter = 0
		end
		if player.lightdashcounter > 5
		and player.lightdashing > 0
		or P_PlayerInPain(player)
			player.lightdashing = 0
		end
		if player.readytolightdash == true
		or player.lightdashing > 0
			player.active_supertrans = false
			player.can_super = false
			player.superanim = 0
			player.readytolightdash = false
			--A_FindTarget (player.mo, MT_RING, 0)
			--A_FindTarget (player.mo, MT_COIN, 0)
			player.mo.target = Lightdashable(player)
			if player.mo.target
				S_StopSoundByID(player.mo, sfx_supjun)
				if player.mo.target.type == MT_RING
				or player.mo.target.type == MT_COIN
				or player.mo.target.type == MT_BLUESPHERE
				or player.mo.target.type == MT_FLINGRING
				or player.mo.target.type == MT_FLINGCOIN
					local targdist = FixedMul(300*FRACUNIT, player.mo.scale)
					if (P_AproxDistance(P_AproxDistance(player.mo.x-player.mo.target.x, player.mo.y-player.mo.target.y), player.mo.z-player.mo.target.z) < targdist)
						if player.mo.state ~= S_PLAY_LDSH
						and player.mo.state ~= S_PLAY_LDSH2
							player.mo.state = S_PLAY_LDSH
						end
						local ghost = P_SpawnGhostMobj(player.mo)
						ghost.tics = 3
						ghost.colorized = true
						ghost.blendmode = AST_ADD
						A_HomingChase(player.mo, 80*FRACUNIT)
						player.airboost = false
						player.airboostheld = false
						local fast = P_SpawnMobjFromMobj(player.mo, (P_RandomRange(-24,24) * player.mo.scale), (P_RandomRange(-24,24) * player.mo.scale), (player.mo.height/2) + (P_RandomRange(-24,24) * player.mo.scale), MT_SPEEDLINE)
						fast.angle = R_PointToAngle2(player.mo.x, player.mo.y, (player.mo.x+player.mo.momx), (player.mo.y+player.mo.momy))
						fast.target = player.mo
						if fast.target.player == displayplayer
							local chasecam = CV_FindVar("chasecam")
							if (chasecam.value == 1)
								fast.flags2 = $ & ~MF2_DONTDRAW
							elseif (chasecam.value == 0)
								fast.flags2 = $ | MF2_DONTDRAW
							end
						end
						if (player.powers[pw_shield] == SH_ELEMENTAL)
						and not (player.mo.eflags & MFE_UNDERWATER)
						and player.powers[pw_super] == 0
							fast.color = SKINCOLOR_ORANGE
						elseif (player.powers[pw_shield] == SH_FLAMEAURA or player.firesonic)
						and player.powers[pw_super] == 0
							fast.color = SKINCOLOR_KETCHUP
						elseif (player.powers[pw_super])
						or player.mysticsuper
							fast.color = FindMyColor(player, SKINCOLOR_GOLDENROD)
						else
							fast.color = FindMyColor(player, SKINCOLOR_SUPER_SUNFLOWER3, 1, "boost1")
						end
						
						fast.frame = $|FF_TRANS20
						local colors = {SKINCOLOR_CYAN, SKINCOLOR_MAGENTA, SKINCOLOR_YELLOW}
						for i = 1,2
							local boostsparkle = P_SpawnMobjFromMobj(player.mo,
							P_RandomRange(-10, 10)*FRACUNIT,
							P_RandomRange(-10, 10)*FRACUNIT,
							P_RandomRange(10, 50)*FRACUNIT,
							MT_BOOSTSPARKLE)
							boostsparkle.color = colors[leveltime % 3  + 1]
							boostsparkle.scale = player.mo.scale/2
							boostsparkle.fuse = 6
							boostsparkle.colorized = true
						end
					end
				end
			else
				--player.lightdashing = 0
			end
				
			if player.mo.state >= S_PLAY_LDSH and player.mo.state <= S_PLAY_LDSH2
				if player.wasjustlightdashing == false
					player.wasjustlightdashing = true
					S_IncrementModernChain(player.mo, 1, 40)
					if not (player.mo.eflags & MFE_UNDERWATER)
						S_StartSound(player.mo, sfx_lsd)
					else
						S_StartSound(player.mo, sfx_lsdw)
					end
					if player.modernmenu.contents[6][1].value == 1 -- Voices
						if player.modernmenu.contents[6][2].value == 0
							PlayModernSound(player, 6)
						elseif player.modernmenu.contents[6][2].value == 1
							PlayModernSound(player, 18)
						elseif player.modernmenu.contents[6][2].value == 2
							PlayModernSound(player, 12)	
						elseif player.modernmenu.contents[6][2].value == 3
							PlayModernSound(player, 24)
						elseif player.modernmenu.contents[6][2].value == 4
							PlayModernSound(player, 25)	
						elseif player.modernmenu.contents[6][2].value == 5
							PlayModernSound(player, 26)
						end
					end
				end
				player.lightdashing = 5
				player.pflags = $ & ~PF_JUMPED
				if player.mo.target and player.mo.target.valid
					if not (player.cmd.buttons & BT_CUSTOM2)
						player.mo.angle = R_PointToAngle2(player.mo.x, player.mo.y, player.mo.target.x, player.mo.target.y)
					end	
					player.drawangle = R_PointToAngle2(player.mo.x, player.mo.y, player.mo.target.x, player.mo.target.y)
				end
			end
		end
		if player.lightdashing == 0
		and player.wasjustlightdashing == true
			player.walljumpmomercy = 25 
			if player.mo.momz*P_MobjFlip(player.mo) > 0
				player.mo.momz = $1/3
				player.mo.state = S_PLAY_SPRING
			else
				player.mo.state = S_PLAY_FALL
			end
			player.trickable = true
			player.mo.momx = $/2
			player.mo.momy = $/2
			player.pflags = $ & ~PF_JUMPED
			player.wasjustlightdashing = false
		end
	/////////STOMP
		if not (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
			player.stompdown = false
		end
		if player.stomptimer > 0 
			player.stomptimer = $1-1
		end
		if P_IsObjectOnGround(player.mo)
		and (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
			player.stompdown = true
		end
		if player.powers[pw_carry]
			player.stompdown = true
			player.jumptimer = 4
		end
		if player.playerstate == PST_DEAD
			player.stomping = false
			player.crouching = false
		end
		if player.springlocktimer > 0
			player.springlocktimer = $1-1
		end
		if player.traillag
			player.traillag = $-1
		end
		if player.solidplayer 
			if player.solidplayer > 1
				player.mo.flags = $|MF_PUSHABLE
			elseif player.solidplayer == 1
				player.mo.flags = $ & ~MF_PUSHABLE
			end
			player.solidplayer = $-1
		end
		if player.SolTransforming
			player.stomping = false
			P_SetObjectMomZ(player.mo, 0)
		end
		if (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
        and (P_IsObjectOnGround(player.mo) == false)
		and not (player.stomping == true) 
		and player.stompdown == false
		and not (player.powers[pw_carry])
		and player.customhoming == 0
		and player.powers[pw_nocontrol] == 0
		and not (P_PlayerInPain(player))
		and player.playerstate == PST_LIVE
		and player.superboost == false
		and player.springlocktimer == 0
		and not (P_IsObjectInGoop(player.mo))
		and not (player.pflags & PF_STASIS)
		and not (player.pflags & PF_FULLSTASIS)
		and not (player.silv_grabbed) //Breaks with Silver otherwise
		and player.tricking == false
		and player.lightdashing == 0
		and player.modernwallslide == 0
		and not (player.mo.modernusedown and player.mo.modernusedown > 3)
		--and not player.dropdashing
		and not player.SolTransforming
		and not player.nomovecounter --fix for QTE script
			if player.cmd.buttons & BT_JUMP
			and not player.dropdashing
			and player.modernmenu.contents[2][9].value == 2
				S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_mspdsw or sfx_mspdsh)
				player.dropdashing = true
			end
			player.stomptimer = 8
			P_SetObjectMomZ(player.mo, -35*FU, true)
			player.stompdown = true
			player.pflags = $|PF_JUMPED
			if not (player.dropdashing)
				player.mo.state = S_PLAY_STOMP
			end
			if not (player.mo.eflags & MFE_UNDERWATER)
				S_StartSound(player.mo, sfx_stmps)
			else
				S_StartSound(player.mo, sfx_stmpsw)
			end
			if player.modernmenu.contents[6][1].value == 1 -- Voices
				if player.modernmenu.contents[6][2].value == 0
					PlayModernSound(player, 3)
				elseif player.modernmenu.contents[6][2].value == 1
					PlayModernSound(player, 15)
				elseif player.modernmenu.contents[6][2].value == 2
					PlayModernSound(player, 9)	
				elseif player.modernmenu.contents[6][2].value == 3 
					PlayModernSound(player, 21)	
				elseif player.modernmenu.contents[6][2].value == 4
					PlayModernSound(player, 25)	
				elseif player.modernmenu.contents[6][2].value == 5
					PlayModernSound(player, 26)
				end
			end
			player.stomping = true
			player.airkick = 0
		end
		if ((P_IsObjectInGoop(player.mo))
		or player.powers[pw_carry]
		or player.customhoming > 0
		or player.powers[pw_nocontrol] 
		or P_PlayerInPain(player)
		or (player.pflags & (PF_STASIS|PF_FULLSTASIS))
		or player.mo.momz*P_MobjFlip(player.mo) > 0)
		and not player.dropdashing
			if player.stomping ~= false
			and player.isspringflipped == false
				player.stomping = false
				player.jumptimer = 5
				player.traillag = 15
				if player.mo.state == S_PLAY_STOMP
					player.mo.state = S_PLAY_FALL
				end
				player.pflags = $ & ~PF_THOKKED
				if not (P_IsObjectOnGround(player.mo))
				and not (P_PlayerInPain(player))
				and player.paintimer == 0
					player.pflags = $|PF_JUMPED
				end
			end
		end
		if player.prevmomz
			--print(abs(player.prevmomz/FU))
		end
		if player.stomping == true 
		and not (player.powers[pw_carry])
		and not (player.powers[pw_nocontrol])
		and not (P_PlayerInPain(player))
		and player.playerstate == PST_LIVE
			player.boosting = false
			player.superboost = false
		--and not (player.mo.state == S_PLAY_SPRING)
			if (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
			and not player.dropdashing
			and not P_IsObjectOnGround(player.mo)
				if not player.stompdown
					S_StartSound(player.mo, player.mo.eflags & MFE_UNDERWATER and sfx_mspdsw or sfx_mspdsh)
					player.dropdashing = true
					player.stompdown = true
				end
			end
			if player.firesonic
				FireSonicFireSpawn(player)
			end
			if player.mo.state != S_PLAY_STOMP
			and not player.dropdashing
				player.mo.state = S_PLAY_STOMP
			end
			if not (player.powers[pw_super])
				player.abilitylock = true
			end
			player.doublejumped = false
			player.pflags = $ & ~PF_THOKKED
			if player.speed > FU*player.mo.scale
			and (leveltime % 2 == 0)
				player.mo.momy = $*5/6
				player.mo.momx = $*5/6
			elseif player.speed < FRACUNIT
				P_InstaThrust(player.mo, player.mo.angle, 0)
			end
			player.prevmomz = player.mo.momz
			local stompSpeed = player.mo.momz
			--player.mo.momz = stompSpeed
			P_SetObjectMomZ(player.mo, -FU*2, true)
			player.camerascale = abs(player.mo.momz/30)
			--TODO this shit
			local p = player --i hate spork
			
			--i had to rename the sprite from STMP to STMP to get this to work
			--what the fuck.
			local stompaura = P_SpawnMobjFromMobj(p.mo, 0,0,0, MT_STOMPAURA)
			stompaura.fuse = 1
			stompaura.frame = $ &(~FF_FRAMEMASK)|(leveltime%2)
			stompaura.scale = ($/player.stompScale)*4/3
			player.stompScale = max(1, $-1)
			
			if player.modernmenu.contents[5][4].value == 1
				stompaura.blendmode = AST_ADD
			end
				
			if player.powers[pw_super]
			or player.mysticsuper
				stompaura.color = FindMyColor(player, SKINCOLOR_GOLDENROD)
			elseif (player.powers[pw_shield] == SH_ELEMENTAL)
			and not (player.mo.eflags & MFE_UNDERWATER)
			and player.powers[pw_super] == 0
				stompaura.color = SKINCOLOR_ORANGE
			elseif (player.powers[pw_shield] == SH_FLAMEAURA or player.firesonic)
				stompaura.color = SKINCOLOR_KETCHUP
			else
				stompaura.color = FindMyColor(player, supercolor, 3, "stomp")
			end

			local coneTrail = P_SpawnMobjFromMobj(p.mo, 0,0,(stompSpeed/6)*(leveltime%3), MT_STOMPAURA)
			coneTrail.frame = $ &(~FF_FRAMEMASK)|C
			coneTrail.tics = 4
			coneTrail.destscale = $*3
			if player.modernmenu.contents[5][4].value == 1
				coneTrail.blendmode = AST_ADD
			end
			coneTrail.color = stompaura.color
			coneTrail.momz = stompSpeed - (stompSpeed/3) + (stompSpeed/10)
			coneTrail.momx = player.mo.momx
			coneTrail.momy = player.mo.momy
			coneTrail.target = p.mo
			coneTrail.dispoffset = 3
			player.powers[pw_strong] = 513
		else
			player.stompScale = 3
			player.stomping = false
		end
		if player.initiatestomptimer == true
			player.stompintoslidetimer = $1+1
		end
		if not (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
			player.stompintoslidetimer = 0
			player.initiatestomptimer = false
		end
		if P_IsObjectOnGround(player.mo)
		and player.stomping == true
			player.solidplayer = 5
			player.traillag = 15
			player.stompshake = 6
			if not (player.mo.eflags & MFE_UNDERWATER)
				if (player.powers[pw_shield] == SH_ELEMENTAL or player.powers[pw_shield] == SH_FLAMEAURA)
				or player.firesonic
					P_ElementalFire(player, true)
				end
				S_StartSound(player.mo, sfx_stmpg)
			else
				S_StartSound(player.mo, sfx_stmpgw)
			end
			local shockwave = P_SpawnMobjFromMobj(player.mo, 0, 0, 0, MT_MODERNSHOCKWAVE)
			shockwave.target = player.mo
			shockwave.color = FindMyColor(player, SKINCOLOR_SUPER_SUNFLOWER3, 3)
			if player.modernmenu.contents[5][4].value == 1
				shockwave.blendmode = AST_ADD
			end
			shockwave.renderflags = $ | RF_FLOORSPRITE
			shockwave.scale = player.mo.scale/2
			shockwave.destscale = player.mo.scale*2
			shockwave.scalespeed = FRACUNIT/100
			for i = 11,33
				if not (player.mo.eflags & MFE_VERTICALFLIP)
					local dust = P_SpawnMobj(player.mo.x, player.mo.y, player.mo.z, MT_STOMPDUST)
					if player.modernmenu.contents[5][4].value == 1
						dust.blendmode = AST_ADD
					end
					dust.target = player.mo
					dust.scale = player.mo.scale/4
					if player.mo.eflags & MFE_VERTICALFLIP then
						dust.flags2 = $|MF2_OBJECTFLIP // flip gravity!
					end
					local an = i*ANG30
					local speed = FixedMul(dust.info.speed/FRACUNIT, player.mo.scale)
					dust.momx = speed/6*cos(an)
					dust.momy = speed/6*sin(an)
					dust.momz = 0
					if player.powers[pw_super]
					or player.mysticsuper
						dust.color = FindMyColor(player, SKINCOLOR_SUPERGOLD3)
					elseif (player.powers[pw_shield] == SH_ELEMENTAL)
					and not (player.mo.eflags & MFE_UNDERWATER)
					and player.powers[pw_super] == 0
						dust.color = SKINCOLOR_ORANGE
					elseif player.powers[pw_shield] == SH_FLAMEAURA
					or player.firesonic
						dust.color = SKINCOLOR_KETCHUP
					else
						dust.color = FindMyColor(player, supercolor, 3, "stomp")
					end
				else
					local offset = FixedMul(23*FRACUNIT, P_GravAndScale(player.mo))
					local dust = P_SpawnMobj(player.mo.x, player.mo.y, player.mo.z-offset, MT_STOMPDUST)
					if player.modernmenu.contents[5][4].value == 1
						dust.blendmode = AST_ADD
					end
					dust.target = player.mo
					dust.scale = player.mo.scale/4
					if player.mo.eflags & MFE_VERTICALFLIP then
						dust.flags2 = $|MF2_OBJECTFLIP // flip gravity!
					end
					local an = i*ANG30
					local speed = FixedMul(dust.info.speed/FRACUNIT, player.mo.scale)
					dust.momx = speed/6*cos(an)
					dust.momy = speed/6*sin(an)
					dust.momz = 0
					if player.powers[pw_super]
					or player.mysticsuper
						dust.color = FindMyColor(player, SKINCOLOR_GOLDENROD)
					elseif (player.powers[pw_shield] == SH_ELEMENTAL)
					and not (player.mo.eflags & MFE_UNDERWATER)
					and player.powers[pw_super] == 0
						dust.color = SKINCOLOR_ORANGE
					elseif player.powers[pw_shield] == SH_FLAMEAURA
					or player.firesonic
						dust.color = SKINCOLOR_KETCHUP
					else
						dust.color = FindMyColor(player, supercolor, 3, "stomp")
					end
				end
			end
			if (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
			and (player.speed > player.mo.scale*15)
			--and player.stompintoslidetimer > 2
			and (((player.cmd.forwardmove ~= 0 or player.cmd.sidemove ~= 0) and not (player.mo.flags2 & MF2_TWOD)) or (player.cmd.sidemove ~= 0 and (player.mo.flags2 & MF2_TWOD)))
			and not (player.pflags & PF_SPINNING) 
			and not player.dropdashing
				player.slidecanceltimer = 15
				player.sliding = 1
				--player.mo.state = S_PLAY_SLIDE
				player.usedown = true
				S_StartSound(player.mo, sfx_sldst)
				if player.modernmenu.contents[6][1].value == 1 -- Voices
					if player.modernmenu.contents[6][2].value == 0
						PlayModernSound(player, 5)
					elseif player.modernmenu.contents[6][2].value == 1
						PlayModernSound(player, 17)
					elseif player.modernmenu.contents[6][2].value == 2
						PlayModernSound(player, 11)
					elseif player.modernmenu.contents[6][2].value == 3
						PlayModernSound(player, 23)
					elseif player.modernmenu.contents[6][2].value == 4
						PlayModernSound(player, 25)	
					elseif player.modernmenu.contents[6][2].value == 5
						PlayModernSound(player, 26)
					end
				end
			else
				if not (player.powers[pw_carry])
				and not (player.pflags & PF_SLIDING)
				and not (player.pflags & PF_SPINNING)
				and not (player.pflags & BT_TOSSFLAG)
					if player.powers[pw_shield] == SH_BUBBLEWRAP
						P_DoBubbleBounce(player)
						player.pflags = $|PF_JUMPED
						player.pflags = $&~PF_THOKKED
						player.justjumped = true
						player.jumptimer = 4
						player.mo.state = S_PLAY_JUMP
					else
						P_InstaThrust(player.mo, player.mo.angle, 0)
						if not (player.mo.state == S_PLAY_CROUCH)
						and not (player.mo.state >= S_PLAY_TAUNT1 and player.mo.state <= S_PLAY_TAUNT4)
						and not (player.mo.state >= S_PLAY_BREAKDANCE1 and player.mo.state <= S_PLAY_BREAKDANCE4)
							player.mo.state = S_PLAY_CROUCH
						end
						if (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
						and not (player.mo.state >= S_PLAY_TAUNT1 and player.mo.state <= S_PLAY_TAUNT4)
						and not (player.mo.state >= S_PLAY_BREAKDANCE1 and player.mo.state <= S_PLAY_BREAKDANCE4)
						and not (player.pflags & BT_TOSSFLAG)
							player.crouching = true
							player.crouchcanceltimer = 12
							player.usedown = true
							player.mo.reactiontime = 1
						end
					end
				end
			end
			player.stomping = false
		end
		if player.crouchcanceltimer > 0 
			player.crouchcanceltimer = $1-1
		end
		if player.stompshake > 0
			player.jt = -4
		end
		//////////SLIDE//CRAWL//FOOTSWEEP
		//Crawl
		if player.crawling
			if player.speed > 5*FRACUNIT 
			and player.mo.tics > 2
				player.mo.tics = 2
			end
			player.normalspeed = 10*FU
			player.thrustfactor = 15
			player.height = P_GetPlayerSpinHeight(player)
			if not P_IsObjectOnGround(player.mo)
			and not (player.pflags & PF_JUMPED)
				player.crawling = false
				player.mo.state = S_PLAY_FALL
			end
		end
		if P_IsObjectOnGround(player.mo)
		and player.speed < FixedMul(1*FRACUNIT, player.mo.scale)
		and ((((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) or((player.mo.ceilingz - player.mo.floorz) < skins[player.mo.skin].height + FRACUNIT)) -- Actionswap
		and player.playerstate == PST_LIVE
		//and not (player.pflags & PF_STARTDASH)
		and not (player.powers[pw_carry])
		and not (player.pflags & PF_SLIDING)
		and not (player.pflags & PF_STARTDASH)
		and not (player.pflags & PF_STASIS)
		and player.customhoming == 0
		and not player.mo.railgrinding 
		and not (player.mo.state >= S_PLAY_TAUNT1 and player.mo.state <= S_PLAY_TAUNT4)
		and not (player.mo.state >= S_PLAY_BREAKDANCE1 and player.mo.state <= S_PLAY_BREAKDANCE4)
		and not (player.exiting)
		and not (player.pflags & PF_SPINNING)
		and not (player.pflags & PF_STARTDASH)
		and not (player.pflags & BT_TOSSFLAG)
			if not (player.mo.state == S_PLAY_CROUCH)
				//P_InstaThrust(player.mo, player.mo.angle, 0)
				player.mo.state = S_PLAY_CROUCH
				
			end
			if player.crouching == false
				player.crouching = true
			end
			if (((player.cmd.forwardmove ~=  0 or player.cmd.sidemove ~= 0) and twod == false) or (player.cmd.sidemove ~= 0 and twod == true))
			and player.slidecanceltimer == 0
			and player.crouchcanceltimer == 0
			--and not (twodlevel)
			--and not (player.mo.flags2 & MF2_TWOD) 
			and not (player.powers[pw_carry])
				player.mo.state = S_PLAY_CRAWL
				player.crawling = true
			end
		elseif (player.crouching == true or player.crawling)
		and not (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
		and player.crouchcanceltimer == 0
		and player.playerstate == PST_LIVE
		and ((player.mo.ceilingz - player.mo.floorz) > skins[player.mo.skin].height + FRACUNIT)
		and player.sliding == 0
		and not (player.pflags & PF_STARTDASH)
		and not (player.pflags & PF_SPINNING)
			player.crouching = false
			player.crawling = false
			if P_IsObjectOnGround(player.mo)
				if player.speed > FU
					player.mo.state = S_PLAY_WALK
				else
					player.mo.state = S_PLAY_STND
				end
			end
		end
		if player.mo.state ~= S_PLAY_CRAWL
			player.crawling = false
		end
		if not (P_IsObjectOnGround(player.mo))
		or P_PlayerInPain(player)
		or player.speed > 0
			player.crouching = false
		end
		if player.pflags & PF_SLIDING
			player.sliding = 0
		end
		if player.crouching == true
		and ((player.mo.ceilingz - player.mo.floorz) < skins[player.mo.skin].height + FRACUNIT)
		and not (player.pflags & PF_SPINNING)
		and not (player.pflags & PF_STARTDASH)
			if not (player.mo.state == S_PLAY_CROUCH)
				player.mo.state = S_PLAY_CROUCH
			end
		end
		if player.speed < FixedMul(FRACUNIT, player.mo.scale)
		and ((player.mo.ceilingz - player.mo.floorz) < skins[player.mo.skin].height + FRACUNIT)
		and player.crouching == false
		and not (player.pflags & BT_TOSSFLAG)
			player.crouching = true
		end
		if player.mo.state == S_PLAY_CROUCH
		or player.footsweepattack
			player.panim = PA_IDLE
			if not (P_IsObjectOnGround(player.mo))
				player.mo.state = S_PLAY_WALK
			end
			
			player.height = P_GetPlayerSpinHeight(player)
		end
		if player.stompshake > 0
		or player.boostshake > 0
			player.stompshake = $1-1
			if client and client.valid and client.mo
				local dist = P_AproxDistance(P_AproxDistance((client.mo.x - player.mo.x)/FRACUNIT, (client.mo.y - player.mo.y)/FRACUNIT), (client.mo.z - player.mo.z)/FRACUNIT)
				if dist >= 0 and dist < (player.powers[pw_super] and 1024 or 512)*player.mo.scale/FRACUNIT
					if (player.modernmenu.contents[2][4].value == 1 and player == displayplayer) -- Quakes
					
						P_StartQuake(50*FRACUNIT, 1)
					end
				end
			end
		end
		//footsweep
		if not (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
			player.footsweepheld = false
		end
		if player.footsweeptap 
			player.footsweeptap = $-1
		end
		if player.footsweepattack 
			player.footsweepattack = $-1
		else
			player.footsweepangle = player.drawangle
		end
		if (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
		and not (player.powers[pw_carry])
		and not (player.exiting)
		and not (player.pflags & PF_STASIS)
		and not P_PlayerInPain(player)
		and player.playerstate == PST_LIVE
		and P_IsObjectOnGround(player.mo)
		--and (player.sliding == 0)
		--and player.usedown == false
		and not (player.silv_grabbed)
		and not (player.pflags & PF_SLIDING)
		and not player.mo.railgrinding
		and not (player.powers[pw_carry])
		and not player.manualdrifting
		and not player.footsweepattack
		and not (player.pflags & PF_SPINNING)
			if not player.footsweeptap
			and not player.footsweepattack
				if player.footsweepheld == false
					player.footsweeptap = 15
					player.footsweepheld = true
				end
			elseif player.footsweepheld == false
				player.footsweepattack = 25
				S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER and sfx_fotspu or sfx_fotspl))
				if player.modernmenu.contents[6][1].value == 1 -- Voices
					if player.modernmenu.contents[6][2].value == 0
						PlayModernSound(player, 31)
					elseif player.modernmenu.contents[6][2].value == 1
						PlayModernSound(player, 32)
					elseif player.modernmenu.contents[6][2].value == 2
						PlayModernSound(player, 33)
					elseif player.modernmenu.contents[6][2].value == 3
						PlayModernSound(player, 34)
					elseif player.modernmenu.contents[6][2].value == 4
						PlayModernSound(player, 25)
					elseif player.modernmenu.contents[6][2].value == 5
						PlayModernSound(player, 26)
					end
				end
				if player.footsweep == nil
					player.footsweep = P_SpawnMobjFromMobj(player.mo, 0,0,0, MT_FOOTSWEEP) 
					player.footsweep.target = player.mo
					player.footsweep.scale = player.mo.scale*6/7
					player.footsweep.state = S_FOOTSWEEP
					if player.modernmenu.contents[5][6].value == 1
						player.footsweep.blendmode = AST_ADD
					end
					player.footsweep.fuse = 25
					player.footsweep.renderflags = RF_FLOORSPRITE|RF_NOSPLATBILLBOARD
					if player.powers[pw_super] == 0
					and not (player.mysticsuper)
						if (player.powers[pw_shield] == SH_ELEMENTAL)
						and not (player.mo.eflags & MFE_UNDERWATER)
							player.footsweep.color = SKINCOLOR_ORANGE
						elseif player.powers[pw_shield] == SH_FLAMEAURA
						or player.firesonic
							player.footsweep.color = SKINCOLOR_KETCHUP
						else
							player.footsweep.color = FindMyColor(player, supercolor, 7, "slide")
						end
					else
						player.footsweep.color = FindMyColor(player, SKINCOLOR_GOLDENROD)
					end
				end
			end
		end
		if player.footsweep
		and player.footsweep.valid
			player.footsweep.angle = player.footsweepangle+ANGLE_180
			if leveltime & 2
				local ghost = P_SpawnGhostMobj(player.footsweep)
				ghost.target = player.mo
				ghost.footsweep = true
			end
			P_MoveOrigin(player.footsweep, player.mo.x, player.mo.y,player.mo.eflags & MFE_VERTICALFLIP and player.mo.z+player.mo.height or player.mo.z)
		end
		
		if not player.footsweepattack
			player.footsweep = nil
			player.footsweepghost = nil
		end
		if player.footsweepattack
			player.doubledamage = true
			player.footsweepangle = $+FixedAngle(23*FU)+FixedAngle(min(player.speed/10, 10*FU))
			player.drawangle = player.footsweepangle
			player.mo.state = S_PLAY_FOOTSWEEP
			player.pflags = $|PF_JUMPSTASIS 
			player.mo.friction = FU
			player.thrustfactor = 1
			player.sliding = 0
			player.crawling = false
			player.slidecanceltimer = 0
			player.powers[pw_strong] = 256
		end
		if not player.footsweepattack
		and player.mo.state == S_PLAY_FOOTSWEEP
			player.mo.state = S_PLAY_WALK
		end
		--STOP SWEEPING BITCH
		if P_PlayerInPain(player)
		or player.powers[pw_carry]
		or player.playerstate ~= PST_LIVE
		or player.mo.state == S_PLAY_DEAD
		or player.pflags & PF_SLIDING
		--or not (P_IsObjectOnGround(player.mo))
			player.footsweepattack = 0
			
		end
		//slide
		if not (player.slidecanceltimer)
			player.slidecanceltimer = 0
		elseif player.slidecanceltimer > 0
			player.slidecanceltimer = $1-1
		end
		if P_PlayerInPain(player)
			player.sliding = 0
		end
		if not (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
			player.usedown = false
		end
		
		if (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
		and not (player.powers[pw_carry])
		and not (player.exiting)
		and not (player.pflags & PF_STASIS)
		and not P_PlayerInPain(player)
		and player.playerstate == PST_LIVE
		and player.speed > FixedMul(FRACUNIT, player.mo.scale)
		and P_IsObjectOnGround(player.mo)
		and (player.sliding == 0)
			if player.usedown == false
			or (s.eflags & MFE_JUSTHITFLOOR) and (p.panim <= PA_DASH) and (p.speed > 24*s.scale) and not (p.pflags & (PF_SPINNING|PF_STARTDASH))
				if not (player.silv_grabbed)
				and not (player.pflags & PF_SLIDING)
				and not player.mo.railgrinding
				and not (player.powers[pw_carry])
				and (player.cmd.forwardmove ~= 0 or player.cmd.sidemove ~= 0)
				and not player.manualdrifting
				and not player.crawling
				and not player.footsweepattack
				and not (player.pflags & PF_SPINNING) 
					player.slidecanceltimer = 13
					player.usedown = true
					if player.mo.state != S_PLAY_SLIDE
						player.mo.state = S_PLAY_SLIDE
					end
					player.boostslidegraceperiod = 25
					player.sliding = 1
					S_StartSound(player.mo, sfx_sldst)
					if player.modernmenu.contents[6][1].value == 1 -- Voices
						if player.modernmenu.contents[6][2].value == 0
							PlayModernSound(player, 5)
						elseif player.modernmenu.contents[6][2].value == 1
							PlayModernSound(player, 17)
						elseif player.modernmenu.contents[6][2].value == 2
							PlayModernSound(player, 11)	
						elseif player.modernmenu.contents[6][2].value == 3
							PlayModernSound(player, 23)	
						elseif player.modernmenu.contents[6][2].value == 4
							PlayModernSound(player, 25)
						elseif player.modernmenu.contents[6][2].value == 5
							PlayModernSound(player, 26)
						end
					end
					if player.speed < FixedMul(15*FRACUNIT, player.mo.scale)
						P_InstaThrust(player.mo, player.drawangle, FixedMul(15*FRACUNIT, player.mo.scale))
					end
				end
			end
		end
		if player.sliding == 1
		and player.speed == 0
		and player.slidecanceltimer == 0
		and player.playerstate == PST_LIVE
		and not (player.powers[pw_carry])
			if P_IsObjectOnGround(player.mo)
			and player.mo.state == S_PLAY_STND
				player.sliding = 0
				player.slidecanceltimer = 0
			end
			if ((player.mo.ceilingz - player.mo.floorz) > skins[player.mo.skin].height + FRACUNIT) 
				player.sliding = 0
				player.slidecanceltimer = 0
			elseif ((player.mo.ceilingz - player.mo.floorz) < skins[player.mo.skin].height + FRACUNIT)		
				player.pflags = $|MF_SLIDEME
				P_InstaThrust(player.mo, player.mo.angle, FixedMul(10*FRACUNIT, player.mo.scale))
				if player.mo.state != S_PLAY_SLIDE
					player.mo.state = S_PLAY_SLIDE
				end
				player.height = P_GetPlayerSpinHeight(player)
			end
		end
		if not (P_IsObjectOnGround(player.mo))
		and player.sliding == 1
		and player.mo.state ~= S_PLAY_SPRING
		and not (P_PlayerInPain(player))
		and player.playerstate == PST_LIVE
			player.sliding = 0
			player.slidecanceltimer = 0
			if player.pflags & PF_JUMPED
				player.mo.state = S_PLAY_HOP
			else
				player.mo.state = S_PLAY_FALL
			end
		end
		if player.pflags & PF_JUMPED
			player.pflags = $ & ~PF_SPINNING
		end
		if player.boostslidegraceperiod
			player.boostslidegraceperiod = $-1
		end
		if player.mo.state == S_PLAY_SLIDE
		and not (P_PlayerInPain(player))
		and player.playerstate == PST_LIVE
			player.panim = PA_DASH
			if (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
				--player.boostheld = true
			end
			if not player.boostslidegraceperiod
				player.boosting = false
			end
			player.airboost = false
			player.airboostheld = false
			player.superboost = false
			player.pflags = $|PF_STASIS
			if (player.powers[pw_shield] == SH_ELEMENTAL
			and player.firesonic)				
			and not (player.mo.eflags & MFE_UNDERWATER)
			and not (player.mo.eflags & MFE_TOUCHWATER)
			and (leveltime & 1)
			and player.speed > FixedMul(4*FRACUNIT, player.mo.scale)
				P_ElementalFire(player)
			end 
			player.slideregen = $1+1
			if player.mo.standingslope == nil
				player.mo.friction = FRACUNIT-1000
			elseif player.mo.standingslope ~= nil
				if (player.mo.z < player.prevz and not (player.mo.eflags & MFE_VERTICALFLIP))
				or (player.mo.z > player.prevz and (player.mo.eflags & MFE_VERTICALFLIP))
					player.mo.friction = 549*(29 * FRACUNIT/32)/500
					player.prevz = player.mo.z
				elseif (player.mo.z > player.prevz and not (player.mo.eflags & MFE_VERTICALFLIP))
				or (player.mo.z < player.prevz and (player.mo.eflags & MFE_VERTICALFLIP))
					player.prevz = player.mo.z
					player.mo.friction = FRACUNIT-1000
				elseif player.mo.z == player.prevz
					player.mo.friction = FRACUNIT-1000
				end
			end
			if not (S_SoundPlaying(player.mo, sfx_sldst))
			and not (S_SoundPlaying(player.mo, sfx_sldng))
				S_StartSound(player.mo, sfx_sldng)
			end
			local xr = P_ReturnThrustX(player.mo, R_PointToAngle2(player.mo.x, player.mo.y, player.mo.x+player.mo.momx, player.mo.y+player.mo.momy)- ANG30, 30*player.mo.scale)
			local yr = P_ReturnThrustY(player.mo, R_PointToAngle2(player.mo.x, player.mo.y, player.mo.x+player.mo.momx, player.mo.y+player.mo.momy) - ANG30, 30*player.mo.scale)
			local xl = P_ReturnThrustX(player.mo, R_PointToAngle2(player.mo.x, player.mo.y, player.mo.x+player.mo.momx, player.mo.y+player.mo.momy) + ANG30, 30*player.mo.scale)
			local yl = P_ReturnThrustY(player.mo, R_PointToAngle2(player.mo.x, player.mo.y, player.mo.x+player.mo.momx, player.mo.y+player.mo.momy) + ANG30, 30*player.mo.scale)
			local chasecam = CV_FindVar("chasecam")
			if not (player.slideright)
				player.slideright = P_SpawnMobjFromMobj(player.mo, xr, yr, 0, MT_SLIDEFX)
				player.slideright.angle = R_PointToAngle2(player.mo.x, player.mo.y, player.mo.x+player.mo.momx, player.mo.y+player.mo.momy)
				player.slideright.scale = player.mo.scale*4/3
				if player.modernmenu.contents[5][6].value == 1
					player.slideright.blendmode = AST_ADD 
				end
				if player.powers[pw_super] == 0
				and not (player.mysticsuper)
					if (player.powers[pw_shield] == SH_ELEMENTAL)
					and not (player.mo.eflags & MFE_UNDERWATER)
						player.slideright.color = SKINCOLOR_ORANGE
					elseif player.powers[pw_shield] == SH_FLAMEAURA
					or player.firesonic
						player.slideright.color = SKINCOLOR_KETCHUP
					else
						player.slideright.color = FindMyColor(player, supercolor, 7, "slide")
					end
				else
					player.slideright.color = FindMyColor(player, SKINCOLOR_GOLDENROD)
				end
				if not chasecam.value
					player.slideright.flags2 = $|MF2_DONTDRAW
				else
					player.slideright.flags2 = $|MF2_DONTDRAW
					player.slideright.flags2 = $ & ~MF2_DONTDRAW
				end
			elseif player.slideright and player.slideright.valid
				player.slideright.angle = R_PointToAngle2(player.mo.x, player.mo.y, player.mo.x+player.mo.momx, player.mo.y+player.mo.momy)
				player.slideright.scale = player.mo.scale*4/3
				if player.mo.eflags & MFE_VERTICALFLIP then
					player.slideright.flags2 = $|MF2_OBJECTFLIP // flip gravity!
					player.slideright.eflags= $|MFE_VERTICALFLIP
					P_MoveOrigin(player.slideright, player.mo.x + xr, player.mo.y + yr, player.mo.z+player.mo.height)
				else
					player.slideright.flags2 = $1&~MF2_OBJECTFLIP // flip gravity!
					player.slideright.eflags= $1&~MFE_VERTICALFLIP
					P_MoveOrigin(player.slideright, player.mo.x + xr, player.mo.y + yr, player.mo.z)
				end
				if player.modernmenu.contents[5][6].value == 1
					player.slideright.blendmode = AST_ADD 
				end
				if player.powers[pw_super] == 0
				and not (player.mysticsuper)
					if (player.powers[pw_shield] == SH_ELEMENTAL)
					and not (player.mo.eflags & MFE_UNDERWATER)
						player.slideright.color = SKINCOLOR_ORANGE
					elseif player.powers[pw_shield] == SH_FLAMEAURA
					or player.firesonic
						player.slideright.color = SKINCOLOR_KETCHUP
					else
						player.slideright.color = FindMyColor(player, supercolor, 7, "slide")
					end
				else
					player.slideright.color = FindMyColor(player, SKINCOLOR_GOLDENROD)
				end
				if not chasecam.value
					player.slideright.flags2 = $|MF2_DONTDRAW
				else
					player.slideright.flags2 = $|MF2_DONTDRAW
					player.slideright.flags2 = $ & ~MF2_DONTDRAW
				end
			end
			
			if not (player.slideleft)
				player.slideleft = P_SpawnMobjFromMobj(player.mo, xl, yl, 0, MT_SLIDEFX)
				player.slideleft.angle = R_PointToAngle2(player.mo.x, player.mo.y, player.mo.x+player.mo.momx, player.mo.y+player.mo.momy)
				player.slideleft.scale = player.mo.scale*4/3
				if player.modernmenu.contents[5][6].value == 1
					player.slideleft.blendmode = AST_ADD
				end
				if player.powers[pw_super] == 0
				and not (player.mysticsuper)
					if (player.powers[pw_shield] == SH_ELEMENTAL)
					and not (player.mo.eflags & MFE_UNDERWATER)
						player.slideleft.color = SKINCOLOR_ORANGE
					elseif player.powers[pw_shield] == SH_FLAMEAURA
					or player.firesonic
						player.slideleft.color = SKINCOLOR_KETCHUP
					else
						player.slideleft.color = FindMyColor(player, supercolor, 7, "slide")
					end
				else
					player.slideleft.color = FindMyColor(player, SKINCOLOR_GOLDENROD)
				end	
				if not chasecam.value
					player.slideleft.flags2 = $|MF2_DONTDRAW
				else
					player.slideleft.flags2 = $|MF2_DONTDRAW
					player.slideleft.flags2 = $ & ~MF2_DONTDRAW
				end
			elseif player.slideleft and player.slideleft.valid
				player.slideleft.angle = R_PointToAngle2(player.mo.x, player.mo.y, player.mo.x+player.mo.momx, player.mo.y+player.mo.momy)
				player.slideleft.scale = player.mo.scale*4/3
				if player.mo.eflags & MFE_VERTICALFLIP then
					player.slideleft.flags2 = $|MF2_OBJECTFLIP // flip gravity!
					player.slideleft.eflags= $|MFE_VERTICALFLIP
					P_MoveOrigin(player.slideleft, player.mo.x + xl, player.mo.y + yl, player.mo.z+player.mo.height)
				else
					player.slideleft.flags2 = $1&~MF2_OBJECTFLIP // flip gravity!
					player.slideleft.eflags= $1&~MFE_VERTICALFLIP
					P_MoveOrigin(player.slideleft, player.mo.x + xl, player.mo.y + yl, player.mo.z)
				end
				if player.modernmenu.contents[5][6].value == 1
					player.slideleft.blendmode = AST_ADD
				end
				if player.powers[pw_super] == 0
				and not (player.mysticsuper)
					if (player.powers[pw_shield] == SH_ELEMENTAL)
					and not (player.mo.eflags & MFE_UNDERWATER)
						player.slideleft.color = SKINCOLOR_ORANGE
					elseif player.powers[pw_shield] == SH_FLAMEAURA
					or player.firesonic
						player.slideleft.color = SKINCOLOR_KETCHUP
					else
						player.slideleft.color = FindMyColor(player, supercolor, 7, "slide")
					end
				else
					player.slideleft.color = FindMyColor(player, SKINCOLOR_GOLDENROD)
				end
				if not chasecam.value
					player.slideleft.flags2 = $|MF2_DONTDRAW
				else
					player.slideleft.flags2 = $|MF2_DONTDRAW
					player.slideleft.flags2 = $ & ~MF2_DONTDRAW
				end
			end
			for i=(leveltime%7)/2,(leveltime%7) do
				local particle = P_SpawnMobj(player.mo.x, player.mo.y,
				player.mo.z + ((player.mo.eflags & MFE_VERTICALFLIP)/MFE_VERTICALFLIP * (player.mo.height - mobjinfo[MT_SPINDUST].height)), MT_SPINDUST)
				if ((player.powers[pw_shield] == SH_ELEMENTAL or player.firesonic) and not (player.mo.eflags & MFE_TOUCHWATER or player.mo.eflags & MFE_UNDERWATER)) then
					particle.state = S_SPINDUST_FIRE1
					particle.bubble = false
				elseif (player.mo.eflags & MFE_TOUCHWATER or player.mo.eflags & MFE_UNDERWATER) then
					particle.state = S_SPINDUST_BUBBLE1
					particle.bubble = true
				else
					particle.state = S_SPINDUST1
					particle.bubble = false
				end
				particle.target = player.mo
				particle.eflags = $1 | (player.mo.eflags & MFE_VERTICALFLIP)
				particle.scale = player.mo.scale*2/3
				P_SetObjectMomZ(particle, player.speed/FRACUNIT*FRACUNIT/50+P_RandomByte()<<10, false)
				P_InstaThrust(particle, player.drawangle+(P_RandomRange(-ANG30/FRACUNIT, ANG30/FRACUNIT)*FRACUNIT), FixedMul(-player.speed/FRACUNIT*FRACUNIT/12-1*FRACUNIT-P_RandomByte()<<11, player.mo.scale))
				P_TryMove(particle, particle.x+particle.momx, particle.y+particle.momy, true)
			end
		else
			player.prevz = player.mo.z
			player.slideregen = 0
			if player.slideright and player.slideright.valid
				P_RemoveMobj(player.slideright)
				player.slideright = nil
			end
			if player.slideleft and player.slideleft.valid
				P_RemoveMobj(player.slideleft)
				player.slideleft = nil
			end
		end
		if player.sliding == 1
		and not (((player.cmd.buttons & BT_USE) and player.modernmenu.contents[2][2].value == 0) or ((player.cmd.buttons & BT_CUSTOM1) and player.modernmenu.contents[2][2].value == 1)) -- Actionswap
		and player.slidecanceltimer == 0
		and ((player.mo.ceilingz - player.mo.floorz) > skins[player.mo.skin].height + FRACUNIT)
		and player.playerstate == PST_LIVE
			player.sliding = 0
		end
		if (player.mo.state == S_PLAY_SPRING) 
		or P_PlayerInPain(player) then
			player.slidecanceltimer = 0
		end
		if (player.sliding == 1 or player.slidecanceltimer > 0)
		and player.playerstate == PST_LIVE
		and not (player.powers[pw_carry])
			if not (player.mo.state == S_PLAY_SPRING)
				player.drawangle = R_PointToAngle2(player.mo.x, player.mo.y, (player.mo.x+player.mo.momx), (player.mo.y+player.mo.momy))
				if player.mo.state != S_PLAY_SLIDE
					player.mo.state = S_PLAY_SLIDE
				end
				player.height = P_GetPlayerSpinHeight(player)
				player.panim = PA_DASH
			end	
		end
		if player.sliding == 0
		and player.mo.state ~= S_PLAY_CROUCH
		and not (player.crawling)
		and not player.footsweepattack
			if ((player.mo.ceilingz - player.mo.floorz) > skins[player.mo.skin].height + FRACUNIT)
				player.height = skins[player.mo.skin].height
			end
		end
	
	//////////SOUND
		if player.modernmenu.contents[6][4].value == 1 -- Footsteps
			local texture = GetGroundTexture(player.mo)
			if texture ~= nil
				player.groundtexture = texture
			end
			local underwatersound = water
			if P_IsObjectOnGround(player.mo)
			and not (player.mo.eflags & MFE_GOOWATER)
			and not (player.powers[pw_carry])
				if player.powers[pw_super] == 0
					if (player.panim == PA_RUN)
					or player.mo.state == S_PLAY_BOOSTRUN
					or player.mo.state == S_PLAY_FIRESONICBOOST
					or player.mo.state == S_PLAY_FIRESONICRUN
					or (player.mo.state >= S_PLAY_TAUNT1 and player.mo.state <= S_PLAY_TAUNT4)
						if player.mo.frame & FF_FRAMEMASK == 0
						or player.mo.frame & FF_FRAMEMASK == 3 
						or player.mo.frame & FF_FRAMEMASK == 6 
						or player.mo.frame & FF_FRAMEMASK == 9 
						or player.mo.frame & FF_FRAMEMASK == 12 
						or player.mo.frame & FF_FRAMEMASK == 15
							if player.runsound == 0
								if not (player.mo.eflags & MFE_UNDERWATER)
								and not (player.mo.eflags & MFE_TOUCHWATER)
									local material = ModernSonic_FlatSounds[player.groundtexture]
									if material == nil
										local sounds = SOUNDS_LIST["concrete"]["steps"]
										 S_StartSound(player.mo, sounds[P_RandomKey(#sounds) + 1])
										//CONS_Printf(player, texture)
									else
										  local sounds = SOUNDS_LIST[material]["steps"]
										  S_StartSound(player.mo, sounds[P_RandomKey(#sounds) + 1])
									end
									if FixedHypot(player.mo.momx, player.mo.momy) > FixedMul(40*FRACUNIT, player.mo.scale)
										local spark = P_SpawnMobjFromMobj(player.mo, FRACUNIT*P_RandomRange(-16,16), FRACUNIT*P_RandomRange(-16,16),
										0,MT_RUNNINGSPARK)
										spark.scale = player.mo.scale*6/5
										spark.angle = (leveltime % 3 == 0) and FixedAngle(FU) or FixedAngle(180*FU)
										spark.blendmode = AST_ADD
										if player.powers[pw_super] == 0
										and not (player.mysticsuper)
											if (player.powers[pw_shield] == SH_ELEMENTAL)
											and not (player.mo.eflags & MFE_UNDERWATER)
												spark.color = SKINCOLOR_ORANGE
											elseif player.powers[pw_shield] == SH_FLAMEAURA
											or player.firesonic
												spark.color = SKINCOLOR_KETCHUP
											elseif player.modernmenu.contents[8][1].value == 0
												spark.color = SKINCOLOR_SKY
											else
												spark.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 1)
											end
										else
											spark.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 1)
										end	
									elseif FixedHypot(player.mo.momx, player.mo.momy) > FixedMul(15*FRACUNIT, player.mo.scale)
										local dust = P_SpawnMobjFromMobj(player.mo, FRACUNIT*P_RandomRange(-16,16), FRACUNIT*P_RandomRange(-16,16),
										0,MT_FAKEDUST)
										if player.powers[pw_shield] == SH_ELEMENTAL
										or player.firesonic
											dust.state = S_FAKEFIRE1
										end
										dust.target = player.mo
										dust.scale = player.mo.scale
										dust.frame = $|FF_TRANS70
										dust.angle = (leveltime % 3 == 0) and FixedAngle(FU) or FixedAngle(180*FU)
									end
								else
									S_StartSound(player.mo, underwatersound[P_RandomKey(#underwatersound) + 1])
									for i = 1, 4
										local dust = P_SpawnMobjFromMobj(player.mo, FRACUNIT*P_RandomRange(-8,8), FRACUNIT*P_RandomRange(-8,8),
										0,MT_FAKEDUST)
										dust.state = S_FAKEBUBBLE1
										dust.target = player.mo
										dust.scale = player.mo.scale
										dust.frame = $|FF_TRANS70
										dust.angle = (leveltime % 3 == 0) and FixedAngle(FU) or FixedAngle(180*FU)
									end
								end
								player.runsound = 1
							end
						elseif not (player.mo.frame == 0 and player.mo.frame == 4)
							player.runsound = 0
						end
					elseif player.mo.state == S_PLAY_DRIFTLEFT
					or player.mo.state == S_PLAY_DRIFTRIGHT
						if player.mo.frame & FF_FRAMEMASK == 0
						or player.mo.frame & FF_FRAMEMASK == 3
							if player.runsound == 0
								if not (player.mo.eflags & MFE_UNDERWATER)
								and not (player.mo.eflags & MFE_TOUCHWATER)
									local material = ModernSonic_FlatSounds[player.groundtexture]
									if material == nil
										local sounds = SOUNDS_LIST["concrete"]["steps"]
										 S_StartSound(player.mo, sounds[P_RandomKey(#sounds) + 1])
										//CONS_Printf(player, texture)
									else
										  local sounds = SOUNDS_LIST[material]["steps"]
										  S_StartSound(player.mo, sounds[P_RandomKey(#sounds) + 1])
									end
									if FixedHypot(player.mo.momx, player.mo.momy) > FixedMul(40*FRACUNIT, player.mo.scale)
										local spark = P_SpawnMobjFromMobj(player.mo, FRACUNIT*P_RandomRange(-16,16), FRACUNIT*P_RandomRange(-16,16),
										0,MT_RUNNINGSPARK)
										spark.scale = player.mo.scale*6/5
										spark.angle = (leveltime % 3 == 0) and FixedAngle(FU) or FixedAngle(180*FU)
										spark.blendmode = AST_ADD
										if player.powers[pw_super] == 0
										and not (player.mysticsuper)
											if (player.powers[pw_shield] == SH_ELEMENTAL)
											and not (player.mo.eflags & MFE_UNDERWATER)
												spark.color = SKINCOLOR_ORANGE
											elseif player.powers[pw_shield] == SH_FLAMEAURA
											or player.firesonic
												spark.color = SKINCOLOR_KETCHUP
											elseif player.modernmenu.contents[8][1].value == 0
												spark.color = SKINCOLOR_SKY
											else
												spark.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 1)
											end
										else
											spark.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 1)
										end	
									elseif FixedHypot(player.mo.momx, player.mo.momy) > FixedMul(15*FRACUNIT, player.mo.scale)
										local dust = P_SpawnMobjFromMobj(player.mo, FRACUNIT*P_RandomRange(-16,16), FRACUNIT*P_RandomRange(-16,16),
										0,MT_FAKEDUST)
										if player.powers[pw_shield] == SH_ELEMENTAL
										or player.firesonic
											dust.state = S_FAKEFIRE1
										end
										dust.target = player.mo
										dust.scale = player.mo.scale
										dust.frame = $|FF_TRANS70
										dust.angle = (leveltime % 3 == 0) and FixedAngle(FU) or FixedAngle(180*FU)
									end
								else
									S_StartSound(player.mo, underwatersound[P_RandomKey(#underwatersound) + 1])
									for i = 1, 4
										local dust = P_SpawnMobjFromMobj(player.mo, FRACUNIT*P_RandomRange(-8,8), FRACUNIT*P_RandomRange(-8,8),
										0,MT_FAKEDUST)
										dust.state = S_FAKEBUBBLE1
										dust.target = player.mo
										dust.scale = player.mo.scale
										dust.frame = $|FF_TRANS70
										dust.angle = (leveltime % 3 == 0) and FixedAngle(FU) or FixedAngle(180*FU)
									end
								end
								player.runsound = 1
							end
						elseif not (player.mo.frame == 0 and player.mo.frame == 4)
							player.runsound = 0
						end
					end
				end
				if player.mo.state == S_PLAY_WALK
					if player.mo.frame == 0
					or player.mo.frame == 4
					or player.mo.frame & FF_FRAMEMASK == 0
					or player.mo.frame & FF_FRAMEMASK == 4
						if player.runsound == 0
							if not (player.mo.eflags & MFE_UNDERWATER)
							and not (player.mo.eflags & MFE_TOUCHWATER)
								local material = ModernSonic_FlatSounds[player.groundtexture]
								if material == nil
									local sounds = SOUNDS_LIST["concrete"]["steps"]
									  S_StartSound(player.mo, sounds[P_RandomKey(#sounds) + 1])
									//CONS_Printf(player, texture)
								else
									  local sounds = SOUNDS_LIST[material]["steps"]
									  S_StartSound(player.mo, sounds[P_RandomKey(#sounds) + 1])
								end
								if FixedHypot(player.mo.momx, player.mo.momy) > FixedMul(15*FRACUNIT, player.mo.scale)
									local dust = P_SpawnMobjFromMobj(player.mo, FRACUNIT*P_RandomRange(-16,16), FRACUNIT*P_RandomRange(-16,16),
									0,MT_FAKEDUST)
									if player.powers[pw_shield] == SH_ELEMENTAL
									or player.firesonic
										dust.state = S_FAKEFIRE1
									end
									dust.target = player.mo
									dust.scale = player.mo.scale
									dust.frame = $|FF_TRANS70
									dust.angle = (leveltime % 3 == 0) and FixedAngle(FU) or FixedAngle(180*FU)
								end
							else
								S_StartSound(player.mo, underwatersound[P_RandomKey(#underwatersound) + 1])
								for i = 1, 4
									local dust = P_SpawnMobjFromMobj(player.mo, FRACUNIT*P_RandomRange(-8,8), FRACUNIT*P_RandomRange(-8,8),
									0,MT_FAKEDUST)
									dust.state = S_FAKEBUBBLE1
									dust.target = player.mo
									dust.scale = player.mo.scale
									dust.frame = $|FF_TRANS70
									dust.angle = (leveltime % 3 == 0) and FixedAngle(FU) or FixedAngle(180*FU)
								end
							end
							player.runsound = 1
						end
					elseif not (player.mo.frame == 0 and player.mo.frame == 4)
						player.runsound = 0
					end
				end
				if player.mo.state == S_PLAY_WAIT
				and player.mo.sprite2 != SPR2_CNT1
					if (player.mo.waitTimer or 0) < 17 //use the timer to make it so the sound can't play when sonic first enters his idle. done to make things behave upon map load/spawn.
						player.mo.waitTimer = ($ or 0) + 1
					end
					if player.mo.waitTimer >= 17
						if player.mo.frame == 0
						or player.mo.frame == 2
						or player.mo.frame & FF_FRAMEMASK == 0
						or player.mo.frame & FF_FRAMEMASK == 2
							if player.runsound == 0
								if not (player.mo.eflags & MFE_UNDERWATER)
								and not (player.mo.eflags & MFE_TOUCHWATER)
									local material = ModernSonic_FlatSounds[player.groundtexture]
									if material == nil
										local sounds = SOUNDS_LIST["concrete"]["steps"]
										  S_StartSound(player.mo, sounds[P_RandomKey(#sounds) + 1])
										//CONS_Printf(player, texture)
									else
										  local sounds = SOUNDS_LIST[material]["steps"]
										  S_StartSound(player.mo, sounds[P_RandomKey(#sounds) + 1])
									end
								else
									S_StartSound(player.mo, underwatersound[P_RandomKey(#underwatersound) + 1])
								end
								player.runsound = 1
							end
						elseif not (player.mo.frame == 0 and player.mo.frame == 4)
							player.runsound = 0
						end
					end
				else
					player.mo.waitTimer = 0
				end
			end
		end
		if not (P_IsObjectOnGround(player.mo))
		and player.modernmenu.contents[6][4].value == 1 -- Footsteps
			player.wasnotonfloor = true
		elseif player.modernmenu.contents[6][4].value ~= 1 -- Footsteps
			player.wasnotonfloor = false
		end
		if player.wasnotonfloor == true
		and player.playerstate == PST_LIVE
		and not (player.mo.state == S_PLAY_FALL)
		and P_IsObjectOnGround(player.mo)
		and player.modernmenu.contents[6][4].value == 1 -- Footsteps
		and not (player.powers[pw_carry])
			player.wasnotonfloor = false
			if not (player.mo.eflags & MFE_UNDERWATER)
			and not (player.mo.eflags & MFE_TOUCHWATER)
				local material = ModernSonic_FlatSounds[player.groundtexture]
				if material == nil
					local sounds = SOUNDS_LIST["concrete"]["land"]
					 S_StartSound(player.mo, sounds[P_RandomKey(#sounds) + 1])
					//CONS_Printf(player, texture)
				else
					local sounds = SOUNDS_LIST[material]["land"]
					S_StartSound(player.mo, sounds[P_RandomKey(#sounds) + 1])
				end
			else
				S_StartSound(player.mo, sfx_wtrlnd)
			end
		end
		if player.skidtime == 16
			if player.modernmenu.contents[6][4].value == 1 -- Footsteps
				if not (player.mo.eflags & MFE_UNDERWATER)
				and not (player.mo.eflags & MFE_TOUCHWATER)
					local material = ModernSonic_FlatSounds[player.groundtexture]
					if material == nil
						local sounds = SOUNDS_LIST["concrete"]["skid"]
						S_StartSound(player.mo, sounds[P_RandomKey(#sounds) + 1])
						//CONS_Printf(player, texture)
					else
						local sounds = SOUNDS_LIST[material]["skid"]
						S_StartSound(player.mo, sounds[P_RandomKey(#sounds) + 1])
					end
				else
					S_StartSound(player.mo, sfx_wtrbrk)
				end
			else
				if player.modernmenu.contents[10][3].value == 2
					S_StartSound(player.mo, sfx_mtlbrk)
				end
			end
			if player.modernmenu.contents[10][3].value == 0
				S_StartSound(player.mo, sfx_ruskid)
			elseif player.modernmenu.contents[10][3].value == 1
				S_StartSound(player.mo, sfx_06skid)
			elseif player.modernmenu.contents[10][3].value == 3
				S_StartSound(player.mo, sfx_sbskid)
			end
		end
		
		//////RAIL GRINDING LANDING
		if (player.mo.eflags & MFE_JUSTHITFLOOR or player.speed > player.mo.scale)
		and P_IsObjectOnGround(player.mo) and player.mo.eflags & MFE_ONGROUND
		and not (player.pflags&PF_JUMPED) and player.playerstate == PST_LIVE
		and not (player.powers[pw_carry])
		
			local sec = R_PointInSubsector(player.mo.x+player.mo.momx,
			player.mo.y+player.mo.momy).sector
			local foffloor
			if (player.mo.eflags&MFE_VERTICALFLIP)
				for fof in sec.ffloors()
					if not (fof and fof.valid and fof.flags&FF_EXISTS) continue end
					if fof.b_slope and fof.b_slope.valid
						foffloor = P_GetZAt(fof.b_slope, player.mo.x, player.mo.y)
					else
						foffloor = fof.bottomheight
					end
					if abs(foffloor-player.mo.z+player.mo.height) <= player.mo.scale*8
						sec = fof.sector
						break
					end
				end
			else
				for fof in sec.ffloors()
					if not (fof and fof.valid and fof.flags&FF_EXISTS) continue end
					if fof.t_slope and fof.t_slope.valid
						foffloor = P_GetZAt(fof.t_slope, player.mo.x, player.mo.y)
					else
						foffloor = fof.topheight
					end
					if abs(foffloor-player.mo.z) <= player.mo.scale*8
						sec = fof.sector
						break
					end
				end
			end
			
			//P_GetMinecartSpecialLine
			local line = -1
			if sec and sec.valid
				if (sec.tag != 0)
					line = P_FindSpecialLineFromTag(16, sec.tag, -1)
				end

				// Also try for lines facing the sector itself, with tag 0.
				local i = 0 while sec.lines[i] != nil
					local li = sec.lines[i]
					if (li.tag == 0 and li.special == 16
					and li.frontsector == sec)
						line = 1//li - lines
					end
					i = $+1
				end
			end
			
			if line != -1
				local minecart = P_SpawnMobjFromMobj(player.mo,
				player.mo.momx, player.mo.momy, 0, MT_MINECART)
				if minecart and minecart.valid
					P_ResetPlayer(player)
					if player.speed >= player.mo.scale*10
						player.drawangle = R_PointToAngle2(0, 0, player.mo.momx, player.mo.momy)
						minecart.momx = player.mo.momx
						minecart.momy = player.mo.momy
					end
					player.mo.angle = player.drawangle
					minecart.angle = player.drawangle
					minecart.flags2 = $|MF2_DONTDRAW
					player.mo.tracer = minecart
					minecart.target = player.mo
					player.powers[pw_carry] = CR_MINECART
				end
			end
		end
		//////LOCKON
		if player.superboost == true
		or player.gotbonked
			player.rettarget = 0
			if (player.ret) and (player.ret.valid) then
				P_RemoveMobj(player.ret)
				player.ret = 0
			end
		end
		if player.mo.eflags & MFE_SPRUNG
			player.customhoming = 0
			player.footsweepattack = 0
		end
		if player.gotthismonitor
			local intable
			for i, m in ipairs(player.gotthismonitor)
				if m == ModernLockOn(player)
					intable = true
					break
				end
			end
		end
		if (player.modernmenu.contents[2][11].value == 1 -- Homing Attack
		or player.modernmenu.contents[2][11].value == 2)
		and not (player.powers[pw_carry] == CR_NIGHTSMODE)
		and not (player.gotflag)
		and player.superboost == false
		and not player.gensdash
			if not (player.exiting)
		--	and not (player.stomping)
			and not (P_IsObjectOnGround(player.mo))
			and player.modernwallslide == 0
			and player.tricking == false
			and not intable
			and not (player.supertrans)
				if player.pflags & PF_JUMPED
					if player.ret == nil
					or player.ret == 0
						local rettarget = ModernLockOn(player)
						if rettarget
						and (rettarget.type != MT_METALSONIC_BATTLE)
							local HomingAttackDetector = P_SpawnMissile(player.mo, rettarget, MT_HOMING_ATTACK_DETECTOR)
							if HomingAttackDetector
								HomingAttackDetector.target = player.mo
							end
						elseif rettarget
							player.rettarget = rettarget
						end
					end
				end
				//too far from the target
				local targdist = FixedMul(600*FRACUNIT*2, player.mo.scale)
				if (player.ret) and (player.ret.valid)
				and (player.customhoming == 0)
				and player.rettarget and player.rettarget.valid
					if (P_AproxDistance(P_AproxDistance(player.mo.x-player.rettarget.x, player.mo.y-player.rettarget.y),
					player.mo.z-player.rettarget.z) > targdist) then
						P_RemoveMobj(player.ret)
						player.ret = 0
						player.rettarget = 0
					end
				end
				//not facing the target
				if (player.ret) and (player.ret.valid)
				and (player.rettarget) and (player.rettarget.valid)
					local angdiff = R_PointToAngle2(player.mo.x, player.mo.y, player.rettarget.x, player.rettarget.y) - player.mo.angle
					if ((angdiff > (ANGLE_45+ANGLE_22h)) or (angdiff < (-ANGLE_45+-ANGLE_22h)))
					and (player.customhoming == 0)
						P_RemoveMobj(player.ret)
						player.ret = 0
						player.rettarget = 0
					end
				end
				//If orb target no longer exists, set the variable to nil
				if (player.rettarget)
					if not (player.rettarget.valid) then
					
						if (player.ret) and (player.ret.valid) then
							P_RemoveMobj(player.ret)
							player.ret = 0
							player.rettarget = 0
						end
					end
				end
				//If orb target no longer has health, set the variable to nil
				if (player.rettarget) and (player.rettarget.valid) then
					if (player.rettarget.health < 1) then
						player.rettarget = 0
						if (player.ret) and (player.ret.valid) then
							P_RemoveMobj(player.ret)
							player.ret = 0
						end
					end
				end
				//Stuff to do if there is currently a valid target
				if (player.rettarget) and (player.rettarget.valid) then
					//Add a target reticle if there is none
					local angdiff = R_PointToAngle2(player.mo.x, player.mo.y, player.rettarget.x, player.rettarget.y) - player.mo.angle
					if not (player.ret) 
					and (player.rettarget and player.rettarget.valid)
					and player.rettarget.type ~= MT_RING
					and player.rettarget.type ~= MT_SIGN 
					and player.rettarget.type ~= MT_TNTBARREL
					and player.rettarget.type ~= MT_BIGMINE
					and player.rettarget.type ~= MT_EGGSHIELD
					and player.rettarget.type ~= MT_FAKEMOBILE
					and not player.rettarget.flung
					and P_CheckSight(player.mo, player.rettarget) 
					and (player.rettarget.flags & MF_SHOOTABLE or player.rettarget.flags2 & MF2_INVERTAIMABLE or player.rettarget.flags & MF_SPRING or player.rettarget.type == MT_METALSONIC_BATTLE or player.rettarget.type == MT_NIGHTSBUMPER or player.rettarget.type == MT_PULLEYHANDLE)
					and (player.customhoming == 0)
					and ((angdiff < (ANGLE_45+ANGLE_22h)) and (angdiff > (-ANGLE_45+-ANGLE_22h)))
						if player.modernmenu.contents[10][8].value == 0
							S_StartSound(player.mo, sfx_lckon1, player)
						elseif player.modernmenu.contents[10][8].value == 1
							S_StartSound(player.mo, sfx_lckon2, player)
						elseif player.modernmenu.contents[10][8].value == 2
							S_StartSound(player.mo, sfx_lckon3, player)
						end
						player.ret = P_SpawnMobj(player.mo.x, player.mo.y, player.mo.z, MT_MODERNRETICLE)
						player.ret.tracer = player.mo
						player.ret.target = player.rettarget
						player.ret.scale = player.rettarget.scale*5
						player.ret.color = player.reticlecolor
					end
				end
				if (player.ret) 
				and player.ret.valid
				and player.rettarget
				and player.rettarget.valid
				and (player.customhoming == 0)
					if player.rettarget ~= ModernLockOn(player)
						player.rettarget = 0
						P_RemoveMobj(player.ret)
						player.ret = 0
					end
				end
				if player.ret and player.ret.valid
				and player.rettarget and player.rettarget.valid
					if player.ret.scale ~= player.rettarget.scale/3*2
						player.ret.destscale = player.rettarget.scale/3*2
					end
				else
					player.perfecthomingtimer = 0
					player.perfectCapable = false
				end
			elseif player.ret and player.ret.valid
			and player.customhoming == 0
				player.rettarget = 0
				P_RemoveMobj(player.ret)
				player.ret = 0
				player.perfecthomingtimer = 0
				player.perfectCapable = false
			end
			player.dontdisplaymarker = true
		end
		//////TRICKS
		if (player.trickable or player.tricking)
		and player.playerstate == PST_LIVE
			if not player.tricksound
				player.tricksound = P_SpawnMobjFromMobj(player.mo, 0,0,0, MT_OVERLAY)
				player.tricksound.target = player.mo
				player.tricksound.tics = -1
			elseif player.tricksound and player.tricksound.valid
				if not player.tricksound.soundplayed
					S_StartSound(player.tricksound, sfx_trkspk)
					player.tricksound.soundplayed = 1
				end
			end
			local j = P_RandomRange(0, 100) --60
			local r = 15
			local p = player
			if leveltime & 5 == 1
				local dust = P_SpawnMobjFromMobj(p.mo, P_ReturnThrustX(p.mo, (p.mo.angle)+FixedAngle(j*FRACUNIT), r*p.mo.scale), P_ReturnThrustY(p.mo, (p.mo.angle)+FixedAngle(j*FRACUNIT), r*p.mo.scale), p.mo.height/2, MT_BOOSTSPARKLE)
				dust.scale = p.mo.scale
				dust.color = player.mo.color
				dust.blendmode = AST_ADD
				dust.fuse = 15
				dust.destscale = 0
				dust.scalespeed = $/2

				local dust2 = P_SpawnMobjFromMobj(p.mo, P_ReturnThrustX(p.mo, (p.mo.angle)+FixedAngle(-j*FRACUNIT), r*p.mo.scale), P_ReturnThrustY(p.mo, (p.mo.angle)+FixedAngle(-j*FRACUNIT), r*p.mo.scale), p.mo.height/2, MT_BOOSTSPARKLE)
				dust2.scale = p.mo.scale
