								S_StartSound(player.mo, sfx_ctrck1)
							elseif player.colorstrickcount == 1
								S_StartSound(player.mo, sfx_ctrck2)
							elseif player.colorstrickcount == 2
								S_StartSound(player.mo, sfx_ctrck3)
