					tricksparklesring.color = SKINCOLOR_AETHER
					tricksparklesring.colorized = true
					player.pflags = $ & ~PF_JUMPED
					if player.modernmenu.contents[10][10].value == 0
						S_StartSound(player.mo, sfx_trickg)
