					P_SetObjectMomZ(player.mo, 0, false)
					P_InstaThrust(player.mo, player.mo.angle, (FixedHypot(player.mo.momx, player.mo.momy) < 70*player.mo.scale and 70*player.mo.scale) or player.speed+10*FU)
					player.mo.state = S_PLAY_AIRKICK
