						S_StartSound(player.mo, sfx_crowd1)
					elseif crowd == 2
						S_StartSound(player.mo, sfx_crowd2)
					elseif crowd == 3
						S_StartSound(player.mo, sfx_crowd3)
					elseif crowd == 4
						S_StartSound(player.mo, sfx_crowd4)
