						S_StartSound(player.mo, sfx_utrck2)
				elseif player.modernmenu.contents[10][10].value == 2
					S_StartSound(player.mo, sfx_chkbst)
				elseif player.modernmenu.contents[10][10].value == 4
					S_StartSound(player.mo, sfx_ftrck)
