				SpawnActionDust(player.mo, 1)
				--player.trickcooldown = 0
			end
		end
		if player.overlaytimer == nil
			player.overlaytimer = 0
		end
		if player.overlaytimer > 0
			player.overlaytimer = $-1
		end
		
		if P_IsObjectOnGround(player.mo)
		or player.doublejumped == true
		or player.customhoming > 0
		or player.stomping == true
			player.trickable = false
		end
		if player.rushmode == 0 
		or player.mysticsuper
		or player.powers[pw_carry] == CR_NIGHTSMODE
