						else
							player.overlay.flags2 = $ & ~MF2_DONTDRAW
						end
					else
						--player.overlay.blendmode = 	AST_TRANSLUCENT
						player.overlay.flags2 = $|MF2_DONTDRAW
					end
				else
					player.overlay.blendmode = 	AST_TRANSLUCENT
					player.overlay.colorized = player.mo.colorized
				end
			elseif player.overlay.valid
				player.overlay.skin = player.mo.skin
				player.overlay.state = player.mo.state
				player.overlay.tics = player.mo.tics
				player.overlay.anim_duration = player.mo.anim_duration
				player.overlay.angle = player.mo.angle
				player.overlay.sprite = SPR_PLAY
				player.overlay.sprite2 = player.mo.sprite2
				player.overlay.target = player.mo
				player.overlay.scale = player.mo.scale
				player.overlay.angle = player.drawangle
				player.overlay.rollangle = player.mo.rollangle
				player.overlay.spritexscale = player.mo.spritexscale
				player.overlay.spriteyscale = player.mo.spriteyscale
				player.overlay.spriteyoffset = player.mo.spriteyoffset
				player.overlay.eflags = player.mo.eflags
				player.overlay.flags2 = player.mo.flags2
				if player.modernmenu.contents[4][2].value == 1
					player.overlay.dispoffset = 3
				else
					player.overlay.dispoffset = 1
				end
				if player.modernmenu.contents[4][2].value == 1
					if player.modernmenu.contents[4][3].value == 1
						player.overlay.colorized = true
					end
					if player.overlaytimer > 2
					and player.modernmenu.contents[4][3].value == 1
						player.overlay.blendmode = 	AST_ADD
						if player.mo.flags2 & MF2_DONTDRAW
							player.overlay.flags2 = $|MF2_DONTDRAW
						else
							player.overlay.flags2 = $ & ~MF2_DONTDRAW
						end
					else
						player.overlay.flags2 = $|MF2_DONTDRAW
					end
				else
					player.overlay.blendmode = 	AST_TRANSLUCENT
					player.overlay.colorized = player.mo.colorized
				end
				--if player.mo.colorized == true
					--player.overlay.colorized = true
			--	else
					--player.overlay.colorized = false
				--end
				--A_CapeChase(player.overlay)
				P_MoveOrigin(player.overlay, player.mo.x,player.mo.y,player.mo.eflags & MFE_VERTICALFLIP and player.mo.z+player.mo.height or player.mo.z)
				player.overlay.scale = player.mo.scale
				if player.overlaytimer == 0
					player.overlaytimer = 40
				end
				local transval = abs((player.overlaytimer-1)/2 - 10)
				local fflag = (transval < 10 and FF_TRANS10*transval) or 0
				if player.rushmode > 0
				and player.modernmenu.contents[4][1].value == 1
					if player.rushcolor == nil
						player.rushcolor = SKINCOLOR_ORANGE
					end
					if player.overlaytimer > 2
						player.overlay.color = player.rushcolor
						player.overlay.frame = player.mo.frame|fflag|FF_FULLBRIGHT
						if player.modernmenu.contents[4][2].value == 1
						and player.modernmenu.contents[4][3].value == 1
							player.overlay.colorized = true
						end
					else
						player.overlay.color = player.mo.color
						player.overlay.frame = player.mo.frame|fflag
						if player.mo.colorized == false
							player.overlay.colorized = false
						end
					end
				end
			end
			player.boostmeter = 117
			player.rushmode = $ - 1
		elseif player.rushmode == 1
		and not (player.playerstate == PST_DEAD)
			S_StartSound(player.mo, sfx_rslose)
			if player.usedboostduringrush == true
				player.boostmeter = 60
				player.usedboostduringrush = false
			else
				player.boostmeter = 116
			end
			player.rushmode = 0
			player.overlaytimer = 0
			if s.boostcashback
				p.boostmeter = $+s.boostcashback
				if p.boostmeter > 116
					p.boostmeter = 116
				end
				s.boostcashback = 0
			end
		end
		if player.stomping or P_IsObjectOnGround(player.mo) or player.lightdashing > 0
		or P_PlayerInPain(player) or (player.pflags & PF_SLIDING) or player.exiting != 0
		or player.powers[pw_carry] != CR_NONE or player.spectator
		or not player.playerstate == PST_LIVE
			player.tricking = false
			player.trickable = false
			player.trickcooldown = 0
		end
		if player.trickcooldown > 0
			player.trickcooldown = $1-1
		end
		if player.tricking == false
			player.trickcooldown = 0
		end
		--New Super Aura
		if player.powers[pw_super]

			--Golden Shine: Welp. Of course I'd take on the aura stuff. If I don't, who will?!
			--Merge this one with your own playerthinker for performance! Best put at the end.
	
			local aurax = P_RandomRange(-16, 16)*player.mo.scale --X and Y offsets continuously forced on the aura.
			local auray = P_RandomRange(-16, 16)*player.mo.scale 
			local auraz = P_RandomRange(0,16)*player.mo.scale+player.mo.momz
			if (player.mo.eflags & MFE_VERTICALFLIP) --Flip support.
			--auraz = $-(50*player.mo.scale)
			end
		
			local aura = P_SpawnMobjFromMobj(player.mo,
			aurax,
			auray,
			auraz,
			MT_MODERNSUPERAURA)
		
			aura.target = player.mo
			aura.aurax = aurax
			aura.auray = auray
			aura.eflags = player.mo.eflags
			aura.flags2 = player.mo.flags2
			aura.scale = (player.mo.scale*10)/P_RandomRange(10, 20)
			aura.scalespeed = ($*10)/P_RandomRange(12,23)
			aura.destscale = $*99
			aura.blendmode = AST_ADD
			aura.spritexscale = FRACUNIT+P_RandomRange(-5000,5000)
			if aura.target.player == displayplayer
				local chasecam = CV_FindVar("chasecam")
				if (chasecam.value == 1)
					aura.flags2 = $ & ~MF2_DONTDRAW
				elseif (chasecam.value == 0)
					aura.flags2 = $ | MF2_DONTDRAW
				end
			end
			if ((player.mo.color == SKINCOLOR_SUPER_SUNFLOWER1) or (player.mo.color == SKINCOLOR_SUPER_SUNFLOWER2) or (player.mo.color == SKINCOLOR_SUPER_SUNFLOWER3) or (player.mo.color == SKINCOLOR_SUPER_SUNFLOWER4) or (player.mo.color == SKINCOLOR_SUPER_SUNFLOWER5))
				aura.color = P_RandomRange(SKINCOLOR_SUPERORANGE2, SKINCOLOR_SUPERGOLD5)
			else
				aura.color = player.mo.color
			end
			aura.frame = P_RandomRange(0,4)|FF_TRANS70|FF_FULLBRIGHT
			
		end
		////////Super
		--Super Aura thing
		if (player.superanim and player.superanim >= 25)
			if player.supertransaura == nil
			--and player.superauratimer == 0
				player.supertransaura = P_SpawnMobjFromMobj(player.mo,0,0,0, MT_MODERNOVERLAY)
