				--if ((player.mo.color == SKINCOLOR_SUPER_SUNFLOWER1) or (player.mo.color == SKINCOLOR_SUPER_SUNFLOWER2) or (player.mo.color == SKINCOLOR_SUPER_SUNFLOWER3) or (player.mo.color == SKINCOLOR_SUPER_SUNFLOWER4) or (player.mo.color == SKINCOLOR_SUPER_SUNFLOWER5))
					if player.scolor
						if player.scolor == "advance"
							player.supertransaura.color = SKINCOLOR_SUPERADVANCEGOLD
						else
							player.supertransaura.color = player.scolor
						end
					else
						player.supertransaura.color = player.superauracolor --SKINCOLOR_SUPERGOLD3
					end
