					player.supertransaura.flags2 = $|MF2_DONTDRAW
				else
					player.supertransaura.flags2 = $ & ~MF2_DONTDRAW
				end
				--player.supertransaura.frame = player.mo.frame|FF_FULLBRIGHT|FF_TRANS30
				if player.superanim
					if player.superanim > 77
						player.supertransaura.frame = player.mo.frame|FF_FULLBRIGHT
					elseif player.superanim > 75
						player.supertransaura.frame = player.mo.frame|FF_FULLBRIGHT|FF_TRANS20
					elseif player.superanim > 70
						player.supertransaura.frame = player.mo.frame|FF_FULLBRIGHT|FF_TRANS30
					elseif player.superanim > 65
						player.supertransaura.frame = player.mo.frame|FF_FULLBRIGHT|FF_TRANS40
					elseif player.superanim > 55
						player.supertransaura.frame = player.mo.frame|FF_FULLBRIGHT|FF_TRANS50
					elseif player.superanim > 45
						player.supertransaura.frame = player.mo.frame|FF_FULLBRIGHT|FF_TRANS60
					elseif player.superanim > 35
						player.supertransaura.frame = player.mo.frame|FF_FULLBRIGHT|FF_TRANS70
					elseif player.superanim > 25
						player.supertransaura.frame = player.mo.frame|FF_FULLBRIGHT|FF_TRANS80
					end
				end
				P_MoveOrigin(player.supertransaura, player.mo.x,player.mo.y,player.mo.eflags & MFE_VERTICALFLIP and player.mo.z+player.mo.height or player.mo.z)
				player.supertransaura.angle = player.drawangle
			end
		end
		if not player.superanim 
		or (not player.powers[pw_super] and not player.supertrans)
			if player.supertransaura
				P_RemoveMobj(player.supertransaura)
				player.supertransaura = nil
			end
		end
		
