		if player.powers[pw_super]
			if player.modernmenu.contents[6][5].value == 1
				player.superaurasound = $+1
				if player.superaurasound >= 100
					player.superaurasound = 0
				end
				if not (S_SoundPlaying(player.mo, sfx_supaur))
					player.superaurasound = 1
				end
				if player.superaurasound == 1
				or not (S_SoundPlaying(player.mo, sfx_supaur))
					S_StartSoundAtVolume(player.mo, sfx_supaur, 155)
				end
			end
			if player.mo.state == S_PLAY_FLOAT
				player.mo.state = S_PLAY_FALL
			end
			player.powers[pw_sneakers] = 0
			player.powers[pw_invulnerability] = 0
		else
			player.superaurasound = 0
			if S_SoundPlaying(player.mo, sfx_supaur)
				S_StopSoundByID(player.mo, sfx_supaur)
			end
		end
		if player.modernmenu.contents[6][5].value == 0
			player.superaurasound = 0
			if S_SoundPlaying(player.mo, sfx_supaur)
				S_StopSoundByID(player.mo, sfx_supaur)
			end
		end
		if player.mo.state >= S_PLAY_MODERNTRANSFORM1
		and player.superanim -- > 0
		and player.mo.state ~= S_PLAY_BOREDOM
			if player.mo.state <= S_PLAY_MODERNTRANSFORM11
				player.pflags = $|PF_FULLSTASIS
				player.pflags = $ & ~PF_JUMPED
			end
			if player.mo.state <= S_PLAY_MODERNTRANSFORM6
				player.camerascale = $-500
			elseif player.mo.state >= S_PLAY_MODERNTRANSFORM7
				player.camerascale = FU*2
			end
		end
	
		if (player.mo.state >= S_PLAY_MODERNTRANSFORM1 and player.mo.state <= S_PLAY_MODERNTRANSFORM11)
			player.supertrans = true
		else
			player.supertrans = false
		end
		if player.supertrans 
			player.pflags = $|PF_FULLSTASIS
		end
		if player.mo.state == S_PLAY_SUPER_TRANS1 and not player.SolTransforming
			player.mo.state = S_PLAY_MODERNTRANSFORM1
		end
		if player.mo.state >= S_PLAY_MODERNTRANSFORM4 and player.mo.state <= S_PLAY_MODERNTRANSFORM6
		and player.supertrans == true
			if player.groundtransformation
				P_SetObjectMomZ(player.mo,3*FU, false)
				P_InstaThrust(player.mo,player.mo.angle,0)
			end
		end
		if player.mo.state >= S_PLAY_MODERNTRANSFORM4
		and not (player.groundtransformation)
		and player.supertrans == true
			P_SetObjectMomZ(player.mo,0, false)
			if leveltime % 2 == 0
				player.mo.momx = $ * 7/8
				player.mo.momy = $ * 7/8
			end
		end
		if player.supertrans == true and (player.mo.state >= S_PLAY_MODERNTRANSFORM6 and player.mo.state <= S_PLAY_MODERNTRANSFORM11)
			P_SetObjectMomZ(player.mo,0, false)
		end
		if not (player.powers[pw_super]) and not (player.mo.state >= S_PLAY_MODERNTRANSFORM1 and player.mo.state <= S_PLAY_MODERNTRANSFORM11)
			player.groundtransformation = false
		end
		
		--cancel transformation
		if player.superanim and not ( (player.mo.state >= S_PLAY_MODERNTRANSFORM1) and (player.mo.state <= S_PLAY_MODERNTRANSFORM11) )
			player.canceltransformation = true
		end
		-- BITCH!
		if player.mo.state == S_PLAY_MODERNTRANSFORM1
			player.mo.frame = A|FF_FULLBRIGHT
		elseif player.mo.state == S_PLAY_MODERNTRANSFORM2
			player.mo.frame = B|FF_FULLBRIGHT
		elseif player.mo.state == S_PLAY_MODERNTRANSFORM3
			player.mo.frame = C|FF_FULLBRIGHT
		elseif player.mo.state == S_PLAY_MODERNTRANSFORM4
			player.mo.frame = D|FF_FULLBRIGHT
		elseif player.mo.state == S_PLAY_MODERNTRANSFORM5
			player.mo.frame = E|FF_FULLBRIGHT
		elseif player.mo.state == S_PLAY_MODERNTRANSFORM6
			player.mo.frame = F|FF_FULLBRIGHT
		elseif player.mo.state == S_PLAY_MODERNTRANSFORM7
			player.mo.frame = G|FF_FULLBRIGHT
		elseif player.mo.state == S_PLAY_MODERNTRANSFORM8
			player.mo.frame = H|FF_FULLBRIGHT
		elseif player.mo.state == S_PLAY_MODERNTRANSFORM9
			player.mo.frame = I|FF_FULLBRIGHT
		elseif player.mo.state == S_PLAY_MODERNTRANSFORM10
			player.mo.frame = J|FF_FULLBRIGHT
		elseif player.mo.state == S_PLAY_MODERNTRANSFORM11
			player.mo.frame = K|FF_FULLBRIGHT 
		end
		if player.cmd.buttons & BT_CUSTOM2
		and not (player.powers[pw_super])
		and not (player.mo.state >= S_PLAY_SUPER_TRANS2 and player.mo.state <= S_PLAY_SUPER_TRANS6)
		and player.rings >= 50
		and player.custom2down == false
		and player.abilitylock == false
		and player.playerstate == PST_LIVE
		and not (P_PlayerInPain(player))
		and not (player.powers[pw_carry] == CR_NIGHTSMODE)
		and not (player.powers[pw_carry] == CR_ROLLOUT)
		and not (player.powers[pw_carry] == CR_GRINDRAIL)
		and not player.exiting
		and not (player.mysticsuper)
		and not player.modernmenu.show
		and not player.sliding
		and not player.customhoming
		and not player.manualdrifting
		and not player.nomovecounter
			if All7Emeralds(emeralds)
				player.custom2down = true
				player.can_super = true
				player.tricking = false
				become_super(player)
