				and player.modernmenu.contents[6][1].value == 1 -- Voices
				and not (player.mo.eflags & MFE_UNDERWATER)
					S_StartSound(player.mo, sfx_supjun)
				end
				--S_StartSound(player.mo, sfx_supjun)
				player.pflags = $ & ~PF_JUMPED
				if player.mo.state ~= S_PLAY_BOREDOM
					if P_IsObjectOnGround(player.mo)
						player.groundtransformation = true
						player.mo.state = S_PLAY_MODERNTRANSFORM1
					else
						player.mo.state = S_PLAY_MODERNTRANSFORM4
						player.mo.tics = 20
					end
				end
			end
		end
		if not (player.cmd.buttons & BT_CUSTOM2)
			player.custom2down = false
		end
		if player.active_supertrans == true
			player.mo.superfunnytable = A_PreSuper(player.mo)
		end
		if player.active_supertrans == true
		and (player.cmd.buttons & BT_CUSTOM2 or player.powers[pw_carry] == CR_ROLLOUT)
		and not (player.powers[pw_super])
		and player.custom2down == false
		or player.canceltransformation
			player.canceltransformation = false
			player.superanim = 0
			if P_IsObjectOnGround(player.mo)
				player.mo.state = S_PLAY_STND
			else
