			end
			player.custom2down = true
			player.active_supertrans = false
			
			S_StartSound(player.mo, sfx_mtranc)
			local colors = {
				SKINCOLOR_GREEN,
				SKINCOLOR_MAGENTA,
				SKINCOLOR_BLUE,
				SKINCOLOR_SKY,
				SKINCOLOR_ORANGE,
				SKINCOLOR_RED,
				SKINCOLOR_SILVER
			}
			for i = 0, 6				
				local bitch = player.mo.superfunnytable[i]
				local sparkle,ghost
				for j = 0, 8
					sparkle = P_SpawnMobjFromMobj(bitch, 0,0,0, MT_BOXSPARKLE)
					sparkle.rejectedsuper = true
					P_InstaThrust(sparkle, FixedAngle(P_RandomRange(0, 360)*FU), P_RandomRange(2, 5)*FU)
					P_SetObjectMomZ(sparkle, (P_RandomRange(5, 10)*FU), false)
					sparkle.color = colors[i+1]
					sparkle.colorized = true
					sparkle.scale = $/2
				end
				ghost = P_SpawnGhostMobj(bitch)
				ghost.blendmode = AST_ADD
			end
		end
		if player.playerstate == PST_DEAD
			player.active_supertrans = false
		end
		if player.powers[pw_super] == 0
			player.superboost = false
			player.supersong = nil 
		end
		if player.modernmenu.show
			--player.supersong = nil 
		end
		if player.powers[pw_super]
		and player.playerstate == PST_LIVE
		--and not (player.powers[pw_extralife])
		and not (player.pflags & PF_FINISHED)
		and player.lives ~= 0
		and not (player.powers[pw_underwater] <= 385 and player.powers[pw_underwater] > 0)
		and not player.modernmenu.show
			if player.modernmenu.contents[6][3].value == 0 -- SuperMusic
				if player.supersong == nil
				or player.supersong ~= player.modernmenu.contents[6][3].value
					player.supersong = player.modernmenu.contents[6][3].value
					P_PlayJingleMusic(player, "MSUPR1", nil, true, JT_SUPER)
				end
			elseif player.modernmenu.contents[6][3].value == 1 -- SuperMusic
				if player.supersong == nil
				or player.supersong ~= player.modernmenu.contents[6][3].value
					player.supersong = player.modernmenu.contents[6][3].value
					P_PlayJingleMusic(player, "MSUPR2", nil, true, JT_SUPER)
				end
			elseif player.modernmenu.contents[6][3].value == 2 -- SuperMusic
				if player.supersong == nil
				or player.supersong ~= player.modernmenu.contents[6][3].value
					player.supersong = player.modernmenu.contents[6][3].value
					P_PlayJingleMusic(player, "MSUPR3", nil, true, JT_SUPER)
				end
			elseif player.modernmenu.contents[6][3].value == 3 -- SuperMusic
				if player.supersong == nil
				or player.supersong ~= player.modernmenu.contents[6][3].value
					player.supersong = player.modernmenu.contents[6][3].value
					P_PlayJingleMusic(player, "MSUPR4", nil, true, JT_SUPER)
				end
			elseif player.modernmenu.contents[6][3].value == 4 -- SuperMusic
				if player.supersong == nil
				or player.supersong ~= player.modernmenu.contents[6][3].value
					player.supersong = player.modernmenu.contents[6][3].value
					P_PlayJingleMusic(player, "MSUPR5", nil, true, JT_SUPER)
				end
			elseif player.modernmenu.contents[6][3].value == 5 -- SuperMusic
				if player.supersong == nil
				or player.supersong ~= player.modernmenu.contents[6][3].value
					player.supersong = player.modernmenu.contents[6][3].value
					P_PlayJingleMusic(player, "MSUPR6", nil, true, JT_SUPER)
				end
			elseif player.modernmenu.contents[6][3].value == 6 -- SuperMusic
				if player.supersong == nil
				or player.supersong ~= player.modernmenu.contents[6][3].value
					player.supersong = player.modernmenu.contents[6][3].value
					P_PlayJingleMusic(player, "_SUPER", nil, true, JT_SUPER)
				end
			end
		end
		//Fire Sonic Aura
		if (player.powers[pw_shield] & SH_FIREFLOWER)
			if player.flameoverlay == nil
			
			--and player.fuck
				player.flameoverlay = P_SpawnMobjFromMobj(player.mo,0,0,0, MT_MODERNOVERLAY)
				player.flameoverlay.state = S_FIRESONICAURA
				player.flameoverlay.color = SKINCOLOR_RED
				player.flameoverlay.target = player.mo
				player.flameoverlay.scale = player.mo.scale/10
				player.flameoverlay.flags2 = player.mo.flags2
				player.flameoverlay.blendmode = AST_ADD
				--player.flameoverlay.spritexscale = player.mo.spritexscale
				--player.flameoverlay.spriteyscale = player.mo.spriteyscale
				--player.flameoverlay.spriteyoffset = player.mo.spriteyoffset
				--player.flameoverlay.eflags = player.mo.eflags
			elseif player.flameoverlay and player.flameoverlay.valid
				player.flameoverlay.color = SKINCOLOR_FLAME
				player.flameoverlay.target = player.mo
				player.flameoverlay.scale = player.mo.scale/10
				player.flameoverlay.flags2 = player.mo.flags2
				player.flameoverlay.blendmode = AST_ADD
				player.flameoverlay.dispoffset = -1
				if player.powers[pw_super]
					player.flameoverlay.spritexscale = player.mo.spritexscale*2
					player.flameoverlay.spriteyscale = player.mo.spriteyscale*13/10
				else
					player.flameoverlay.spritexscale = player.mo.spritexscale*3/2
					player.flameoverlay.spriteyscale = player.mo.spriteyscale*5/6
				end
				--player.flameoverlay.spriteyoffset = player.mo.spriteyoffset
				--player.flameoverlay.eflags = player.mo.eflags
				P_MoveOrigin(player.flameoverlay, player.mo.x,player.mo.y,player.mo.eflags & MFE_VERTICALFLIP and player.mo.z+player.mo.height or player.mo.z)
			end
		else
			if player.flameoverlay and player.flameoverlay.valid
				P_RemoveMobj(player.flameoverlay)
				player.flameoverlay = nil
			end
		end
		if (player.pflags & PF_SPINNING)
		and (P_IsObjectOnGround(player.mo) or player.boosting)
			player.thrustfactor = 50
		end
	end
end)
--Finally the end of the great ThinkFrame.


--Typing "mo" and "player" kills me inside, but for Motd's sanity....
addHook("MobjThinker", function(mo)
	if mo.target and mo.target.valid --No target, no game.
		local t = mo.target	
		mo.z = $+(t.scale*2*P_MobjFlip(mo))	--Rise, auraflame.	
		mo.spriteyscale = $+P_RandomRange(-50,900) --Vertical flickering
			if not mo.disengaged --Only follow if Sonic's going slow.
			P_MoveOrigin(mo, t.x+mo.aurax-(t.momx/3), t.y+mo.auray-(t.momy/3), mo.z +((mo.eflags & MFE_VERTICALFLIP) and mo.height or 0))
			end
			if (mo.tics % 5 == 0) --Get gradually more translucent
			mo.frame = $+FRACUNIT
			end
			if (mo.spritexscale > 200) --Thin out
			mo.spritexscale = $-200
			end
			if t.player and (t.player.speed > 50*mo.target.scale)
			mo.disengaged = true --Too fast. Disengage.
			end
	elseif mo.valid
		P_RemoveMobj(mo) --Die.
	end
end, MT_MODERNSUPERAURA)

addHook("MobjThinker", function(mo)
	if mo.tracer and mo.tracer.valid --No target, no game.
	and mo.tracer.flung
