local function ringEngine(special, toucher)
    if special and special.valid and toucher and toucher.valid and toucher.player and toucher.player.valid and toucher.skin == "modernsonic" then
        local player = toucher.player
        mobjinfo[special.type].deathsound = player.ringseq == 0 and sfx_itemu1 or player.ringseq == 1 and sfx_itemu2 or sfx_itemu3
        player.ringseq = $ + 1 //increase the sequence by 1
    else
        mobjinfo[special.type].deathsound = sfx_itemup
    end
end

for i = 1,#sound_engines do
    addHook("TouchSpecial", ringEngine, sound_engines[i])
end

addHook("AbilitySpecial", function(player)
	if player.mo.skin == "modernsonic"
	and (player.pflags & PF_JUMPED or player.stomping == true)
	and player.playerstate == PST_LIVE
	and player.hopdown == false
		player.justjumped = true
		player.usedown = true
		if player.customhoming == 0
		and player.rettarget and player.rettarget.valid and player.rettarget.health
		and not (player.rettarget.flags2 & MF2_FRET)
		and player.rettarget.type ~= MT_BIGMINE
		and player.rettarget.type ~= MT_EGGSHIELD
		and player.rettarget.type ~= MT_TNTBARREL
		and player.rettarget.type ~= MT_FAKEMOBILE
		and (player.rettarget.flags & MF_SHOOTABLE or player.rettarget.flags2 & MF2_INVERTAIMABLE or player.rettarget.flags & MF_SPRING or player.rettarget.type == MT_METALSONIC_BATTLE or player.rettarget.type == MT_NIGHTSBUMPER or player.rettarget.type == MT_PULLEYHANDLE)
		and not (player.rettarget and player.rettarget.state == S_METALSONIC_VECTOR)
-- 		and player.stomping == false
		and player.ret and player.ret.valid
		and player.modernmenu.contents[2][11].value == 1 --Homing Input
			if player.perfectCapable
				player.boostmeter = $ + 10
				S_IncrementModernChain(player.mo)
				player.doubledamage = true
				S_StartSound(player.mo, sfx_perfhm)
				if (player.modernmenu.contents[2][4].value == 1 and player == displayplayer) -- Quakes
					P_StartQuake(15*FRACUNIT, 5)
				end
			end
			player.thrustblock = 5
			if player.modernmenu.contents[2][5].value == 1 -- HomingCam
				player.camerascale = 7*FRACUNIT/2
			end
			player.stomping,player.stompdown,player.stomptimer = false,true,0
			player.customhoming = 3*TICRATE
			player.gotbonked = false
			if not (player.mo.eflags & MFE_UNDERWATER)
				if player.modernmenu.contents[10][9].value == 0
					S_StartSound(player.mo, sfx_ruthok)
				elseif player.modernmenu.contents[10][9].value == 1
					S_StartSound(player.mo, sfx_06thok)
				elseif player.modernmenu.contents[10][9].value == 2
					S_StartSound(player.mo, sfx_mthok)
				elseif player.modernmenu.contents[10][9].value == 3
					S_StartSound(player.mo, sfx_sdpzom)					
				end
			else
				if player.modernmenu.contents[10][9].value == 0
					S_StartSound(player.mo, sfx_ruthkw)
				elseif player.modernmenu.contents[10][9].value == 1
					S_StartSound(player.mo, sfx_06thkw)
				elseif player.modernmenu.contents[10][9].value == 2
					S_StartSound(player.mo, sfx_mthokw)
				elseif player.modernmenu.contents[10][9].value == 3
					S_StartSound(player.mo, sfx_sdpzmw)					
				end
			end
			if player.modernmenu.contents[6][1].value == 1 -- Voices
				if player.modernmenu.contents[6][2].value == 0
					PlayModernSound(player, 4)
				elseif player.modernmenu.contents[6][2].value == 1
					PlayModernSound(player, 16)
				elseif player.modernmenu.contents[6][2].value == 2
					PlayModernSound(player, 10)
				elseif player.modernmenu.contents[6][2].value == 3
					PlayModernSound(player, 22)
				elseif player.modernmenu.contents[6][2].value == 4
					PlayModernSound(player, 25)
				elseif player.modernmenu.contents[6][2].value == 5
					PlayModernSound(player, 26)
				end
			end
		elseif not (player.pflags & PF_THOKKED)
		and player.stomptimer == 0
		and player.customhoming == 0
		and player.modernmenu.contents[2][1].value ~= 0 -- Ability 
		--and player.mo.state ~= S_PLAY_AIRKICK
			player.dropdashdown = true
			player.finishedtrick = false
			player.jumpdown = true
			player.stomping = false
			if player.modernmenu.contents[2][1].value == 1 -- Jump Ability
				if player.powers[pw_shield] == SH_WHIRLWIND
					P_SetObjectMomZ(player.mo, (player.mo.eflags & MFE_UNDERWATER) and 5*FU or 10*FU, false)
					S_StartSound(player.mo, sfx_wdjump)
				else
					P_SetObjectMomZ(player.mo, (player.mo.eflags & MFE_UNDERWATER) and 4*FU or 8*FU, false)
				end
				if (player.mo.eflags & MFE_UNDERWATER)
					local bubble = P_SpawnMobj(player.mo.x, player.mo.y, player.mo.z, MT_UWEXPLODE)
					bubble.scale = player.mo.scale
				end
				if player.modernmenu.contents[10][1].value == 0 -- Jump Sound
					S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_jmpwt5 or sfx_mjump5)
				elseif player.modernmenu.contents[10][1].value == 2 -- Jump Sound
					S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_jmpwt7 or sfx_mjump7)
				elseif player.modernmenu.contents[10][1].value == 4 -- Jump Sound
					S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_2spnwr or sfx_2arspn)
				else
					S_StartSound(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_spnwtr or sfx_airspn)
				end
				
				
				if player.modernmenu.contents[10][1].value == 3 -- Jump Sound
					S_StartSoundAtVolume(player.mo, (player.mo.eflags & MFE_UNDERWATER) and sfx_jmpwt4 or sfx_mjump4, 100)
				end
				player.doublejumped = true
				player.pflags = $|PF_THOKKED
				if (player.mysticsuper)
				and (player.mo.eflags & MFE_UNDERWATER)
					player.doublejumped = false
					player.pflags = $ & ~PF_THOKKED
				end
				if player.speed > 15*FRACUNIT
				and not (player.mysticsuper)
					if not(player.powers[pw_shield] == SH_WHIRLWIND)
					and not (player.powers[pw_super])
						player.mo.momx = $*5/8
						player.mo.momy = $*5/8
					end
				end
				if player.speed > 55*player.mo.scale
					player.mo.modernjetspeed = 55*player.mo.scale
				else
					player.mo.modernjetspeed = player.speed
				end
				player.mo.state = S_PLAY_JUMP
				player.jumptimer = 4
				player.boosting = false
				--SpawnActionDust(player.mo, 1)
				local shockwave = P_SpawnMobjFromMobj(player.mo, 0, 0, 30*FRACUNIT, MT_MODERNSHOCKWAVE)
				shockwave.target = player.mo
				shockwave.color = player.mo.color
				shockwave.blendmode = AST_ADD
				shockwave.renderflags = RF_FLOORSPRITE
				shockwave.scale = player.mo.scale/2
				shockwave.destscale = player.mo.scale*3/5
				shockwave.scalespeed = FRACUNIT/50
			else
				player.gensdash = 10
				player.thrustblock = 5
				player.gotbonked = false
				player.pflags = $|PF_THOKKED
				if not (player.mo.eflags & MFE_UNDERWATER)
					if player.modernmenu.contents[10][9].value == 0
						S_StartSound(player.mo, sfx_ruthok)
					elseif player.modernmenu.contents[10][9].value == 1
						S_StartSound(player.mo, sfx_06thok)
					elseif player.modernmenu.contents[10][9].value == 2
						S_StartSound(player.mo, sfx_mthok)
					elseif player.modernmenu.contents[10][9].value == 3
						S_StartSound(player.mo, sfx_sdpzom)					
					end
				else
					if player.modernmenu.contents[10][9].value == 0
						S_StartSound(player.mo, sfx_ruthkw)
					elseif player.modernmenu.contents[10][9].value == 1
						S_StartSound(player.mo, sfx_06thkw)
					elseif player.modernmenu.contents[10][9].value == 2
						S_StartSound(player.mo, sfx_mthokw)
					elseif player.modernmenu.contents[10][9].value == 3
						S_StartSound(player.mo, sfx_sdpzmw)					
					end
			end
				if player.modernmenu.contents[6][1].value == 1 -- Voices
					if player.modernmenu.contents[6][2].value == 0
						PlayModernSound(player, 4)
					elseif player.modernmenu.contents[6][2].value == 1
						PlayModernSound(player, 16)
					elseif player.modernmenu.contents[6][2].value == 2
						PlayModernSound(player, 10)
					elseif player.modernmenu.contents[6][2].value == 3
						PlayModernSound(player, 22)
					elseif player.modernmenu.contents[6][2].value == 4
						PlayModernSound(player, 25)
					elseif player.modernmenu.contents[6][2].value == 5
						PlayModernSound(player, 26)
					end
				end
			end
		end	
		if player.modernmenu.contents[2][9].value ~= 0
			if player.modernmenu.contents[2][1].value == 0
			or player.modernmenu.contents[2][1].value == 1 and player.pflags & PF_THOKKED
			or (player.modernmenu.contents[2][1].value == 2 or player.modernmenu.contents[2][1].value == 3) and not player.gensdash
				player.dropdashable = true
			end
		end
	end
end)

--Boost aura itself's thinker.
addHook("MobjThinker", function(s)
	if s and (s.tics == 2) and s.target
		local t = s.target
		if (t.player.powers[pw_shield] == SH_ELEMENTAL or t.player.powers[pw_shield] == SH_FLAMEAURA or t.player.firesonic)
			s.color = SKINCOLOR_ORANGE
		else
			s.color = FindMyColor(t.player, SKINCOLOR_GOLDENROD, 1, "boost3")
		end
		s.frame = E|FF_FULLBRIGHT|FF_TRANS70
		--s.blendmode = AST_ADD
		if t.player.modernmenu.contents[5][5].value == 1
			s.blendmode = AST_ADD
		end
		s.scale = $*5/6
	end
end, MT_MSBOOSTAURA)

addHook("MobjThinker", function(mobj)
	if mobj and mobj.target
		mobj.rollangle = FixedAngle(mobj.target.momz*P_MobjFlip(mobj.target))
	end
end, MT_SPEEDLINE)

addHook("MobjThinker", function(mobj)
	if mobj and mobj.valid
		if mobj.state >= S_FAKEBUBBLE1
		and mobj.state <= S_FAKEBUBBLE4
			mobj.momz = FU*3/4
			mobj.momy = P_RandomRange(1, -1)*FU
			mobj.momx = P_RandomRange(1, -1)*FU
			if not (mobj.eflags & MFE_UNDERWATER)
			and not P_IsObjectOnGround(mobj)
				P_KillMobj(mobj)
			end
		end
	end
end, MT_FAKEDUST)

local function FlipObjectFromObject(mo, master)
	mo.flags2 = ($ & ~MF2_OBJECTFLIP) | (master.flags2 & MF2_OBJECTFLIP)
	mo.eflags = ($ & ~MFE_VERTICALFLIP) | (master.eflags & MFE_VERTICALFLIP)
end

addHook("MobjThinker", function(mo)
	if not mo.target return end --
    mo.lifetime = $ or 0
	FlipObjectFromObject(mo, mo.target)
	local flip = (P_MobjFlip(mo.target) == 1) and 0 or mo.target.height+(6*FU)
	local z = 6*mo.scale
	if mo.eflags & MFE_VERTICALFLIP
		z = -$ + mo.target.z + mo.target.height - mo.height
	else
		z = $ + mo.target.z
	end
	P_MoveOrigin(mo, mo.target.x + mo.momx, mo.target.y + mo.momy, z + mo.momz + ((mo.eflags & MFE_VERTICALFLIP) and mo.height or 0))
    mo.lifetime = $ + 1
	if mo.lifetime >= 15
		P_RemoveMobj(mo)
	elseif (mo.lifetime>=6)
		mo.frame =  $|((mo.lifetime-5)<<16)
	end
end, MT_TRICKSPARKLES)

addHook("MobjThinker", function(mo)
	if not mo.target return end --
    mo.lifetime = $ or 0
	FlipObjectFromObject(mo, mo.target)
	local flip = (P_MobjFlip(mo.target) == 1) and 0 or mo.target.height+(2*FU)
	local z = 2*mo.scale
	if mo.eflags & MFE_VERTICALFLIP
		z = -$ + mo.target.z + mo.target.height - mo.height
	else
		z = $ + mo.target.z
	end
	P_MoveOrigin(mo, mo.target.x + mo.momx, mo.target.y + mo.momy, z + mo.momz + ((mo.eflags & MFE_VERTICALFLIP) and mo.height or 0))
    mo.lifetime = $ + 1
	if mo.lifetime >= 10
		P_RemoveMobj(mo)
	else
		mo.frame = ($ & ~FF_TRANSMASK)|(mo.lifetime<<16)		
	end
end, MT_TRICKSPARKLESRING)

--New mobjthinker for MT_PLAYER specifically to make Modern Sonic's boost aura work.
addHook("MobjThinker", function(mobj)
	local player = mobj.player
	if player.mo and player.mo.boostpass2  //Modern Sonic's thinker is different from SMS', so he'll check for boostpass2 instead of just boostpass
		player.mo.boostpass2 = $-1
		if not (player.powers[pw_carry] == CR_MINECART)
			player.mo.msbaang = R_PointToAngle2(player.mo.x, player.mo.y, (player.mo.x+player.mo.momx), (player.mo.y+player.mo.momy))
		else
			player.mo.msbaang = player.drawangle
		end
		
		if not player.mo.bostframeswitch
			if not player.mo.bostframejs
				if player.mo.bostframe == nil or (player.mo.bostframe < 1)
					player.mo.bostframe = 3
				else
					player.mo.bostframe = $-1
				end
				player.mo.bostframejs = true
			else
				player.mo.bostframejs = false
			end
			player.mo.bostframeswitch = true
		else
			player.mo.bostframeswitch = false
		end
		
		--This is the third boost aura particle. It appears behind Modern Sonic, not the initial burst in front of him.
		
	//	player.mo.rollboostangle = $+FixedAngle(10*FRACUNIT)
		player.mo.baaie = P_SpawnMobjFromMobj(player.mo, 0, 0, 0, MT_MSBOOSTAURA) //player.mo.baaie is the boost aura object.
		player.mo.baaie.target = player.mo
		player.mo.baaie.momx = player.mo.momx/3
		player.mo.baaie.momy = player.mo.momy/3
		player.mo.baaie.momz = player.mo.momz/2
		player.mo.baaie.angle = player.mo.msbaang
		if player.mo.msflameboost
			player.mo.baaie.color = SKINCOLOR_ORANGE
		elseif player.mo.color == SKINCOLOR_UNLEASHED
			player.mo.baaie.bluee = true //With the Bluee property this will flicker into another color
			player.mo.baaie.color = FindMyColor(player, SKINCOLOR_GOLDENROD, 1, "boost1")
		else
			player.mo.baaie.color =  FindMyColor(player, SKINCOLOR_GOLDENROD, 1)
		end
		--player.mo.baaie.blendmode = AST_ADD
		if player.modernmenu.contents[5][5].value == 1
			player.mo.baaie.blendmode = AST_ADD
		end
		player.mo.baaie.scale = (player.mo.scale*10/13)+(FixedMul(P_RandomRange(15,14000), player.mo.scale))
		player.mo.baaie.scalespeed = $/2
		player.mo.baaie.destscale = player.mo.baaie.scalespeed+1
		
		player.mo.baaie.momz = $+FRACUNIT*2
		player.mo.baaie.frame = E|FF_FULLBRIGHT|FF_TRANS60
		player.mo.baaie.tics = 4
		if (player.mo.eflags & MFE_VERTICALFLIP)
			--player.mo.baaie.z = $-FixedMul(36*FRACUNIT, player.mo.baaie.scale)
		end
	end
end, MT_PLAYER)

//These next 2 hooks get rid of the SRB2 reticle (that redish arrow) and also makes it so only the player locking onto the enemy can see the reticle.
addHook("MobjThinker", function(marker)
	if not marker.valid then return end --
	if displayplayer and displayplayer.dontdisplaymarker==true or secondarydisplayplayer and secondarydisplayplayer.dontdisplaymarker==true
		marker.flags2 = $|MF2_DONTDRAW return true --
	end
end, MT_LOCKON)

local RRa = {} --What the Ring Range touches.
RRa[MT_RING] = "grab"
RRa[MT_COIN] = "grab"
RRa[MT_REDTEAMRING] = 1
RRa[MT_BLUETEAMRING] = 2

//Handles attracting rings
addHook("MobjMoveCollide", function(eb, item)
	if item and item.valid and (RRa[item.type]) and not item.soncattract
	and eb and eb.target and eb.z <= item.z + item.height*10 and eb.z + eb.height >= item.z
	and eb.target.valid and eb.target.player and P_CanPickupItem(eb.target.player) and not P_PlayerInPain(eb.target.player)
		if RRa[item.type]=="grab" or (RRa[item.type]==eb.target.player.ctfteam and G_GametypeHasTeams())
			item.soncattract = true
			item.target = eb.target
			item.ringchasetimer = 6*TICRATE
			if not eb.target.player.sonic_rings then eb.target.player.sonic_rings = {} end
			table.insert(eb.target.player.sonic_rings,item)
		end
	end
end, MT_RINGRANGE)

//Gives the player boost energy for killing enemies
addHook("MobjDeath", function(enemy, i, msonic)
	if not (msonic and msonic.skin=="modernsonic" and enemy and enemy.valid) return end --
	
	if (enemy.flags & (MF_ENEMY|MF_SHOOTABLE))
		if (enemy.type != MT_FOUNDYOUFAKER) and not (enemy.player) and not (enemy.flags & MF_BOSS) and not (enemy.flung)
			if not (msonic.valid and msonic.type == MT_PLAYER) return end --
			if msonic.player.customhoming > 0
				HandleHomingEnd(msonic, 0)
			end
			enemy.target = msonic
			SpawnBoostEnergy(enemy, 4, 1)
			if msonic.player.stomping == true
				msonic.player.stomping = true
				P_SetObjectMomZ(msonic, FixedMul(-50*FRACUNIT, msonic.scale))
			end
			if enemy.faker
				P_KillMobj(enemy.faker)
				enemy.faker = nil
			end
		end
	elseif enemy.type==MT_FLINGRING or enemy.type==MT_FLINGCOIN
		if not (msonic.valid and msonic.type == MT_PLAYER) return end --
		if msonic.player.boostmeter and msonic.player.boostmeter > 0
			msonic.player.boostmeter = $1-2
		end
	end
end)

local function RingShit(ring, mo)
	local player = mo.player
	if mo.skin == "modernsonic"
		player.lightdashcounter = 0
	end
end

local function BoostEnergy(boostenergy, mobj)
	local player = mobj.player
	if mobj.skin == "modernsonic"
		if boostenergy and boostenergy.valid
		and (boostenergy.type == MT_BOOSTENERGY)
		and boostenergy.boostchasetimer <= 6*TICRATE
		and boostenergy.target == mobj
			if mobj.player.rushmode > 0
				mobj.player.rushmode = $ + TICRATE/8
			end
			if mobj.player.powers[pw_super]
				if mobj.player.tricking == true
				and leveltime & 2
					P_GivePlayerRings(mobj.player, 1)
				end
			else
				mobj.player.boostmeter = $+2
			end
			mobj.player.boostregentimer = 0
			S_StartSound(mobj, sfx_engygn, mobj.player)
			P_KillMobj(boostenergy, mobj, mobj)
		end
	end
end


addHook("TouchSpecial", RingShit, MT_RING)
addHook("TouchSpecial", RingShit, MT_COIN)
addHook("TouchSpecial", RingShit, MT_BLUESPHERE)
addHook("TouchSpecial", RingShit, MT_FLINGRING)
addHook("TouchSpecial", BoostEnergy, MT_BOOSTENERGY)


addHook("MobjDamage", function(s, i, sonic)
    if sonic and sonic.skin=="modernsonic" and sonic.player and ((sonic.player.customhoming or 0) > 0)
		if (sonic.player.rettarget==s) and s.valid
			HandleHomingEnd(sonic, (s.type==MT_EGGMOBILE4) and 2 or 1)
		end
	end
end)

addHook("MobjDamage", function(sonic, enemy, enemy)
	if sonic and sonic.skin == "modernsonic"
		S_EndCombo(sonic)
		if sonic.player.modernmenu.contents[6][1].value == 1 -- Voices
			if sonic.player.modernmenu.contents[6][2].value == 0
				PlayModernSound(sonic.player, 27)
			elseif sonic.player.modernmenu.contents[6][2].value == 1
				PlayModernSound(sonic.player, 29)
			elseif sonic.player.modernmenu.contents[6][2].value == 2
				PlayModernSound(sonic.player, 30)
			elseif sonic.player.modernmenu.contents[6][2].value == 3
				PlayModernSound(sonic.player, 28)
			elseif sonic.player.modernmenu.contents[6][2].value == 4
				PlayModernSound(sonic.player, 25)
			elseif sonic.player.modernmenu.contents[6][2].value == 5
				PlayModernSound(sonic.player, 26)
			end
		end
		if sonic.player.rushmode > 0
			sonic.player.rushmode = 0
			sonic.player.boostmeter = 60
			S_StartSound(sonic, sfx_rslose)
		end
	end
end, MT_PLAYER)

//This just makes it so you dont get hurt by enemies while doing certain actions. 
addHook("ShouldDamage", function(target, inflictor, source, damage, damagetype)
	if (target.skin != "modernsonic") return end -- 
	
	if target.player.boosting == true
	or target.player.sliding == 1
	or target.state == S_PLAY_AIRBOOST
	or target.player.footsweepattack
	or target.player.lightdashing > 0
	or target.player.stomping == true
	or target.player.stompshake > 0
	or (target.player.customhoming > 0)
	or (((target.state >= S_PLAY_TRICKALT_1 and target.state <= S_PLAY_TRICKE_3) or (target.state == S_PLAY_HOPFALL and target.player.usedhomingattack == true)) and target.player.pflags & PF_JUMPED)
	or (inflictor and inflictor.valid and inflictor.flung)
	
		if (inflictor and inflictor.valid)
		and (inflictor.flags & MF_BOSS or inflictor.flags & MF_ENEMY)
			return false
		end
	end
	if target.player.doubledamage and not (target.player.footsweepattack)
	or ((target.player.phinvultime <= 5 and target.player.phinvultime and inflictor.type != 202) 
	or (target.player.phinvultime > 5 and inflictor.type == 202))
	and inflictor and inflictor.valid
		return false
	end
	if target.player.footsweepattack
	and inflictor
	and (inflictor.flags & MF_ENEMY
	or inflictor.flags & MF_BOSS
	or inflictor.type == MT_FACESTABBERSPEAR)
		return false
	end
end, MT_PLAYER)

local function DontKillStuff(player, thing)
	if player.mo.valid and player.mo.skin == "modernsonic" and player.mo.health
		if (player.boosting == true
		or player.sliding == 1
		or player.mo.state == S_PLAY_AIRBOOST
		or player.lightdashing > 0
		or player.stomping == true
		or player.stompshake > 0
		or player.powers[pw_super]
		or (player.customhoming > 0))
		and thing and thing.valid and (thing.flags & MF_ENEMY)
		and thing.health == 1
		and not thing.flung
			return false --
		end
	end
end
addHook("PlayerCanDamage", DontKillStuff)

addHook("MobjDamage", function(boss, sonic, sonic)
    if sonic and sonic.valid and sonic.skin == "modernsonic"
		if boss and boss.valid and boss.flags & MF_BOSS
			local checkVal = 1
			if sonic.player.doubledamage
				checkVal = 2
			end
			S_IncrementModernChain(sonic)
			if boss.health <= checkVal
			and sonic.player.bossperfect[boss.perfectID] == 1
				if sonic.player.modernmenu.contents[6][1].value == 1 -- Voices
				and not (sonic.eflags & MFE_UNDERWATER)
					if sonic.player.modernmenu.contents[6][2].value == 0
						S_StartSound(sonic, sfx_perjas)
					elseif sonic.player.modernmenu.contents[6][2].value == 1
						S_StartSound(sonic, sfx_perrog)
					elseif sonic.player.modernmenu.contents[6][2].value == 2
						S_StartSound(sonic, sfx_perrya)
					elseif sonic.player.modernmenu.contents[6][2].value == 3
						S_StartSound(sonic, sfx_perjun)
					elseif sonic.player.modernmenu.contents[6][2].value == 4
						S_StartSound(sonic, sfx_perfeg)	
					elseif sonic.player.modernmenu.contents[6][2].value == 5
						S_StartSound(sonic, sfx_perfea)	
					end
				end
				S_IncrementModernChain(sonic, 5, 99)
				sonic.player.bossperfect[boss.perfectID] = 0
				S_StartSound(sonic, sfx_bprfct)	
				SpawnFaker(boss, sonic.player)
			end
		end
	end
end)

--Let's try to make a more sophisticated system for Modern Sonic that accounts for the new ringspeed feature.

local function DumbassBossThinker(dumbass)
	if not (dumbass and dumbass.valid) return end --
	if dumbass.diedharder
		S_StopSound(dumbass)
	end
	if dumbass.type == MT_FANG
		dumbass.rollangle = 0		
	elseif dumbass.flung and not dumbass.diedharder
		dumbass.spriteyoffset = FixedRandom(-10, 10)
		dumbass.spritexoffset = FixedRandom(-10, 10)
		dumbass.rollangle = $/-10
		local ow = P_SpawnGhostMobj(dumbass)
		ow.color = SKINCOLOR_BLACK
		ow.colorized = true
		ow.fuse = 2
	end
end

local function DontSuperFlingThisFucker(target, inflictor, source, damage)
	if (target.flags & MF_ENEMY) and inflictor and (inflictor.skin=="modernsonic") and inflictor.player and (inflictor.player.powers[pw_super])
	and (target.health < 2) --and inflictor.player.speed >= FixedMul(10*FRACUNIT, inflictor.scale) and inflictor.player.stomping == false)
		return false --
	end	
end

local function GSAddonLoad(_)
	for type = 1,max(1, (#mobjinfo)-1) local INFO=mobjinfo[type] if INFO==nil or (SemiGlobal[type]) continue end --		
		if (INFO.flags & MF_BOSS) --For all objects with the MF_MONITOR flag, add a hook!
			SemiGlobal[type] = true
			addHook("BossThinker", DumbassBossThinker, type)
		end
		if (INFO.flags & MF_ENEMY) or type==MT_MINUS or type==MT_EGGGUARD
			SemiGlobal[type] = true
			addHook("ShouldDamage", DontSuperFlingThisFucker, type)
		end
	end
end

addHook("AddonLoaded", GSAddonLoad) --This hook makes sure to scan for new objects everytime a new mod is added.
GSAddonLoad(_) --Run the function once on initial load.


if GS_RAILS_SKINS==nil rawset(_G,"GS_RAILS_SKINS",{}) end --Make sure your own lump has this line too!

--Modern Sonic stats?
GS_RAILS_SKINS["modernsonic"] = {} 
local SKIN = GS_RAILS_SKINS["modernsonic"]

SKIN["GrindThinker"] = function(p, s, GS, rail)
	p.c3railhold = true
	local MX,MY,MZ = s.momx,s.momy,s.momz
	local TMOMZ = -s.momz
	if GS.grinding
		TMOMZ = s.z-GS.LastGrindZ
	end
	TMOMZ = s.z-GS.LastGrindZ
	for i = 1,2
		if i==2 
			s.momx,s.momy,s.momz = MX,MY,MZ break --Restore old momentum and move on!
		elseif GS.railspeed!=nil and GS.LastGrindZ!=nil
			P_InstaThrust(s, p.drawangle, GS.railspeed) --This little hack saves me from having to rewrite anything.
			s.momz = s.z-GS.LastGrindZ
		end
		local SPIN
		if (p.cmd.buttons & BT_CUSTOM1)
			SPIN = max(GS.railspin, GS.railc1) or 0
			if (SPIN >= 999<<16)
				SPIN = (GS.boosting or p.boosting) and 2 or 0
			end
		elseif not (GS.grinding and (GS.grinding < 3))
			GS.boosting = 0	
		end
		local SPEED = abs(GS.railspeed or 0) --The speed we're moving at.
		if not p.boostmeter
			GS.boosting = 0
			if p.boosting --Turn off the boost!
				--S_StartSoundAtVolume(nil, sfx_antiri, 65, p)
				--S_StartSoundAtVolume(nil, sfx_adderr, 85, p)				
				--S_StartSound(s, sfx_shattr)
				--EndBoost(p,s,yu,RB)
				p.boosting = false
			elseif SPIN
				GS.railc1,GS.railspin = 999<<16,999<<16
				if SPIN == 1
					if GS.railspeed and ((GS.grinding or 0) > 4) --Punishment for spamming boost without meter.
						GS.railspeed = $*6/7
					end
					--RB.notboosting = 0
					S_StartSound(s, sfx_s236)
				end
			end
		else
			if SPIN 
				GS.cantcrouch = 2 --Doesn't stack.
				GS.crouchgrind = false
				p.powers[pw_strong] = $|STR_HEAVY|STR_WALL  --We're currently boosting.
				--RB.cantboost = 0 --Always allow boosting on the rails so long as you have meter!
				/*
				RB.boosting = max(GS.boosting or 0, RB.boosting or 0)+1
				GS.boosting = RB.boosting --So the regular behaviour won't turn the boost off.
		
				if (RB.boosting < 5) --Beginning of the boost!
					YUSO.BoostBurst(s, 70000)
					YUSO.BoostBurst2(s)	
					local QUAKEPOWER =  min(80<<16, P_IsObjectOnGround(s) and SPEED/2 or SPEED)
					P_YuQuake(p, QUAKEPOWER, 4)
					if RB.boosting==1 and not ((s.flags2 & MF2_TWOD) or twodlevel)
						YUSO.BoostBurst(s, 79000, nil, nil, FF_TRANS40)
					end
				elseif (SPEED < 15*s.scale) --Way too slow. Cancel boost!
					GS.railspin,GS.railc1 = 99<<16,99<<16 continue --		
				end				
				if (SPEED > 32*s.scale) --Speeding along smoothly!
					local RNG = P_RandomRange(6250,29250)
					YUSO.BoostAura(s, 80250+RNG)
					RushGhost(s)
					YUSO.YuSpinTrail(p, s, yu)	
					yu.spintrailticket = nil	
				end */
				if not p.startboost
					if not (p.powers[pw_super])
						p.boostmeter = $ - 10
					end
					if p.modernmenu.contents[10][2].value == 2
						S_StartSound(s, (s.eflags & MFE_UNDERWATER) and sfx_wtbst2 or sfx_boost2)
					elseif p.modernmenu.contents[10][2].value == 3
					or p.modernmenu.contents[10][2].value == 4
						S_StartSound(p.mo, (s.eflags & MFE_UNDERWATER) and sfx_fwbst2 or sfx_fbost2)
					elseif p.modernmenu.contents[10][2].value == 0	
						S_StartSound(s, (s.eflags & MFE_UNDERWATER) and sfx_rwbst1 or sfx_rbost1)
					elseif p.modernmenu.contents[10][2].value == 1
						S_StartSound(p.mo, (p.mo.eflags & MFE_UNDERWATER) and sfx_06bstw or sfx_06bost)	
					end
					if p.modernmenu.contents[6][1].value == 1 -- Voices
						local SFX = p.modernmenu.contents[6][2].value
						if not (SFX)
							PlayModernSound(p, 2)
						elseif SFX == 1
							PlayModernSound(p, 14)
						elseif SFX == 2
							PlayModernSound(p, 8)
						elseif SFX == 3
							PlayModernSound(p, 20)
						elseif SFX == 4
							PlayModernSound(p, 25)
						elseif SFX == 5
							PlayModernSound(p, 26)
						end
					end
					p.boostshake = 8
					local boostshockwave = P_SpawnMobjFromMobj(s, 0, 0, 0, MT_BOOSTSHOCKWAVE)
					boostshockwave.target = s
					if p.powers[pw_super] or p.mysticsuper
						boostshockwave.color = s.color
					elseif (p.powers[pw_shield] == SH_ELEMENTAL or p.powers[pw_shield] == SH_FLAMEAURA or p.firesonic)
					and not (s.eflags & MFE_UNDERWATER)
					and p.powers[pw_super] == 0
						boostshockwave.color = SKINCOLOR_ORANGE
					else
						boostshockwave.color = FindMyColor(s.player, SKINCOLOR_GOLDENROD, 1, "boost1")
					end
					boostshockwave.scale = s.scale
					boostshockwave.momx = s.momx/2
					boostshockwave.momy = s.momy/2
					boostshockwave.momz = s.momz
					p.startboost = true
				end
				--Now determine boost drain!
				/*local DRAIN = 10
				if (RB.boosting > 35) --Keeping up your boost lowers drain
					DRAIN = (RB.boosting >= 70) and $-2 or $-1
				end
				if (p.rings>29) --Having many rings lower drains.
					DRAIN = (p.rings>119) and $-3 or (p.rings>59) and $-2 or $-1	
				end
				if p.powers[pw_sneakers] --Super Sneakers half the drain.
					DRAIN = $/2
				end
				RB.boostmeter = max($-DRAIN,0)*/
				p.boostcanceltimer = 10
				p.boosting = true
				p.boostheld = true
				p.superboost = false
				p.airboost = false
				local TOPSPEED = 82*s.scale --Determine boostspeed!
				local MINSPEED = 46*s.scale
				if p.powers[pw_super] 
					TOPSPEED = 100*s.scale
					MINSPEED = 59*s.scale			
				else
					if (s.eflags & MFE_UNDERWATER) and ((p.powers[pw_shield]&~SH_FIREFLOWER)!=SH_BUBBLEWRAP)
						TOPSPEED = 56*s.scale
						MINSPEED = 31*s.scale
					end
				end
				--Now thrust using GS.railspeed.
				if (TOPSPEED > p.boostspeed) --Our top speed decreased!
					p.boostspeed = max(TOPSPEED, $-(s.scale/4))
				elseif (TOPSPEED < p.boostspeed) and (SPEED < p.boostspeed)
					p.boostspeed = max(TOPSPEED, $-(MINSPEED/100))
				end
				if (SPEED < p.boostspeed)
					local MINBOOST = (p.boosting == false) and p.boostspeed/2 or p.boostspeed*2/3
					if (SPEED < MINBOOST) and GS.myrail
						GS.railspeed = MINBOOST*GS_RAILS.GrindFlip(s, GS.myrail, true) --Go at THIS minimum speed.
					end
					GS.railspeed = ($<0) and $-(MINSPEED/41) or $+(MINSPEED/41) --Now gradually accelerate.
					SPEED = abs(GS.railspeed)
				end
			--	print("RB.boosting:\x82"+RB.boosting+"\x80 p.boostspeed:\x84"+p.boostspeed/FRACUNIT+"\x80 GS.railspeed:\x88"+SPEED/FRACUNIT)
				
			else --Not holding SPIN, thus not boosting!
				p.startboost = false
				if p.boosting
				and not (p.boostheld)
					--EndBoost(p,s,yu,RB) 
					p.boosting = false
					GS.railc1,GS.railspin = 999<<16,999<<16
				end
			/*	if (abs(GS.railspeed) > 50*s.scale) and not (p.cmd.buttons & BT_TOSSFLAG)
					local ghs = RushGhost(s)
					ghs.dispoffset = 79
				end */
			end
		end
	end
	if p.boosting
		local AURA = p.modernmenu.contents[7][1].value -- Boost Aura
		if not (AURA)
			ModernSonicRebornBoost(s)
		elseif AURA == 1
		or AURA == 2
			ModernSonicGenerationsBoost(s)					
		elseif AURA == 3
			ModernSonicColorsBoost(s)					
		elseif AURA == 4
			ModernSonicRushBoost(s)
		elseif AURA == 5
			ModernSonicForcesBoost(s)
		elseif AURA == 7 
			ModernSonicOldBoost(s)
		elseif AURA == 8 
			ModernSonicRebornBoost(s)
			ModernSonicGenerationsBoost(s)
			ModernSonicColorsBoost(s)
			ModernSonicRushBoost(s)
			ModernSonicForcesBoost(s)
			ModernSonicOldBoost(s)
		end
	end
	local TMOMX,TMOMY = FixedMul(abs(GS.railspeed or 0), cos(p.drawangle)), FixedMul(abs(GS.railspeed or 0), sin(p.drawangle))
	if s.gensboostaura and s.gensboostaura.valid
		P_MoveOrigin(s.gensboostaura, s.x+TMOMX, s.y+TMOMY, s.z+TMOMZ)
	end
	if s.rushboostaura and s.rushboostaura.valid
		P_MoveOrigin(s.rushboostaura, s.x+TMOMX, s.y+TMOMY, s.z+TMOMZ)
	end
	if s.forcesboostaura and s.forcesboostaura.valid
		P_MoveOrigin(s.forcesboostaura, s.x+TMOMX, s.y+TMOMY, s.z+TMOMZ)
	end
end

