	SemiGlobal = network($) --Sync what's been added so far for netgame sanity.
	currentstarcolor = network($)
	currentstarcolor2 = network($) 
end)

--addHook("MusicChange", is in LUA_PREPOST now!

addHook("MobjThinker", function(s)
	if not (s and s.valid)
	or s.tracer and s.tracer.valid and (s.tracer.skin!="modernsonic")
		return
	end
	if s.tracer and s.tracer.valid and s.tracer.skin == "modernsonic" and s.tracer.player 
		if s.tracer.player.powers[pw_carry] == CR_ROLLOUT
			local p = s.tracer.player
			local t = s.tracer 
			if (((p.cmd.buttons & BT_USE) and p.modernmenu.contents[2][2].value == 1) or ((p.cmd.buttons & BT_CUSTOM1) and p.modernmenu.contents[2][2].value == 0)) -- Actionswap
			and p.boostmeter > 0
				if p.powers[pw_super] == 0
					p.boostdecrease = $1+1
				end
				if p.boostmeter > 0
				and (p.boostdecrease >= 3)
					p.boostmeter = $ - 1
					p.boostdecrease = 0
				end
				P_Thrust(s, p.drawangle+ANGLE_180, 20*FRACUNIT)
				t.state = S_PLAY_BOOSTRUN
				p.pflags = $|PF_JUMPED
				
				//p.drawangle = t.angle+ANGLE_180
				if (s.eflags & MFE_UNDERWATER)
					P_SetObjectMomZ(s, FRACUNIT*4, true)
					P_SetObjectMomZ(t, FRACUNIT*4, true)
				end
				if not p.boostheld
					p.boostheld = true
				else
					if p.modernmenu.contents[7][1].value == 0 -- Boost Aura
						ModernSonicRebornBoost(t)
					elseif p.modernmenu.contents[7][1].value == 1 -- Boost Aura
					or p.modernmenu.contents[7][1].value == 2 -- Boost Aura
						ModernSonicGenerationsBoost(t)					
					elseif p.modernmenu.contents[7][1].value == 3 -- Boost Aura
						ModernSonicColorsBoost(t)					
					elseif p.modernmenu.contents[7][1].value == 4 -- Boost Aura
						ModernSonicRushBoost(t)
					elseif p.modernmenu.contents[7][1].value == 5 -- Boost Aura
						ModernSonicForcesBoost(t)
					elseif p.modernmenu.contents[7][1].value == 7 -- Boost Aura
						ModernSonicOldBoost(t)
					elseif p.modernmenu.contents[7][1].value == 8 -- Boost Aura
						ModernSonicRebornBoost(t)
						ModernSonicGenerationsBoost(t)
						ModernSonicColorsBoost(t)
						ModernSonicRushBoost(t)
						ModernSonicForcesBoost(t)
						ModernSonicOldBoost(t)
					end
				end
				if t.player.firesonic
					FireSonicFireSpawn(t.player)
				end
				if	not (p.rockringattract) 
					p.rockringattract = P_SpawnMobj(t.x + t.momx, t.y+ t.momy, t.z + t.momz + t.height/2 - 80*t.scale, MT_RINGRANGE)
					p.rockringattract.scale = (p.sonic_ringcharge and 2 or 1)*t.scale
					p.rockringattract.height = $*(p.powers[pw_super] and 2 or 1)
					p.rockringattract.radius = $*(p.powers[pw_super] and 2 or 1)
					p.rockringattract.target = t
				elseif p.rockringattract and p.rockringattract.valid
					P_MoveOrigin(p.rockringattract, t.x, t.y, t.z)
				end
				if not (p.boostmobj3 and p.boostmobj3.valid) then
					p.boostmobj3 = P_SpawnMobj(t.x, t.y, t.z, MT_GFZFLOWER1)
					p.boostmobj3.flags2 = $|MF2_DONTDRAW
					
					if not (t.eflags & MFE_UNDERWATER)
						if p.modernmenu.contents[10][2].value == 2
						or p.modernmenu.contents[10][2].value == 3
							S_StartSound(p.boostmobj3, sfx_boost3)
						elseif p.modernmenu.contents[10][2].value == 4
						and (p.modernmenu.contents[7][2].value == 1
						or (p.modernmenu.contents[7][2].value == 2 and p.rushmode))
							S_StartSound(p.boostmobj3, sfx_fbost3)
						end
					else
						if p.modernmenu.contents[10][2].value == 2
						or p.modernmenu.contents[10][2].value == 3
							S_StartSound(p.boostmobj3, sfx_wtbst3)
						elseif p.modernmenu.contents[10][2].value == 4
						and (p.modernmenu.contents[7][2].value == 1
						or (p.modernmenu.contents[7][2].value == 2 and p.rushmode))
							S_StartSound(p.boostmobj3, sfx_fwbst3)
						end
					end
					
					P_MoveOrigin(p.boostmobj3, t.x, t.y, t.z)
				elseif (p.boostmobj3 and p.boostmobj3.valid)
					P_MoveOrigin(p.boostmobj3, t.x, t.y, t.z)
					if p.modernmenu.contents[10][2].value == 4
					and (p.modernmenu.contents[7][2].value == 1
					or (p.modernmenu.contents[7][2].value == 2 and p.rushmode))
						if not (t.eflags & MFE_UNDERWATER)
							if not (S_SoundPlaying(p.boostmobj3, sfx_fbost3))
							and not (S_SoundPlaying(p.boostmobj3, sfx_fbost4))
								S_StartSound(p.boostmobj3, sfx_fbost4)
							end
						else
							if not (S_SoundPlaying(p.boostmobj3, sfx_fwbst4))
							and not (S_SoundPlaying(p.boostmobj3, sfx_fwbst4))
								S_StartSound(p.boostmobj3, sfx_fwbst4)
							end
						end
					end
				end
				if not (p.boostmobj4 and p.boostmobj4.valid) then
					p.boostmobj4 = P_SpawnMobj(t.x, t.y, t.z, MT_GFZFLOWER1)
					p.boostmobj4.flags2 = $|MF2_DONTDRAW
					P_MoveOrigin(p.boostmobj4, t.x, t.y, t.z)
				elseif (p.boostmobj4 and p.boostmobj4.valid)
					if p.modernmenu.contents[10][2].value != 0
					and p.modernmenu.contents[10][2].value != 1
						if not (p.mo.eflags & MFE_UNDERWATER)
							if not (S_SoundPlaying(p.boostmobj2, sfx_boost4))
								S_StartSound(p.boostmobj2, sfx_boost4)
							end
						else
							if not (S_SoundPlaying(p.boostmobj2, sfx_wtbst4))
								S_StartSound(p.boostmobj2, sfx_wtbst4)
							end
						end
					end
					P_MoveOrigin(p.boostmobj4, t.x, t.y, t.z)
				end
				if not s.modernsoundplayed
					P_InstaThrust(s, t.angle, 20*FRACUNIT)
					if not (p.powers[pw_super])
						p.boostmeter = $ - 10
					end
					if p.modernmenu.contents[10][2].value == 2
						S_StartSound(p.mo, (p.mo.eflags & MFE_UNDERWATER) and sfx_wtbst2 or sfx_boost2)
					elseif p.modernmenu.contents[10][2].value == 4
					or p.modernmenu.contents[10][2].value == 3
						S_StartSound(p.mo, (p.mo.eflags & MFE_UNDERWATER) and sfx_fwbst2 or sfx_fbost2)
					elseif p.modernmenu.contents[10][2].value == 0	
						S_StartSound(p.mo, (p.mo.eflags & MFE_UNDERWATER) and sfx_rwbst1 or sfx_rbost1)
					elseif p.modernmenu.contents[10][2].value == 1
						S_StartSound(p.mo, (p.mo.eflags & MFE_UNDERWATER) and sfx_06bstw or sfx_06bost)
					end
					if p.modernmenu.contents[6][1].value == 1 -- Voices
						if p.modernmenu.contents[6][2].value == 0
							PlayModernSound(p, 2)
						elseif p.modernmenu.contents[6][2].value == 1
							PlayModernSound(p, 14)
						elseif p.modernmenu.contents[6][2].value == 2
							PlayModernSound(p, 8)
						elseif p.modernmenu.contents[6][2].value == 3
							PlayModernSound(p, 20)
						elseif p.modernmenu.contents[6][2].value == 4
							PlayModernSound(p, 25)
						elseif p.modernmenu.contents[6][2].value == 5
							PlayModernSound(p, 26)
						end
					end
					p.boostshake = 8
					local boostshockwave = P_SpawnMobjFromMobj(t, 0, 0, 0, MT_BOOSTSHOCKWAVE)
					boostshockwave.target = t
					if p.powers[pw_super]
					or p.mysticsuper
						boostshockwave.color = t.color
					elseif (p.powers[pw_shield] == SH_ELEMENTAL or p.powers[pw_shield] == SH_FLAMEAURA or p.firesonic)
					and not (s.eflags & MFE_UNDERWATER)
					and p.powers[pw_super] == 0
						boostshockwave.color = SKINCOLOR_ORANGE
					else
						boostshockwave.color = FindMyColor(t.player, SKINCOLOR_GOLDENROD, 1, "boost1")
					end
					boostshockwave.scale = t.scale
					boostshockwave.momx = t.momx/2
					boostshockwave.momy = t.momy/2
					boostshockwave.momz = t.momz
					s.modernsoundplayed = true
				end
			else
				if p.rockringattract and p.rockringattract.valid
					P_RemoveMobj(p.rockringattract)
					p.rockringattract = nil
				end
				if (p.pflags & PF_JUMPED)			
					p.pflags = $ & ~PF_JUMPED & ~PF_STARTJUMP & ~PF_SPINNING
				end
				if t.state == S_PLAY_BOOSTRUN
					t.state = S_PLAY_WALK
					p.pflags = $ & ~PF_JUMPED & ~PF_STARTJUMP & ~PF_SPINNING
				end
				if s.modernsoundplayed
					s.modernsoundplayed = false
				end
				if (p.boostmobj3 and p.boostmobj3.valid)
					S_StopSound(p.boostmobj3)
					P_RemoveMobj(p.boostmobj3)
				end
				if (p.boostmobj4 and p.boostmobj4.valid)
					S_StopSound(p.boostmobj4)
					P_RemoveMobj(p.boostmobj4)
				end
			end
		end
	elseif s.tracer
		s.tracer.target = s
		s.flags = $|MF_PUSHABLE
		s.tracer = nil
	end
end, MT_ROLLOUTROCK)

//Prevent a sigsev.
addHook("MobjRemoved", function(s)
	if s and s.tracer and s.tracer.valid and s.tracer.player and (s.tracer.player.powers[pw_carry] == CR_ROLLOUT)
		s.tracer.player.powers[pw_carry] = 0
		s.tracer = nil
		s.flags = $|MF_PUSHABLE
		return --
	end
end, MT_ROLLOUTROCK)

